  ui_story_5014_50140101_56_dialog_content = "Apa ini?",
  ui_story_5014_50140101_57_dialog_content = "Ini detektor Illumina. Benda ini bisa mendeteksi energi yang tidak normal. Dengan inilah aku menemukan Colossus-mu dulu.",
  ui_story_5014_50140101_58_dialog_content = "Aku ingin menggunakannya untuk mendeteksi arah sinyal itu...",
  ui_story_5014_50140101_59_dialog_content = "Tapi, sama sekali tak bereaksi.",
  ui_story_5014_50140101_60_dialog_content = "Sekarang kita harus bagaimana?",
  ui_story_5014_50140101_61_dialog_content = "Kita pakai cara tradisional saja–kita periksa setiap jengkal wilayah dalam jangkauan koordinat.",
  ui_story_5014_50140101_62_dialog_content = "Vice, PlayerName, lihat ini.",
  ui_story_5014_50140101_63_dialog_content = "Besar sekali celah itu!",
  ui_story_5014_50140101_64_dialog_content = "Kenapa tiba-tiba ada celah besar di sini? Sepertinya juga tak ada dasarnya...",
  ui_story_5014_50140101_65_dialog_content = "Saat kita di Northland, kudengar belakangan <color=#FFB400>banyak terjadi gempa bumi</color> di sekitar pegunungan ini.",
  ui_story_5014_50140101_66_dialog_content = "Mungkin itu disebabkan oleh pergerakan lempeng tektonik atau semacamnya... Aku kurang paham hal-hal seperti itu.",
