  ui_story_5014_50140101_68_dialog_content = "Siapa yang bakal jatuh ke dalam celah yang jelas kelihatan seperti itu...",
  ui_story_5014_50140101_69_dialog_content = "Halo? Apa ada orang? Apa ada yang di bawah sana?",
  ui_story_5014_50140101_70_dialog_content = "Vice, kamu...?",
  ui_story_5014_50140101_71_dialog_content = "Eh, aku hanya mengira, anu, mungkin...",
  ui_story_5014_50140101_72_dialog_content = "Mungkin benar-benar ada orang yang jatuh ke sana dan mengirim sinyal bahaya... seperti aku...",
  ui_story_5014_50140101_73_dialog_content = "Saat pertama kalinya aku bertemu Vice, dia jatuh dari permukaan karena ceroboh.",
  ui_story_5014_50140101_74_dialog_content = "Itu kecelakaan, kok! Bukan karena aku ceroboh!",
  ui_story_5014_50140101_75_dialog_content = "Selain itu, mungkin mereka tidak jatuh! Mungkin mereka sengaja masuk ke dalamnya untuk menyelidiki sesuatu.",
  ui_story_5014_50140101_76_dialog_content = "Menyelidiki apa?",
  ui_story_5014_50140101_77_dialog_content = "Anu... tambang bawah tanah atau sumber air?",
