  ui_story_5014_50140101_79_dialog_content = "...",
  ui_story_5014_50140101_80_dialog_content = "Aku tak bisa mendengar atau merasakan siapa pun.",
  ui_story_5014_50140101_81_dialog_content = "Kalau begitu, ayo kita periksa di tempat lain...",
  ui_story_5014_50140101_82_dialog_content = "Tunggu dulu! Communicator milikku berbunyi!",
  ui_story_5014_50140101_83_dialog_content = "Jadi, sinyal itu memang berasal dari sana...",
  ui_story_5014_50140101_84_dialog_content = "<color=#e8d9bb>Gruk!</color>",
  ui_story_5014_50140101_85_dialog_content = "Gawat! Menyingkir dari celah itu sekarang!",
  ui_story_5014_50140101_86_dialog_content = "Ada gempa bumi!!!",
  ui_story_5014_50140101_87_dialog_content = "<color=#e8d9bb>Duar!</color>",
  ui_story_5014_50140201_1_dialog_content = "Bangun... PlayerName... Carleen!",
  ui_story_5014_50140201_2_dialog_content = "Aduh... Kepalaku sakit... Sekujur tubuhku sakit...",
  ui_story_5014_50140201_3_dialog_content = "PlayerName, akhirnya kamu siuman! Ada yang sakit?!",
  ui_story_5014_50140201_4_dialog_content = "Aduh! Aku tidak apa-apa, berhenti menampar wajahku...",
  ui_story_5014_50140201_5_dialog_content = "Maaf! Penglihatanku kabur... Ada yang sakit? Lukamu parah tidak?",
  ui_story_5014_50140201_6_dialog_content = "Ini hanya luka gores. Kalian berdua baik-baik saja?",
  ui_story_5014_50140201_7_dialog_content = "Aku baik-baik saja, tapi Carleen... D-dia terluka saat melindungimu.",
  ui_story_5014_50140201_8_dialog_content = "Kakiku hanya terluka sedikit. Jangan khawatir.",
  ui_story_5014_50140201_9_dialog_content = "Ada apa?",
  ui_story_5014_50140201_10_dialog_content = "Tadi tiba-tiba ada gempa bumi. Tanahnya runtuh, lalu kita semua jatuh ke dalam celah.",
