  ui_story_5014_50140201_13_dialog_content = "Benar, kita jatuh ke dalam gua bawah tanah.",
  ui_story_5014_50140201_14_dialog_content = "Gua ini lumayan besar. Aku ingin tahu ke mana gua ini mengarah.",
  ui_story_5014_50140201_15_dialog_content = "Bagaimana kalau kita kembali lewat jalan masuk tadi?",
  ui_story_5014_50140201_16_dialog_content = "Sudah kami coba, tapi jalannya terhalang tanah longsor.",
  ui_story_5014_50140201_17_dialog_content = "Kita tidak bisa kembali lewat jalan yang tadi.",
  ui_story_5014_50140201_18_dialog_content = "Akan kucoba memanggil Soroz.",
  ui_story_5014_50140201_19_dialog_content = "...",
  ui_story_5014_50140201_20_dialog_content = "Gagal. Tidak ada jawaban.",
  ui_story_5014_50140201_21_dialog_content = "Kami juga sudah mencoba menghubungi Illumina dan Colossus dengan Communicator, tapi gagal.",
  ui_story_5014_50140201_22_dialog_content = "Aku menduga ada bidang energi khusus yang membuat sistem komunikasi terganggu.",
  ui_story_5014_50140201_23_dialog_content = "Energi itu memengaruhi sinyal dari Illuminan dan detektorku.",
  ui_story_5014_50140201_24_dialog_content = "Berarti... sekarang kita terjebak di bawah tanah.",
  ui_story_5014_50140201_25_dialog_content = "Maaf, ini semua salahku.",
  ui_story_5014_50140201_26_dialog_content = "Jangan menyalahkan diri. Tak ada yang mengira bakal seperti ini.",
  ui_story_5014_50140201_27_dialog_content = "Kamu hanya ingin menjelajahi apa yang kita temui.",
  ui_story_5014_50140201_28_dialog_content = "Mungkin beginilah cara orang-orang yang mengirim sinyal itu juga terjebak di bawah tanah.",
  ui_story_5014_50140201_29_dialog_content = "Bagaimana kalau kita berjalan mengikuti gua ini saja? Mungkin kita bisa bertemu orang lain.",
  ui_story_5014_50140201_30_dialog_content = "Benar, niatku juga begitu.",
  ui_story_5014_50140201_31_dialog_content = "Kalau kita bertemu orang lain, peluang untuk keluar dari sini makin besar.",
  ui_story_5014_50140201_32_dialog_content = "Lagi pula, makin banyak orang yang kita temui, makin baik.",
  ui_story_5014_50140201_33_dialog_content = "Medan di sekitar sini sebagian besar berupa tundra pegunungan.",
  ui_story_5014_50140201_34_dialog_content = "Kalau beruntung, kita bisa keluar jika gua ini langsung mengarah ke lembah atau dataran,",
  ui_story_5014_50140201_35_dialog_content = "Tapi, Carleen terluka... Ayo kita beristirahat sebentar.",
  ui_story_5014_50140201_36_dialog_content = "Sudah kubilang ini bukan luka serius. Sebaiknya kita bergegas.",
  ui_story_5014_50140201_37_dialog_content = "Kalau begitu, biar kubantu. Di sini sangat gelap. Hati-hati.",
  ui_story_5014_50140201_38_dialog_content = "Biar aku yang jalan di depan karena indraku tajam.",
  ui_story_5014_50140201_39_dialog_content = "<color=#e8d9bb>Kresek, kresek.</color>",
  ui_story_5014_50140201_40_dialog_content = "Vice, Carleen, lihat!",
  ui_story_5014_50140201_41_dialog_content = "Itu lampu? Tapi, sepertinya rusak...",
  ui_story_5014_50140201_42_dialog_content = "Ini Searchlight Illumina! Pasti ada orang yang pernah kemari!",
  ui_story_5014_50140201_43_dialog_content = "Ayo jalan terus.",
  ui_story_5014_50140201_44_dialog_content = "<color=#e8d9bb>Kresek, kresek.</color>",
  ui_story_5014_50140201_45_dialog_content = "Huff... Huff... Harus jalan berapa lama lagi, nih? Sekarang aku hampir tak bisa berjalan...",
  ui_story_5014_50140201_46_dialog_content = "Apa benar-benar ada orang yang pernah kemari? Kita belum melihat tanda-tanda keberadaan seseorang selain lampu rusak itu.",
  ui_story_5014_50140201_47_dialog_content = "Aku juga tidak tahu... Ayo kita istirahat dulu.",
  ui_story_5014_50140201_48_dialog_content = "Sebentar, aku merasa udaranya bergerak... Asalnya dari depan!",
  ui_story_5014_50140201_49_dialog_content = "Biar kuperiksa!",
  ui_story_5014_50140201_50_dialog_content = "PlayerName, dinding batu ini menuju ke atas... Ada cahaya di sana!",
  ui_story_5014_50140201_51_dialog_content = "Itu pasti pintu keluarnya! Carleen, pintu keluarnya ketemu!",
  ui_story_5014_50140201_52_dialog_content = "Bagus...",
  ui_story_5014_50140201_53_dialog_content = "Carleen, biar kubantu. Hati-hati... Ayo naik.",
  ui_story_5014_50140201_54_dialog_content = "Sini, aku juga mau membantu.",
  ui_story_5014_50140201_55_dialog_content = "<color=#e8d9bb>Kresek, kresek.</color>",
  ui_story_5014_50140201_56_dialog_content = "Sepertinya ada penutupnya di atas sana!",
  ui_story_5014_50140201_57_dialog_content = "Penutup? Berarti ada orang yang membuatnya... Mungkin orang yang kita cari ada di sana!",
  ui_story_5014_50140201_58_dialog_content = "PlayerName, akan kupikirkan cara untuk membukanya...",
  ui_story_5014_50140201_59_dialog_content = "<color=#e8d9bb>Kriek... Krak...</color>",
  ui_story_5014_50140201_60_dialog_content = "<color=#e8d9bb>Wuuss...</color>",
  ui_story_5014_50140201_61_dialog_content = "Ini...",
  ui_story_5014_50140201_62_dialog_content = "Di mana kita?!",
  ui_story_5014_50140201_63_dialog_content = "Vice... Apa aku bermimpi?",
  ui_story_5014_50140201_64_dialog_content = "T-tenang, Carleen.",
  ui_story_5014_50140201_65_dialog_content = "Hangat sekali di sini... langitnya juga sangat cerah...",
  ui_story_5014_50140201_66_dialog_content = "Anginnya bahkan bertiup sepoi-sepoi...",
  ui_story_5014_50140201_67_dialog_content = "Kurasa...",
  ui_story_5014_50140201_68_dialog_content = "PlayerName, apa kamu lihat bangunan tinggi ini?",
  ui_story_5014_50140201_69_dialog_content = "Iya... Kita tidak bermimpi, 'kan...?",
  ui_story_5014_50140201_70_dialog_content = "Aku... belum pernah melihat tempat yang seperti ini di Northland.",
  ui_story_5014_50140201_71_dialog_content = "Aku akan menjelajahinya!",
  ui_story_5014_50140201_72_dialog_content = "<color=#e8d9bb>Klik... Klik...</color>",
  ui_story_5014_50140201_73_dialog_content = "Sebentar, Vice. Ada suara bising yang aneh dari sebelah sana.",
  ui_story_5014_50140201_74_dialog_content = "Sesuatu yang aneh mendekat. Bersiaplah.",
  ui_story_5014_50140201_75_dialog_content = "<color=#e8d9bb>Klik... Klik...</color>",
  ui_story_5014_50140201_76_dialog_content = "Apa ini?",
  ui_story_5014_50140201_77_dialog_content = "Bip... Bip...",
  ui_story_5014_50140201_78_dialog_content = "Sepertinya ini peralatan yang mencurigakan.",
  ui_story_5014_50140201_79_dialog_content = "Selain itu, ia terus mengeluarkan bunyi yang aneh.",
  ui_story_5014_50140201_80_dialog_content = "Ayo kita menjauh.",
  ui_story_5014_50140201_81_dialog_content = "Itu robot.",
  ui_story_5014_50140201_82_dialog_content = "Tapi, itu tidak sama dengan robot dari Illumina...",
  ui_story_5014_50140201_83_dialog_content = "Aku jadi teringat pada Firefly di Colossus. Rasanya kok agak mirip.",
  ui_story_5014_50140201_84_dialog_content = "Bersiaplah untuk pemeriksaan.",
  ui_story_5014_50140201_85_dialog_content = "Robot itu bisa mengeluarkan bunyi-bunyian dan bahkan menembakkan sinar!",
  ui_story_5014_50140201_86_dialog_content = "Jangan khawatir, katanya ia ingin \"memeriksa\" kita.",
  ui_story_5014_50140201_87_dialog_content = "Jadi pergerakannya dan pancaran pemindaian itu seharusnya hanya bagian dari pemeriksaan.",
  ui_story_5014_50140201_88_dialog_content = "Bagaimana caranya memindai kita? Aku ingin melihat lebih jelas...",
  ui_story_5014_50140201_89_dialog_content = "Peringatan! Peringatan! Orang-orang mencurigakan yang melanggar <color=#FFB400>aturan berpakaian</color> telah ditemukan.",
  ui_story_5014_50140201_90_dialog_content = "Mengambil tindakan untuk mengalahkan dan menangkap mereka!",
  ui_story_5014_50140201_91_dialog_content = "Vice, PlayerName, menjauh dari benda itu!",
  ui_story_5014_50140202_1_dialog_content = "<color=#e8d9bb>Duar!</color>",
  ui_story_5014_50140202_2_dialog_content = "Ups, tak sengaja merusaknya.",
  ui_story_5014_50140202_3_dialog_content = "Kenapa dia tiba-tiba menyerang? Lalu apa artinya \"pelanggaran Aturan Berpakaian\"?",
  ui_story_5014_50140202_4_dialog_content = "Mesin-mesin ini sangat berbahaya.",
  ui_story_5014_50140202_5_dialog_content = "Apa pun tujuannya, pokoknya kita harus hati-hati.",
  ui_story_5014_50140202_6_dialog_content = "Peringatan, pengganggu keadilan, perusakan properti umum... Memanggil bala bantuan.",
  ui_story_5014_50140202_7_dialog_content = "Gawat. Dia memanggil bala bantuan.",
  ui_story_5014_50140202_8_dialog_content = "Karena hampir tidak tahu apa-apa, sebaiknya kita hindari pertempuran...",
  ui_story_5014_50140202_9_dialog_content = "Bagaimana kalau kita cari tempat aman untuk sembunyi?",
  ui_story_5014_50140202_10_dialog_content = "...",
  ui_story_5014_50140202_11_dialog_content = "Siapa itu? Keluarlah!",
  ui_story_5014_50140202_12_dialog_content = "Tenanglah, kita berada di pihak yang sama.",
  ui_story_5014_50140202_13_dialog_content = "Ayo kita pergi ke tempat yang aman sebelum droid lainnya berdatangan.",
  ui_story_5014_50140202_14_dialog_content = "Akan kujelaskan nanti...",
  ui_story_5014_50140202_15_dialog_content = "Siapa kamu...?",
  ui_story_5014_50140202_16_dialog_content = "Siobhan, peneliti Illumina, anak buah Tech Officer Gronru.",
  ui_story_5014_50140202_17_dialog_content = "Busur yang kamu gunakan itu buatan Illumina.",
  ui_story_5014_50140202_18_dialog_content = "Lieutenant Vice.",
  ui_story_5014_50140202_19_dialog_content = "Nah, sedangkan dua temanmu ini, mereka pasti si Caelestite dan Putri dari Lumopolis.",
  ui_story_5014_50140202_20_dialog_content = "<size=45>Master Siobhan?!</size>",
  ui_story_5014_50140202_21_dialog_content = "Ya, benar. Jangan senang dulu.",
  ui_story_5014_50140202_22_dialog_content = "Maaf, aku tidak mengenalimu karena masker itu.",
  ui_story_5014_50140202_23_dialog_content = "Penampilanmu agak berbeda dari biasanya...",
  ui_story_5014_50140202_24_dialog_content = "Ini pakaian baru.",
  ui_story_5014_50140202_25_dialog_content = "Aku masih punya yang lain. Tunggu di sini, akan kuambilkan.",
  ui_story_5014_50140202_26_dialog_content = "Apa yang gurumu lakukan di sini?",
  ui_story_5014_50140202_27_dialog_content = "Master Siobhan adalah pakar reruntuhan kuno. Mungkin dia memeriksa tempat ini.",
  ui_story_5014_50140202_28_dialog_content = "Pakar reruntuhan kuno? Apa dia guru sejarah?",
  ui_story_5014_50140202_29_dialog_content = "Tidak juga, sih. Dia mengajar arkeologi, tidak sama dengan pelajaran sejarah di Lumopolis.",
  ui_story_5014_50140202_30_dialog_content = "Aku mempelajari semua keterampilan eksplorasi dari Master Siobhan.",
  ui_story_5014_50140202_31_dialog_content = "Dia bahkan mengkritik keterampilan menggambarku yang buruk.",
  ui_story_5014_50140202_32_dialog_content = "Begitu rupanya. Pantas kamu sangat menghormatinya. Kamu takut padanya, ya?",
  ui_story_5014_50140202_33_dialog_content = "Tidak, aku memang sangat menghormatinya karena aku jadi tertarik pada teknologi kuno berkat dia.",
  ui_story_5014_50140202_34_dialog_content = "Aku benar-benar menghormatinya, bukan takut!",
  ui_story_5014_50140202_35_dialog_content = "Setelah dikritik, keterampilan menggambar teknisku jadi meningkat...",
  ui_story_5014_50140202_36_dialog_content = "Memangnya dulu aku galak padamu?",
  ui_story_5014_50140202_37_dialog_content = "Oh, Master sudah kembali... Bukan masalah penting, lupakan saja.",
  ui_story_5014_50140202_38_dialog_content = "Tenanglah, jangan tegang begitu.",
  ui_story_5014_50140202_39_dialog_content = "Benar... Maaf, tak kusangka Master masih ingat padaku. Aku jadi sangat gugup.",
  ui_story_5014_50140202_40_dialog_content = "Aku sudah membaca semua laporanmu mengenai Colossus. Aku sangat terkesan.",
  ui_story_5014_50140202_41_dialog_content = "Aku senang kamu memilih untuk mengeksplorasi teknologi kuno.",
  ui_story_5014_50140202_42_dialog_content = "Terima kasih. Dari dulu aku memang sangat tertarik pada teknologi kuno.",
  ui_story_5014_50140202_43_dialog_content = "Yah, aku mengatakannya karena kamu memang benar-benar murid yang menonjol.",
  ui_story_5014_50140202_44_dialog_content = "Bagaimana kalian bisa kemari?",
  ui_story_5014_50140202_45_dialog_content = "Kami menerima sinyal misterius saat berada di Colossus.",
  ui_story_5014_50140202_46_dialog_content = "Vice menemukan koordinatnya. Ternyata lokasinya sangat dekat dengan kami.",
  ui_story_5014_50140202_47_dialog_content = "Saat melakukan ekspedisi, terjadi gempa bumi sehingga kami terjatuh ke dalam celah dan mendarat di gua...",
  ui_story_5014_50140202_48_dialog_content = "Lalu kami berjalan kaki hingga kemari.",
  ui_story_5014_50140202_49_dialog_content = "Seperti yang kutakutkan, sinyal bahayaku tidak terkirim.",
  ui_story_5014_50140202_50_dialog_content = "Kalau begitu, sinyal apa yang kami terima?",
  ui_story_5014_50140202_51_dialog_content = "Bukan sinyalku.",
  ui_story_5014_50140202_52_dialog_content = "Aku juga mendapatkan sinyal koordinat dalam patroli rutinku melalui pegunungan Northland.",
  ui_story_5014_50140202_53_dialog_content = "Pencarian kami juga berujung kemari.",
  ui_story_5014_50140202_54_dialog_content = "Ada sesuatu yang membuat sinyal bahayaku tidak terkirim. Alat komunikasiku juga mati.",
  ui_story_5014_50140202_55_dialog_content = "\"Kami\"? Bagaimana dengan rekanmu?",
  ui_story_5014_50140202_56_dialog_content = "Aku selalu pergi sendirian. Mereka bukan anggota timku.",
  ui_story_5014_50140202_57_dialog_content = "Mereka hanya... teman dari Lumopolis.",
  ui_story_5014_50140202_58_dialog_content = "Lumopolis?",
  ui_story_5014_50140202_59_dialog_content = "Kami sudah terperangkap di sini selama lebih dari 20 hari dan belum bisa menemukan jalan keluar.",
  ui_story_5014_50140202_60_dialog_content = "Lebih dari 20 hari? Tempat macam apa ini?",
  ui_story_5014_50140202_61_dialog_content = "Mungkin ini kota kuno yang tersembunyi di ngarai Northland.",
  ui_story_5014_50140202_62_dialog_content = "Tidak hanya ada droid, tapi juga Eclipsite.",
  ui_story_5014_50140202_63_dialog_content = "Kadang mereka mengganggu eksplorasi, terutama saat kami mencari jalan keluar.",
  ui_story_5014_50140202_64_dialog_content = "Kami diserang droid saat pertama kali tiba.",
  ui_story_5014_50140202_65_dialog_content = "Sebenarnya, itu hanya masalah kecil.",
  ui_story_5014_50140202_66_dialog_content = "Untungnya, aku baru saja menemukan baju ganti untuk kalian.",
  ui_story_5014_50140202_67_dialog_content = "Baju ganti?",
  ui_story_5014_50140202_68_dialog_content = "Benar, ini cara yang bagus untuk menghindari deteksi droid.",
  ui_story_5014_50140202_69_dialog_content = "Baiklah... Aku mengerti.",
  ui_story_5014_50140202_70_option_content = "Aku tidak paham. Bisa tolong diperjelas?",
  ui_story_5014_50140202_71_dialog_content = "Droid ini hanya menegakkan peraturan setempat.",
  ui_story_5014_50140202_72_dialog_content = "Polisi Gannon akan menangkap kita kalau kita tidak berpakaian.",
  ui_story_5014_50140202_73_dialog_content = "Nah, droid ini hanya mengikuti peraturan yang sama.",
  ui_story_5014_50140202_74_dialog_content = "Apa perbandingannya harus seperti itu?",
  ui_story_5014_50140202_75_dialog_content = "Kalau melanggar \"aturan berpakaian\", kita akan dianggap target.",
  ui_story_5014_50140202_76_option_content = "Memangnya kita harus mengikuti semacam \"aturan berpakaian\"?",
  ui_story_5014_50140202_77_dialog_content = "Para droid itu memberi peringatan \"pelanggaran Aturan Berpakaian\" sebelum menyerang.",
  ui_story_5014_50140202_78_dialog_content = "Nah, berarti kita harus berpakaian sesuai aturan mereka, 'kan?",
  ui_story_5014_50140202_79_dialog_content = "Benar. Kamu sangat pintar.",
  ui_story_5014_50140202_80_dialog_content = "Pakaian yang kukenakan dan yang kuberikan pada kalian adalah kostum untuk kota kuno ini.",
  ui_story_5014_50140202_81_dialog_content = "Dibuat di sini.",
  ui_story_5014_50140202_82_dialog_content = "Tapi, ini...",
  ui_story_5014_50140202_83_dialog_content = "Tenang saja. Kita kan hanya berganti pakaian. Bukan masalah besar.",
  ui_story_5014_50140202_84_dialog_content = "Memang harus begini. Tak seorang pun akan mengejekmu.",
  ui_story_5014_50140202_85_dialog_content = "Tapi, aku...",
  ui_story_5014_50140202_86_dialog_content = "Sebaiknya kita mematuhi Master Siobhan. Ini juga demi keselamatan kita.",
  ui_story_5014_50140202_87_dialog_content = "Tapi, kamu...",
  ui_story_5014_50140202_88_dialog_content = "Ganti pakaianmu di ruang sebelah, PlayerName.",
  ui_story_5014_50140202_89_dialog_content = "Jangan buang-buang waktu.",
  ui_story_5014_50140202_90_dialog_content = "Kamu kan bukan petarung. Menurutmu, bagaimana caranya kamu bisa melawan droid?",
  ui_story_5014_50140202_91_dialog_content = "Iya, iya, aku ganti baju...",
  ui_story_5014_50140202_92_dialog_content = "Sudah siap?",
  ui_story_5014_50140202_93_dialog_content = "Aku siap!",
  ui_story_5014_50140202_94_dialog_content = "Pakaian ini terlalu ringan dan tak berpelindung, tapi membuat kita bisa bergerak dengan leluasa.",
  ui_story_5014_50140202_95_dialog_content = "Jadi, rupanya begini rasanya mengenakan pakaian kuno.",
  ui_story_5014_50140202_96_dialog_content = "Menurutku ada persamaannya dengan pakaian yang biasa kita pakai.",
  ui_story_5014_50140202_97_dialog_content = "Justru sebaliknya. Pakaian kita memiliki persamaan dengan ini.",
  ui_story_5014_50140202_98_dialog_content = "Kamu siap, PlayerName?",
  ui_story_5014_50140202_99_dialog_content = "Ada baju lain tidak, sih? Aku tidak mau pakai ini...",
  ui_story_5014_50140202_100_dialog_content = "Tidak ada. Hanya ini yang kutemukan, dan semuanya pakaian wanita.",
  ui_story_5014_50140202_101_dialog_content = "Ayolah. Kami tak akan mengejekmu, aku janji.",
  ui_story_5014_50140202_102_dialog_content = "Baiklah...",
  ui_story_5014_50140202_103_dialog_content = "...",
  ui_story_5014_50140202_104_dialog_content = "...",
  ui_story_5014_50140202_105_dialog_content = "Katakan saja yang kamu pikirkan!",
  ui_story_5014_50140202_106_dialog_content = "Ehem, tak kusangka kakimu sangat ramping.",
  ui_story_5014_50140202_107_dialog_content = "Tak kusangka apanya? Bukankah dulu aku mengenakan celana pendek saat di pantai?",
  ui_story_5014_50140202_108_dialog_content = "Yah, tak kusangka kamu tahu cara mengenakan gaun. Kukira kamu belum pernah memakainya.",
  ui_story_5014_50140202_109_dialog_content = "Memang belum pernah! Sumpah!",
  ui_story_5014_50140202_110_dialog_content = "Ini terlalu kecil dan ketat di bagian dada... Rasanya sesak...",
  ui_story_5014_50140202_111_dialog_content = "Tarik ke bawah sedikit ritsleting di punggungnya. Pasti lebih enak.",
  ui_story_5014_50140202_112_dialog_content = "Apa kota ini hanya membuat pakaian wanita saja, Siobhan?",
  ui_story_5014_50140202_113_dialog_content = "Kurasa tidak. Kebetulan hanya ini yang bisa kutemukan.",
  ui_story_5014_50140202_114_dialog_content = "Baiklah, aku mengerti...",
  ui_story_5014_50140202_115_dialog_content = "Karena sekarang kita sudah aman dari droid, ayo periksa kota ini.",
  ui_story_5014_50140202_116_dialog_content = "Aku ingin mencari pakaian lain.",
  ui_story_5014_50140202_117_dialog_content = "Ehem. Kurasa tujuan kita sama-sama mencari jalan keluar.",
  ui_story_5014_50140202_118_dialog_content = "Kamu benar, Vice.",
  ui_story_5014_50140202_119_dialog_content = "(Sialan, mereka mengabaikan keadaanku... Pokoknya aku harus ganti pakaian!)",
  ui_story_5014_50140202_120_dialog_content = "Baiklah, ayo kita pergi!",
  ui_story_5014_50140202_121_dialog_content = "Grrr...",
  ui_story_5014_50140202_122_dialog_content = "Rasanya seperti Eclipsite, tapi juga bukan... Yah, mungkin mereka memang Eclipsite.",
  ui_story_5014_50140202_123_dialog_content = "Kenapa pendapatmu berubah?",
  ui_story_5014_50140202_124_dialog_content = "Mereka cukup jauh, dan tidak sama dengan Eclipsite yang biasanya kurasakan.",
  ui_story_5014_50140202_125_dialog_content = "Apa bedanya?",
  ui_story_5014_50140202_126_dialog_content = "Aku tak bisa menjelaskannya. Pokoknya aku tahu.",
  ui_story_5014_50140202_127_dialog_content = "Mereka datang.",
  ui_story_5014_50140202_128_dialog_content = "Ayo kita pergi ke tempat lain dan sebisa mungkin menghindari pertarungan.",
  ui_story_5014_50140301_1_dialog_content = "Bip! Bip!",
  ui_story_5014_50140301_2_dialog_content = "Lagi-lagi para droid itu...",
  ui_story_5014_50140301_3_dialog_content = "Jangan khawatir.",
  ui_story_5014_50140301_4_dialog_content = "Lihat, 'kan? Mereka tidak menyerangmu lagi.",
  ui_story_5014_50140301_5_dialog_content = "Baiklah... Maaf, aku terlalu takut.",
  ui_story_5014_50140301_6_dialog_content = "Apa ini benar-benar kota kuno, Master Siobhan?",
  ui_story_5014_50140301_7_dialog_content = "Benar.",
  ui_story_5014_50140301_8_dialog_content = "Tempat ini penuh dengan bangunan yang sangat tinggi dan memiliki banyak ruang kecil...",
  ui_story_5014_50140301_9_dialog_content = "Berarti tempat ini sangat padat penghuni?",
  ui_story_5014_50140301_10_dialog_content = "Benar.",
  ui_story_5014_50140301_11_dialog_content = "Bagaimana kamu tahu masyarakat kuno dulu tinggal di sini?",
  ui_story_5014_50140301_12_dialog_content = "Soroz bilang tak ada yang tahu seperti apa masa kuno itu.",
  ui_story_5014_50140301_13_dialog_content = "Yah, Gannon dibangun kembali dari reruntuhan kuno.",
  ui_story_5014_50140301_14_dialog_content = "Kita tetap bisa menebaknya dengan logis walau tidak tahu persisnya.",
  ui_story_5014_50140301_15_dialog_content = "Gannon? Tapi, tempat ini sangat berbeda dengan Gannon.",
  ui_story_5014_50140301_16_dialog_content = "Iya, gaya arsitekturnya pun tidak sama.",
  ui_story_5014_50140301_17_dialog_content = "Kurasa ini karena keduanya dibangun di era yang berbeda dan mungkin untuk tujuan berbeda pula.",
  ui_story_5014_50140301_18_dialog_content = "Era yang berbeda, aku paham. Tapi, kalau tujuan yang berbeda... apa maksudnya?",
  ui_story_5014_50140301_19_dialog_content = "Anu, aku juga belum paham benar.",
  ui_story_5014_50140301_20_dialog_content = "Aku hanya tahu bahwa dulu kaum Ancient menjadikan reruntuhan Gannon sebagai tempat berlindung saat perang.",
  ui_story_5014_50140301_21_dialog_content = "Bagaimana menurutmu, Master Siobhan?",
  ui_story_5014_50140301_22_dialog_content = "Kurasa kamu terlalu cerewet.",
  ui_story_5014_50140301_23_dialog_content = "Aku tahu dulu Gannon adalah tempat berlindung saat perang.",
  ui_story_5014_50140301_24_dialog_content = "Ada sisa-sisa peradaban kuno di seluruh negeri, dan Illumina ditugaskan untuk menggalinya.",
  ui_story_5014_50140301_25_dialog_content = "Lumopolis mungkin tidak seperti Illumina yang sangat memahami teknologi kuno, tapi kami semua tahu beberapa hal tentang itu.",
  ui_story_5014_50140301_26_dialog_content = "Eh, Carleen adalah anggota tim, Master Siobhan.",
  ui_story_5014_50140301_27_dialog_content = "Aku yakin kita bisa membagikan informasi nonrahasia dengan bebas.",
  ui_story_5014_50140301_28_dialog_content = "Baiklah... Kurasa Carleen memang bukan bangsawan arogan.",
  ui_story_5014_50140301_29_dialog_content = "Aku tidak menginginkan rahasiamu.",
  ui_story_5014_50140301_30_dialog_content = "Tapi, karena kita semua terjebak di sini, sebaiknya kita saling terbuka.",
  ui_story_5014_50140301_31_dialog_content = "Aku hanya ingin mencari jalan keluar dan makanan.",
  ui_story_5014_50140301_32_dialog_content = "Beberapa fasilitas di sini masih berfungsi, termasuk droid dan pabrik makanan.",
  ui_story_5014_50140301_33_dialog_content = "Pertanyaanku masih sama. Kenapa bangunannya tampak berbeda dengan yang di Gannon?",
  ui_story_5014_50140301_34_dialog_content = "Kupikir ini hanya kota biasa.",
  ui_story_5014_50140301_35_dialog_content = "Kota biasa?",
  ui_story_5014_50140301_36_dialog_content = "Aku menemukan petunjuk, seperti buku-buku berbahasa kuno dan banyak fasilitas untuk sehari-hari.",
  ui_story_5014_50140301_37_dialog_content = "Menurut pengamatanku, serangan droid tidak begitu berbahaya.",
  ui_story_5014_50140301_38_dialog_content = "Tempat ini dibangun untuk dihuni.",
  ui_story_5014_50140301_39_dialog_content = "Sayangnya, aku tidak bisa menemukan tanda-tanda penduduk Ancient sejauh ini.",
  ui_story_5014_50140301_40_dialog_content = "Seluruh penduduknya pasti sudah dihabisi Eclipsite.",
  ui_story_5014_50140301_41_dialog_content = "Aku tidak yakin karena ada satu fakta aneh...",
  ui_story_5014_50140301_42_dialog_content = "Para Eclipsite dan droid di sini tidak saling menyerang.",
  ui_story_5014_50140301_43_dialog_content = "Tapi, kalau Eclipsite menyerang kami, droid akan menyerang mereka.",
  ui_story_5014_50140301_44_dialog_content = "Kami...? Oh, aku mau tanya, di mana orang-orang dari Lumopolis?",
  ui_story_5014_50140301_45_dialog_content = "Mereka selalu di sekitarku.",
  ui_story_5014_50140301_46_dialog_content = "Para Eclipsite itu mengikuti kita, Chief.",
  ui_story_5014_50140301_47_dialog_content = "Jumlah mereka seukuran sarang lebah.",
  ui_story_5014_50140301_48_dialog_content = "Sudah berapa kali kubilang, jangan menggunakan deskripsi yang aneh begitu, dan jangan panggil aku Chief!",
  ui_story_5014_50140301_49_dialog_content = "Serang saja Eclipsite terbesar denganku.",
  ui_story_5014_50140301_50_dialog_content = "Baik, Chief.",
  ui_story_5014_50140301_51_dialog_content = "Aku merasakan Aurorian bertarung melawan Eclipsite di sana!",
  ui_story_5014_50140301_52_dialog_content = "Kekuatan psikismu kuat juga.",
  ui_story_5014_50140301_53_dialog_content = "Kurasa dua teman Lumopolis-ku mengalami masalah.",
  ui_story_5014_50140301_54_dialog_content = "Karena sudah di sini, sekalian saja kita bantu.",
  ui_story_5014_50140301_55_dialog_content = "Sepertinya kamu tidak terlalu senang, Siobhan.",
  ui_story_5014_50140301_56_dialog_content = "Tak kusangka kamu akan menemukan kami dan kemari dengan sangat cepat...",
  ui_story_5014_50140301_57_dialog_content = "Florine.",
  ui_story_5014_50140302_1_dialog_content = "Yang Mulia, saya Florine dari Divisi Investigasi Bidat. Sangat senang bertemu dengan Anda!",
  ui_story_5014_50140302_2_dialog_content = "Tapi, apa yang Anda lakukan di sini?",
  ui_story_5014_50140302_3_dialog_content = "Aku tak sengaja jatuh ke sini karena gempa bumi.",
  ui_story_5014_50140302_4_dialog_content = "Bagaimana denganmu? Di mana rekanmu?",
  ui_story_5014_50140302_5_dialog_content = "Erica sedang mengintai perimeter.",
  ui_story_5014_50140302_6_dialog_content = "Meski tindakannya tak bisa diprediksi, dia pasti akan segera kembali.",
  ui_story_5014_50140302_7_dialog_content = "Kami mengalami masalah di tundra dan terjebak di tempat aneh ini.",
  ui_story_5014_50140302_8_dialog_content = "Kalian kan jatuh ke dalam gua karena mengikutiku.",
  ui_story_5014_50140302_9_dialog_content = "Sebaiknya kita bicara empat mata di tempat lain, Lady Carleen.",
  ui_story_5014_50140302_10_dialog_content = "Kota kuno ini dijaga dengan baik dan mungkin lebih besar dari yang kita kira.",
  ui_story_5014_50140302_11_dialog_content = "Tentu.",
  ui_story_5014_50140302_12_dialog_content = "Mereka mau bicara empat mata. Memangnya apa sih yang mereka tak ingin kita dengar?",
  ui_story_5014_50140302_13_dialog_content = "Kemarilah, Vice. Ada yang harus kukatakan.",
  ui_story_5014_50140302_14_dialog_content = "Florine bukan hanya anggota Divisi Investigasi Bidat...",
  ui_story_5014_50140302_15_dialog_content = "Dia juga penjelajah terbaik di kota itu.",
  ui_story_5014_50140302_16_dialog_content = "Dia spesialis penyelidikan reruntuhan kuno.",
  ui_story_5014_50140302_17_dialog_content = "Tapi, tidak seperti aku, misi mereka adalah untuk menghancurkan...",
  ui_story_5014_50140302_18_dialog_content = "Memangnya apa sih tujuan rahasia-rahasiaan seperti ini? Aku dengar semua, kok.",
  ui_story_5014_50140302_19_dialog_content = "...",
  ui_story_5014_50140302_20_dialog_content = "Telingamu tajam juga rupanya.",
  ui_story_5014_50140302_21_dialog_content = "Aku juga mendengar pembicaraan dua orang lainnya.",
  ui_story_5014_50140302_22_dialog_content = "Mereka menganggapmu sebagai cendekiawan berbahaya, dan tempat ini juga sangat berbahaya.",
  ui_story_5014_50140302_23_dialog_content = "Karena kita semua terjebak di sini, sebaiknya kita saling jujur pada satu sama lain.",
  ui_story_5014_50140302_24_dialog_content = "Kalau tidak saling percaya, kita tak akan bisa menemukan jalan keluar.",
  ui_story_5014_50140302_25_dialog_content = "Bagaimana menurut kalian?",
  ui_story_5014_50140302_26_dialog_content = "Kamu pasti Caelestite yang bertualang dengan Lady Carleen, dan...",
  ui_story_5014_50140302_27_dialog_content = "Kamu tidak cocok pakai gaun itu.",
  ui_story_5014_50140302_28_dialog_content = "Aku tidak punya pilihan lain!",
  ui_story_5014_50140302_29_dialog_content = "Hiss!",
  ui_story_5014_50140302_30_dialog_content = "Wah, ular itu kenapa, sih?",
  ui_story_5014_50140302_31_dialog_content = "Jangan berisik, kamu menakuti Alba!",
  ui_story_5014_50140302_32_dialog_content = "Kenapa kamu membawa ular?",
  ui_story_5014_50140302_33_dialog_content = "Ini masalah serius. Jangan mengalihkan pembicaraan.",
  ui_story_5014_50140302_34_dialog_content = "Heh, justru kamu yang mengalihkan pembicaraan!",
  ui_story_5014_50140302_35_dialog_content = "Perhatianku jadi terganggu gara-gara kamu memakai gaun itu.",
  ui_story_5014_50140302_36_dialog_content = "Omong-omong, walaupun kamu berteman dengan Lady Carleen...",
  ui_story_5014_50140302_37_dialog_content = "Kusarankan kamu tidak menyela kalau tidak paham dengan situasinya.",
  ui_story_5014_50140302_38_dialog_content = "Bukankah Anda dengan Divisi Investigasi? Aku bahkan tahu Hedy.",
  ui_story_5014_50140302_39_dialog_content = "Dulu Hedy bekerja denganku.",
  ui_story_5014_50140302_40_dialog_content = "Apa dia belum pernah bercerita tentang aku?",
  ui_story_5014_50140302_41_dialog_content = "Pernah... Apa kalian berteman?",
  ui_story_5014_50140302_42_dialog_content = "Tidak juga. Tapi, kalau ada di sini, dia pasti mau mendengar saranku.",
  ui_story_5014_50140302_43_dialog_content = "Aku setuju dengan PlayerName.",
  ui_story_5014_50140302_44_dialog_content = "Seperti yang kujelaskan padamu barusan, Florine...",
  ui_story_5014_50140302_45_dialog_content = "Tujuan kita sama-sama menemukan jalan keluar. Itu hanya bisa dicapai dengan berbagi informasi.",
  ui_story_5014_50140302_46_dialog_content = "Benar, aku juga setuju.",
  ui_story_5014_50140302_47_dialog_content = "Baiklah, Lady Carleen. Aku akan berusaha sebaik mungkin.",
  ui_story_5014_50140302_48_dialog_content = "...",
  ui_story_5014_50140302_49_dialog_content = "Apa maksudmu?",
  ui_story_5014_50140302_50_dialog_content = "Berkat Vice dan teman-temannya, sepertinya kita bisa mencoba akrab.",
  ui_story_5014_50140302_51_dialog_content = "Ya, berkat Lady Carleen dan teman-temannya.",
  ui_story_5014_50140401_1_dialog_content = "Tadinya kami sedang melakukan misi di dekat tundra.",
  ui_story_5014_50140401_2_dialog_content = "Kami menerima sinyal misterius di perjalanan, tapi tidak tahu sinyal apakah itu.",
  ui_story_5014_50140401_3_dialog_content = "Yang jelas, sumbernya tidak jauh.",
  ui_story_5014_50140401_4_dialog_content = "Saat kami melakukan penyelidikan, tanah berguncang. Lalu Erica dan aku terjatuh.",
  ui_story_5014_50140401_5_dialog_content = "Bukannya kalian mengintaiku?",
  ui_story_5014_50140401_6_dialog_content = "Kami hanya melakukan penyelidikan rutin, kok.",
  ui_story_5014_50140401_7_dialog_content = "Kami tidak mengerti maksudmu, Siobhan.",
  ui_story_5014_50140401_8_dialog_content = "Kamu pasti melakukan penelitian yang mencurigakan kalau sangat bersikap defensif begitu.",
  ui_story_5014_50140401_9_dialog_content = "Tuduhanmu terdengar tidak berdasar.",
  ui_story_5014_50140401_10_dialog_content = "Aku bersikap defensif karena kalian mencurigakan dan membuatku terancam.",
  ui_story_5014_50140401_11_dialog_content = "Kenapa begitu?",
  ui_story_5014_50140401_12_dialog_content = "Poin pertama dalam pelajaran Exploration adalah...",
  ui_story_5014_50140401_13_dialog_content = "\"Lumopolis ingin menghancurkan seluruh teknologi kuno untuk menjamin kekuatan mereka sendiri\".",
  ui_story_5014_50140401_14_dialog_content = "Jadi ancaman terbesar bagi tim ekspedisi adalah Divisi Investigasi Bidat Lumopolis, yang bertugas menghancurkan teknologi kuno.",
  ui_story_5014_50140401_15_dialog_content = "Wah, sepertinya ada yang menyimpan dendam, nih.",
  ui_story_5014_50140401_16_dialog_content = "Saya berlari melintasi Divisi Investigasi beberapa kali sendiri.",
  ui_story_5014_50140401_17_dialog_content = "Kami pasti selalu bertarung atau hampir bertarung.",
  ui_story_5014_50140401_18_dialog_content = "Kami tak pernah terus memaksamu untuk mengungkap motifmu.",
  ui_story_5014_50140401_19_dialog_content = "Dan kami tak pernah berniat menghentikan misimu setelahnya.",
  ui_story_5014_50140401_20_dialog_content = "Aku tidak melakukan penelitian yang berbahaya.",
  ui_story_5014_50140401_21_dialog_content = "Sinyal koordinat dikirim dengan enkripsi Illumina. Aku hanya mengikutinya.",
  ui_story_5014_50140401_22_dialog_content = "Mungkin saja itu sinyal bahaya dari <color=#FFB400>sesama orang Illumina</color>.",
  ui_story_5014_50140401_23_dialog_content = "Kami juga mengikuti sinyal itu.",
  ui_story_5014_50140401_24_dialog_content = "Sini, aku mau lihat alat komunikasimu, Vice. Mungkin kita masih bisa melacaknya.",
  ui_story_5014_50140401_25_dialog_content = "Tentu saja. Tapi, alat ini jadi tak berfungsi sejak kami kemari.",
  ui_story_5014_50140401_26_dialog_content = "Kurasa semua orang terjebak karena sinyal itu...",
  ui_story_5014_50140401_27_dialog_content = "Tempat ini seperti lubang tanpa dasar yang menarik orang dengan umpan.",
  ui_story_5014_50140401_28_dialog_content = "Siapa kamu? Apa yang kamu lakukan di belakangku?!",
  ui_story_5014_50140401_29_dialog_content = "Jangan takut. Itu Erica, rekanku.",
  ui_story_5014_50140401_30_dialog_content = "Kadang omongannya memang aneh. Kadang.",
  ui_story_5014_50140401_31_dialog_content = "Kenapa kamu mengulanginya, Chief?",
  ui_story_5014_50140401_32_dialog_content = "Aku khawatir mereka jadi curiga padamu lalu pertemanan yang kita jalin dengan susah payah ini jadi hancur.",
  ui_story_5014_50140401_33_dialog_content = "Apa Anda sudah menggunakan kekuatan rahasia, Lady Carleen?",
  ui_story_5014_50140401_34_dialog_content = "Chief bicara pada peneliti Illumina... Ini pasti gara-gara Anda.",
  ui_story_5014_50140401_35_dialog_content = "Kekuatan rahasia?",
  ui_story_5014_50140401_36_dialog_content = "Jangan hiraukan dia, Lady Carleen.",
  ui_story_5014_50140401_37_dialog_content = "Apa kamu menemukan hal baru, Erica?",
  ui_story_5014_50140401_38_dialog_content = "Ya, Chief. Aku menemukan pakaian yang bagus.",
  ui_story_5014_50140401_39_dialog_content = "Pakaian pria bukan?",
  ui_story_5014_50140401_40_dialog_content = "Sayangnya, ini pakaian wanita... Caelestite bergaun.",
  ui_story_5014_50140401_41_dialog_content = "Aku tak mau pakai ini! Jangan panggil begitu, dong!",
  ui_story_5014_50140401_42_dialog_content = "Kalau begitu, aku akan memanggilmu Captain, pilot Colossus Caelestite.",
  ui_story_5014_50140401_43_dialog_content = "Omong kosong apa itu?",
  ui_story_5014_50140401_44_dialog_content = "Sudah kubilang, jangan hiraukan dia.",
  ui_story_5014_50140401_45_dialog_content = "Bagaimana kalau kita bertukar informasi saja?",
  ui_story_5014_50140401_46_dialog_content = "Aku duluan.",
  ui_story_5014_50140401_47_dialog_content = "Kurasa ini adalah kota otomatis yang bertenaga baik.",
  ui_story_5014_50140401_48_dialog_content = "Kemungkinan besar tempat ini dikelola oleh AI.",
  ui_story_5014_50140401_49_dialog_content = "AI? Maksudmu, seperti Soroz...?",
  ui_story_5014_50140401_50_dialog_content = "Benar, tapi yang satu ini hanya berfungsi sebagian.",
  ui_story_5014_50140401_51_dialog_content = "Ini adalah reruntuhan kuno pertama yang kulihat masih sangat... utuh.",
  ui_story_5014_50140401_52_dialog_content = "Bahkan lebih sempurna dari pembuatan ulang peta Hedy berdasarkan buku-buku tua.",
  ui_story_5014_50140401_53_dialog_content = "Tempat ini bahkan punya mesin yang bisa mengeluarkan minuman aneh.",
  ui_story_5014_50140401_54_dialog_content = "Kita akan jadi monster cegukan kalau meminumnya.",
  ui_story_5014_50140401_55_dialog_content = "Jangan-jangan kamu meminumnya...",
  ui_story_5014_50140401_56_dialog_content = "Lalu ada burung mekanis yang beterbangan dan memikat orang-orang ke lokasi tertentu dengan makanan.",
  ui_story_5014_50140401_57_dialog_content = "Nah, yang lebih mengerikan lagi... Semuanya berupa makanan kalengan.",
  ui_story_5014_50140401_58_dialog_content = "Di Illumina juga ada makanan kalengan. Mengerikan bagaimana?",
  ui_story_5014_50140401_59_dialog_content = "Mereka punya makanan kalengan rasa keik. Lumayan enak, lo.",
  ui_story_5014_50140401_60_dialog_content = "Sudah kubilang jangan memakannya, 'kan?",
  ui_story_5014_50140401_61_dialog_content = "Lalu ada pabrik jahat yang bisa melahap makanan dan memuntahkan kaleng.",
  ui_story_5014_50140401_62_dialog_content = "Kamu ini bicara apa, sih?",
  ui_story_5014_50140401_63_dialog_content = "Aku juga tidak begitu paham. Tapi, itu artinya mereka melihat...",
  ui_story_5014_50140401_64_dialog_content = "Mesin jual otomatis, drone pengantar kaleng, dan pabrik kaleng.",
  ui_story_5014_50140401_65_dialog_content = "Aku tidak habis pikir bagaimana kamu bisa memahami omongannya.",
  ui_story_5014_50140401_66_dialog_content = "Semua yang kubaca di buku tentang dunia alien... ada di sini.",
  ui_story_5014_50140401_67_dialog_content = "Tempat ini kejam sekaligus menarik.",
  ui_story_5014_50140401_68_dialog_content = "Jangan-jangan kamu menyukainya, ya?",
  ui_story_5014_50140401_69_dialog_content = "Apa kamu sudah lupa pada droid itu?",
  ui_story_5014_50140401_70_dialog_content = "Droid? Benar, mereka sangat keras kepala...",
  ui_story_5014_50140401_71_dialog_content = "Kenapa kamu gemetaran begitu?",
  ui_story_5014_50140401_72_dialog_content = "Mereka tidak pernah capek dan terus bekerja...",
  ui_story_5014_50140401_73_dialog_content = "Mereka menerjang dengan gagah berani menuju pertempuran tanpa takut mati...",
  ui_story_5014_50140401_74_dialog_content = "Mereka mengerumunimu...",
  ui_story_5014_50140401_75_dialog_content = "Seperti para Eclipsite menjijikkan itu.",
  ui_story_5014_50140401_76_dialog_content = "Baiklah, tenang dulu.",
  ui_story_5014_50140401_77_dialog_content = "Produksi makanan dan pengiriman otomatis... Apa kamu tahu artinya?",
  ui_story_5014_50140401_78_dialog_content = "Ini berarti semua orang di setiap kota Illumina bisa berhenti mencemaskan makanan.",
  ui_story_5014_50140401_79_dialog_content = "Terutama yang di garis depan.",
  ui_story_5014_50140401_80_dialog_content = "Benar. Tenaga kerja dan sumber daya yang dihemat bisa digunakan untuk meningkatkan produksi pertanian.",
  ui_story_5014_50140401_81_dialog_content = "Itu bisa memastikan semua Aurorian di seluruh negeri akan...",
  ui_story_5014_50140401_82_dialog_content = "Sebentar, mereka juga droid yang dikendalikan AI. Apa kamu sadar artinya?",
  ui_story_5014_50140401_83_dialog_content = "Itu berarti kita bisa menghemat tenaga kerja dan sumber daya.",
  ui_story_5014_50140401_84_dialog_content = "Itu berarti kita tak perlu mengendalikan droid secara aktif.",
  ui_story_5014_50140401_85_dialog_content = "Orang-orang Illumina seperti kalian selalu merasa bisa mengendalikan mesin untuk mengalahkan Eclipsite, ya?",
  ui_story_5014_50140401_86_dialog_content = "Bagaimana kalau para droid itu justru menyerang Aurorian?",
  ui_story_5014_50140401_87_dialog_content = "Bagaimana kalau para Eclipsite itu mengendalikan droid?",
  ui_story_5014_50140401_88_dialog_content = "Apa maksudmu? Eclipsite kan tidak bisa mengendalikan mesin.",
  ui_story_5014_50140401_89_dialog_content = "Kami pernah bertemu Eclipsite yang cerdas, juga Eclipsite jadi-jadian Aurorian.",
  ui_story_5014_50140401_90_dialog_content = "Jadi, Illumina harus mengandalkan Lumopolis untuk mengalahkan Eclipsite?",
  ui_story_5014_50140401_91_dialog_content = "Dan menunggu Lumopolis untuk membagi ransum makanan kami?",
  ui_story_5014_50140401_92_dialog_content = "Cukup, berhentilah bertengkar. Tak ada gunanya.",
  ui_story_5014_50140401_93_dialog_content = "Aku baru saja menyadari masalah yang lebih besar.",
  ui_story_5014_50140401_94_dialog_content = "Apa kamu yakin alat komunikasimu menunjukkan tanggal yang benar, Vice?",
  ui_story_5014_50140401_95_dialog_content = "Tentu. Kenapa?",
  ui_story_5014_50140401_96_dialog_content = "Alat itu menunjukkan bahwa aku sudah ada di sini selama lebih dari 50 hari.",
  ui_story_5014_50140401_97_dialog_content = "Lebih dari 50 hari? Mustahil. Aku masih ingat benar...",
  ui_story_5014_50140401_98_dialog_content = "Iya, aku juga.",
  ui_story_5014_50140401_99_dialog_content = "Alat-alatku tidak berfungsi, tapi aku yakin ini baru 27 hari.",
  ui_story_5014_50140401_100_dialog_content = "Kegagalan perangkat? Jangan-jangan itu teknologi jamming kuno?",
  ui_story_5014_50140401_101_dialog_content = "Mungkin mereka membuat alat-alat jadi tak berfungsi dan mengacaukan perkiraan waktu kita dengan suatu bidang energi spesial?",
  ui_story_5014_50140401_102_dialog_content = "Aku menjumpai banyak bidang energi di reruntuhan, tapi kurasa bukan itu penyebabnya.",
  ui_story_5014_50140401_103_dialog_content = "Mustahil. Mengacaukan waktu dan ruang adalah ranah supranatural.",
  ui_story_5014_50140401_104_dialog_content = "Tapi, beberapa Eclipsite bisa membuat dimensi kecil, dan Eclipsium semacam itu bisa memengaruhi peralatan serta persepsi normal.",
  ui_story_5014_50140401_105_dialog_content = "Sudah kuduga, tempat ini dan para Eclipsite-nya sama-sama menggunakan kekuatan jahat!",
  ui_story_5014_50140401_106_dialog_content = "Pasti AI itu juga jahat...",
  ui_story_5014_50140401_107_dialog_content = "Selama ini dia mengawasi dan membuat rencana...",
  ui_story_5014_50140401_108_dialog_content = "Dia ingin melahap pikiran kita, membuat kita jadi gila...",
  ui_story_5014_50140401_109_dialog_content = "Kenapa kamu mulai lagi, sih, Erica?",
  ui_story_5014_50140401_110_dialog_content = "Lihat, Chief! Antek-anteknya datang!",
  ui_story_5014_50140401_111_dialog_content = "Bip... Bip...",
  ui_story_5014_50140401_112_dialog_content = "<color=#e8d9bb>Mulai pemindaian area...</color>",
  ui_story_5014_50140401_113_dialog_content = "<color=#e8d9bb>Orang luar menghancurkan tempat rekreasi umum.</color>",
  ui_story_5014_50140401_114_dialog_content = "<color=#e8d9bb>Menghancurkan tempat pasokan makanan.</color>",
  ui_story_5014_50140401_115_dialog_content = "Ada pendatang baru lagi?",
  ui_story_5014_50140401_116_dialog_content = "Mungkin karena ada gempa bumi lagi.",
  ui_story_5014_50140401_117_dialog_content = "Apa kamu tidak bisa memperbaiki jalan itu, Butler?",
  ui_story_5014_50140401_118_dialog_content = "<color=#e8d9bb>Saat ini sedang dalam... perbaikan keempat.</color>",
  ui_story_5014_50140401_119_dialog_content = "Itu pasti juga akan rusak kalau ada gempa bumi lagi.",
  ui_story_5014_50140401_120_dialog_content = "<color=#e8d9bb>Jangan... khawatir. Modul sistem parsial... memperbarui sekarang.</color>",
  ui_story_5014_50140401_121_dialog_content = "<color=#e8d9bb>Kami akan... segera menyelesaikannya.</color>",
  ui_story_5014_50140401_122_dialog_content = "Sekarang apa yang bisa kita lakukan selain sembunyi?",
  ui_story_5014_50140401_123_dialog_content = "Orang-orang luar itu terlalu kuat. Mereka bisa mengalahkan Eclipsite.",
  ui_story_5014_50140401_124_dialog_content = "<color=#e8d9bb>Jangan... khawatir. Modul produksi dipasang kembali.</color>",
  ui_story_5014_50140401_125_dialog_content = "<color=#e8d9bb>Memperbarui... sekarang.</color>",
  ui_story_5014_50140401_126_dialog_content = "<color=#e8d9bb>Tolong tunggu di... bungker bawah tanah. Jangan ke mana-mana.</color>",
  ui_story_5014_50140401_127_dialog_content = "<color=#e8d9bb>Kami akan... segera menyelesaikannya.</color>",
  ui_story_5014_50140401_128_dialog_content = "Tapi, robotmu tidak sebanding dengan orang-orang luar itu.",
  ui_story_5014_50140401_129_dialog_content = "Sebaiknya aku pergi...",
  ui_story_5014_50140401_130_dialog_content = "Tunggu, Gretel.",
  ui_story_5014_50140401_131_dialog_content = "Apa sistem pengawasannya sudah diperbaiki, Butler?",
  ui_story_5014_50140401_132_dialog_content = "<color=#e8d9bb>Perbaikan... gagal.</color>",
  ui_story_5014_50140401_133_dialog_content = "Mari kita kirim Guardian Angel No. 3.",
  ui_story_5014_50140401_134_dialog_content = "Kita bisa memantau orang-orang luar dengan itu.",
  ui_story_5014_50140401_135_dialog_content = "Tidak, jangan mengirimnya. Nanti mereka malah menghancurkannya!",
  ui_story_5014_50140401_136_dialog_content = "Ini hadiah penting dari Ayah!",
  ui_story_5014_50140401_137_dialog_content = "Jangan buat mereka menunggu. Kita harus melakukan sesuatu.",
  ui_story_5014_50140401_138_dialog_content = "Bahkan kalau hanya demi segelintir informasi.",
  ui_story_5014_50140401_139_dialog_content = "Akan kuminta Guardian Angel No. 3 untuk berhati-hati dan menghindari deteksi.",
  ui_story_5014_50140401_140_dialog_content = "Baiklah.",
  ui_story_5014_50140401_141_dialog_content = "Kemarilah, Guardian Angel No. 3.",
  ui_story_5014_50140401_142_dialog_content = "Bibu!",
  ui_story_5014_50140401_143_dialog_content = "Awasi dengan diam-diam dan cari tahu rencana mereka.",
  ui_story_5014_50140401_144_dialog_content = "Jaga jarak dan jangan sampai mereka melihatmu.",
  ui_story_5014_50140501_1_dialog_content = "<color=#e8d9bb>Gruk!</color>",
  ui_story_5014_50140501_2_dialog_content = "Ada gempa bumi lagi! Cari tempat aman untuk berlindung!",
  ui_story_5014_50140501_3_dialog_content = "<color=#e8d9bb>Gruk...</color>",
  ui_story_5014_50140501_4_dialog_content = "Untung saja bangunannya tidak roboh. Akan gawat kalau sampai roboh!",
  ui_story_5014_50140501_5_dialog_content = "<color=#e8d9bb>Tik, tik.</color>",
  ui_story_5014_50140501_6_dialog_content = "Alat komunikasiku berfungsi lagi, Master Siobhan.",
  ui_story_5014_50140501_7_dialog_content = "Benar, alatku juga.",
  ui_story_5014_50140501_8_dialog_content = "Gempa bumi terakhir...",
  ui_story_5014_50140501_9_dialog_content = "Ini juga terjadi.",
  ui_story_5014_50140501_10_dialog_content = "Kita harus cukup dekat dengan sumbernya agar bisa menerima sinyal, atau...",
  ui_story_5014_50140501_11_dialog_content = "Gangguan apa pun itu telah berhenti.",
  ui_story_5014_50140501_12_dialog_content = "Ayo kita cari sumbernya selagi masih ada sinyal.",
  ui_story_5014_50140501_13_dialog_content = "Kamu mau ke mana?",
  ui_story_5014_50140501_14_dialog_content = "Mencari sumber sinyal itu.",
  ui_story_5014_50140501_15_dialog_content = "Kamu masih mau mencarinya?",
  ui_story_5014_50140501_16_dialog_content = "Gempa bumi sudah terjadi tiga kali. Kalau begini terus, kita bisa...",
  ui_story_5014_50140501_17_dialog_content = "Ya, di sini memang sangat berbahaya. Kita harus mencari jalan keluar.",
  ui_story_5014_50140501_18_dialog_content = "Yang lainnya kita lakukan nanti.",
  ui_story_5014_50140501_19_dialog_content = "Ini sinyal Illumina. Berarti pernah ada ekspedisi Illumina di sini.",
  ui_story_5014_50140501_20_dialog_content = "Benar, sinyal yang ditinggalkan oleh rekan kerja lama.",
  ui_story_5014_50140501_21_dialog_content = "Aku tahu mereka meninggalkan semacam pesan untuk kita.",
  ui_story_5014_50140501_22_dialog_content = "Apa ada yang kamu ketahui tentang ekspedisi itu, Master Siobhan?",
  ui_story_5014_50140501_23_dialog_content = "Aku belum pernah melihat berkas apa pun mengenai tempat ini. Apa ekspedisinya rahasia?",
  ui_story_5014_50140501_24_dialog_content = "Di berkas rahasia juga tidak ada apa-apa.",
  ui_story_5014_50140501_25_dialog_content = "Aku khawatir tak ada yang bisa kembali ke Illumina.",
  ui_story_5014_50140501_26_dialog_content = "Kenapa rekan kerjamu kemari tanpa meninggalkan petunjuk apa pun?",
  ui_story_5014_50140501_27_dialog_content = "Bukankah seharusnya ada catatan?",
  ui_story_5014_50140501_28_dialog_content = "Misalnya tempat yang dituju tim.",
  ui_story_5014_50140501_29_dialog_content = "Bahaya bisa datang kapan saja saat menjelajahi reruntuhan.",
  ui_story_5014_50140501_30_dialog_content = "Kehilangan anggota adalah hal yang wajar bagi tim ekspedisi.",
  ui_story_5014_50140501_31_dialog_content = "Tapi, mereka meninggalkan suar di sini...",
  ui_story_5014_50140501_32_dialog_content = "Mereka sudah mempertaruhkan nyawa, jadi aku harus menemukannya.",
  ui_story_5014_50140501_33_dialog_content = "Ayo kita juga ikut membantu, Florine.",
  ui_story_5014_50140501_34_dialog_content = "Ya, saya bisa menggunakan perlengkapan Divisi Investigasi...",
  ui_story_5014_50140501_35_dialog_content = "Untuk menemukan lokasi suarnya.",
  ui_story_5014_50140501_36_dialog_content = "Bersiaplah, Erica.",
  ui_story_5014_50140501_37_dialog_content = "Baiklah, Chief.",
  ui_story_5014_50140501_38_dialog_content = "Aku siap, menunggu wahyu Light.",
  ui_story_5014_50140501_39_dialog_content = "Aku ingin tahu instrumen apa yang digunakan Divisi Investigasi...",
  ui_story_5014_50140501_40_dialog_content = "Aku boleh ikut?",
  ui_story_5014_50140501_41_dialog_content = "Sayangnya, tidak.",
  ui_story_5014_50140501_42_dialog_content = "Memangnya rahasia, ya?",
  ui_story_5014_50140501_43_dialog_content = "Bisa dibilang begitu.",
  ui_story_5014_50140501_44_dialog_content = "Oh, baiklah.",
  ui_story_5014_50140501_45_dialog_content = "Sinyal anehnya masih ada di sana. Sudah ketemu. Ikuti aku.",
  ui_story_5014_50140501_46_dialog_content = "Sudah sampai?",
  ui_story_5014_50140501_47_dialog_content = "Benar, di sini. Di bawah.",
  ui_story_5014_50140501_48_dialog_content = "Apa kita akan masuk melalui celah?",
  ui_story_5014_50140501_49_dialog_content = "Celah ini terbentuk karena gempa bumi. Terlalu berbahaya.",
  ui_story_5014_50140501_50_dialog_content = "Memang berbahaya, tapi pantas dicoba.",
  ui_story_5014_50140501_51_dialog_content = "Aku selalu yakin ada fasilitas bawah tanah di sini, tapi pintu masuknya tak pernah ketemu.",
  ui_story_5014_50140501_52_dialog_content = "Lihat ke bawah. Kita beruntung.",
  ui_story_5014_50140501_53_dialog_content = "Sepertinya itu jalannya.",
  ui_story_5014_50140501_54_dialog_content = "Aku mau masuk. Silakan berdebat kalau mau.",
  ui_story_5014_50140501_55_dialog_content = "Tunggu aku, Master Siobhan!",
  ui_story_5014_50140501_56_dialog_content = "Tunggu, Vice!",
  ui_story_5014_50140501_57_dialog_content = "Aku ingin pergi dengan Master Siobhan, PlayerName.",
  ui_story_5014_50140501_58_dialog_content = "Tidak, bukan begitu. Aku menghentikanmu karena...",
  ui_story_5014_50140501_59_dialog_content = "Graaah!",
  ui_story_5014_50140501_60_dialog_content = "Aku merasakan kedatangan Eclipsite!",
  ui_story_5014_50140502_1_dialog_content = "Ada satu di arah jam 9 yang berniat menyergap kita, Vice!",
  ui_story_5014_50140502_2_dialog_content = "Baiklah. Rapid Torrent!",
  ui_story_5014_50140502_3_dialog_content = "Mereka melawan Eclipsite lagi!",
  ui_story_5014_50140502_4_dialog_content = "Dan orang-orang luar itu mungkin menang lagi.",
  ui_story_5014_50140502_5_dialog_content = "Apa mereka mau masuk?",
  ui_story_5014_50140502_6_dialog_content = "Aku yakin mereka memang berniat begitu...",
  ui_story_5014_50140502_7_dialog_content = "Jangan takut, aku akan melindungimu.",
  ui_story_5014_50140502_8_dialog_content = "Kalau mereka datang, carilah tempat untuk sembunyi. Biar kuurus mereka.",
  ui_story_5014_50140502_9_dialog_content = "Keluarlah setelah Butler mengerahkan droid baru.",
  ui_story_5014_50140502_10_dialog_content = "Apa droid barunya sudah siap, Butler?",
  ui_story_5014_50140502_11_dialog_content = "<color=#e8d9bb>Melakukan modifikasi... terakhir.</color>",
  ui_story_5014_50140502_12_dialog_content = "Terlambat. Kerahkan saja!",
  ui_story_5014_50140502_13_dialog_content = "<color=#e8d9bb>Pertanyaan: Apa aku harus membatalkan modifikasi terakhir... untuk droid itu?</color>",
  ui_story_5014_50140502_14_dialog_content = "Tidak, jangan dibatalkan. Itu sangat penting untuk keamanan kita.",
  ui_story_5014_50140502_15_dialog_content = "Berapa kali harus kubilang, Gretel? Jangan berkata begitu kepada Butler.",
  ui_story_5014_50140502_16_dialog_content = "Maaf, Kak... Tadi aku tidak sabar.",
  ui_story_5014_50140502_17_dialog_content = "Sinyalnya makin kuat. Aku bisa merasakan...",
  ui_story_5014_50140502_18_dialog_content = "Di depan sana.",
  ui_story_5014_50140502_19_dialog_content = "Gawat, mereka menuju kemari.",
  ui_story_5014_50140502_20_dialog_content = "Sembunyi, Gretel.",
  ui_story_5014_50140502_21_dialog_content = "Ada Aurorian di sana. Meskipun samar, aku bisa merasakannya!",
  ui_story_5014_50140502_22_dialog_content = "Bagus, PlayerName. Teruskan.",
  ui_story_5014_50140502_23_dialog_content = "Baiklah!",
  ui_story_5014_50140502_24_dialog_content = "Aurorian itu sembunyi...",
  ui_story_5014_50140502_25_dialog_content = "...",
  ui_story_5014_50140502_26_dialog_content = "Awas, master droid jahat itu ada di sini!",
  ui_story_5014_50140502_27_dialog_content = "Peringatan, peringatan, tolong jangan mendekat.",
  ui_story_5014_50140502_28_dialog_content = "Siapa kamu? Bagaimana kamu memanggil semua droid ini?",
  ui_story_5014_50140502_29_dialog_content = "Apa kamu keturunan kaum Ancient?",
  ui_story_5014_50140502_30_dialog_content = "Bisa memanggil mesin?",
  ui_story_5014_50140502_31_dialog_content = "Master? Kuno? Memanggil? Kalian ini bicara apa?",
  ui_story_5014_50140502_32_dialog_content = "Penghuni dunia alien ini bisa bicara dengan bahasa kita?",
  ui_story_5014_50140502_33_dialog_content = "Kalau dia bisa bicara dengan bahasa kita, berarti dia bukan Ancient.",
  ui_story_5014_50140502_34_dialog_content = "Siapa kamu?",
  ui_story_5014_50140502_35_dialog_content = "Berhenti. Jangan mendekat.",
  ui_story_5014_50140502_36_dialog_content = "Droid prajurit, bersiaplah untuk bertempur.",
  ui_story_5014_50140502_37_dialog_content = "Siap.",
  ui_story_5014_50140502_38_dialog_content = "Dulu aku pernah melihat jenis Luminatics yang dia gunakan...",
  ui_story_5014_50140502_39_dialog_content = "Lebih tepatnya, ini sihir teknologi Illumina... Machinomancy.",
  ui_story_5014_50140502_40_dialog_content = "Illumina?",
  ui_story_5014_50140502_41_dialog_content = "Benar. Tolong berhenti. Kami tidak bermaksud jahat. Kami hanya mencari...",
  ui_story_5014_50140502_42_dialog_content = "Rekan kerja kami.",
  ui_story_5014_50140601_1_dialog_content = "Sinyalnya berasal dari bangunan di belakangnya.",
  ui_story_5014_50140601_2_dialog_content = "Kamu...",
  ui_story_5014_50140601_3_dialog_content = "Hai, aku Vice. Kami Aurorian dari Illumina.",
  ui_story_5014_50140601_4_dialog_content = "Kami kemari karena menerima sinyal bahaya.",
  ui_story_5014_50140601_5_dialog_content = "Apa kamu...",
  ui_story_5014_50140601_6_dialog_content = "Berasal dari Illumina Federation?",
  ui_story_5014_50140601_7_dialog_content = "Benar, kami dari Illumina Federation!",
  ui_story_5014_50140601_8_dialog_content = "Siapa namamu? Apa kamu juga berasal dari Illumina?",
  ui_story_5014_50140601_9_dialog_content = "Namaku Valencia, aku bukan orang Illumina.",
  ui_story_5014_50140601_10_dialog_content = "Baiklah, Valencia. Bolehkah kami masuk?",
  ui_story_5014_50140601_11_dialog_content = "Seharusnya ada Communicator Illumina seperti ini.",
  ui_story_5014_50140601_12_dialog_content = "(Itu sama dengan alat peninggalan Ayah!)",
  ui_story_5014_50140601_13_dialog_content = "Aku pernah dengar tentang Illumina, tapi Ayah bilang...",
  ui_story_5014_50140601_14_dialog_content = "Jangan dengarkan mereka, Kak!",
  ui_story_5014_50140601_15_dialog_content = "Butler bilang orang luar berbahaya!",
  ui_story_5014_50140601_16_dialog_content = "Sedang apa kamu di sini, Gretel?",
  ui_story_5014_50140601_17_dialog_content = "Aku dengar semuanya... Mereka pasti berbohong padamu.",
  ui_story_5014_50140601_18_dialog_content = "Tapi, Ayah bilang kalau aku bertemu orang Illumina, kita harus...",
  ui_story_5014_50140601_19_dialog_content = "Mereka penyusup dan orang asing yang menghancurkan tempat ini!",
  ui_story_5014_50140601_20_dialog_content = "Apa Kakak sudah lupa berapa banyak droid yang mereka hancurkan?",
  ui_story_5014_50140601_21_dialog_content = "Sebentar, aku tak pernah menghancurkan...",
  ui_story_5014_50140601_22_dialog_content = "Diam!",
  ui_story_5014_50140601_23_dialog_content = "Ayah melarang kita bicara dengan orang asing!",
  ui_story_5014_50140601_24_dialog_content = "Apa kamu mengendalikan droid?",
  ui_story_5014_50140601_25_dialog_content = "Kami terpaksa menghancurkan beberapa droid.",
  ui_story_5014_50140601_26_dialog_content = "Apa kalian tinggal di sini sejak dulu? Di mana orang tua kalian?",
  ui_story_5014_50140601_27_dialog_content = "Kenapa kalian bicara terus? Ini rumahku. Keluar! Pergi!",
  ui_story_5014_50140601_28_dialog_content = "Meskipun ingin, aku tak bisa keluar dari sini.",
  ui_story_5014_50140601_29_dialog_content = "Apa mereka rekan kerja Aurorian-mu, Siobhan?",
  ui_story_5014_50140601_30_dialog_content = "Berhentilah menggangguku. Aku sedang mencoba berpikir.",
  ui_story_5014_50140601_31_dialog_content = "Siapa nama ayah kalian?",
  ui_story_5014_50140601_32_dialog_content = "Grey, Yuswen, Shaw, Seamus, Iv...",
  ui_story_5014_50140601_33_dialog_content = "Sebentar, nama ayahku adalah Seamus.",
  ui_story_5014_50140601_34_dialog_content = "Seamus? Kalian anak-anak Seamus?!",
  ui_story_5014_50140601_35_dialog_content = "Seamus adalah seniorku. Dia menghilang lebih dari satu dekade yang lalu.",
  ui_story_5014_50140601_36_dialog_content = "Kukira dia sudah mati.",
  ui_story_5014_50140601_37_dialog_content = "Tak kusangka dia masih hidup dan punya anak...",
  ui_story_5014_50140601_38_dialog_content = "Cepat, antar aku kepada ayah kalian!",
  ui_story_5014_50140601_39_dialog_content = "Ada banyak hal yang ingin kubicarakan dengannya.",
  ui_story_5014_50140601_40_dialog_content = "Tidak bisa... Dia sudah meninggal.",
  ui_story_5014_50140601_41_dialog_content = "Jangan beri tahu mereka!",
  ui_story_5014_50140601_42_dialog_content = "Butler melarang kita bicara kepada orang luar!",
  ui_story_5014_50140601_43_dialog_content = "Mereka kemari untuk merampok kita!",
  ui_story_5014_50140601_44_dialog_content = "Merampok kita...",
  ui_story_5014_50140601_45_dialog_content = "Maaf, tapi aku harus menyela.",
  ui_story_5014_50140601_46_dialog_content = "Aku merasakan para Eclipsite menuju kemari. Sebaiknya kita...",
  ui_story_5014_50140601_47_dialog_content = "Lihat, 'kan? Mereka mencuri pakaian kita!",
  ui_story_5014_50140601_48_dialog_content = "Yang itu malah menyobek pakaianmu!",
  ui_story_5014_50140601_49_dialog_content = "Tidak, tidak, kalian salah paham! Aku hanya...",
  ui_story_5014_50140601_50_dialog_content = "Graaah!",
  ui_story_5014_50140601_51_dialog_content = "Awas! Mereka datang!",
  ui_story_5014_50140601_52_dialog_content = "Kita teruskan nanti. Sekarang saatnya bertarung.",
  ui_story_5014_50140601_53_dialog_content = "Cari tempat aman untuk sembunyi, Valencia.",
  ui_story_5014_50140601_54_dialog_content = "Biar kami saja yang menghadapi Eclipsite.",
  ui_story_5014_50140601_55_dialog_content = "Baiklah...",
  ui_story_5014_50140602_1_dialog_content = "Rasanya mereka bisa dipercaya, Gretel.",
  ui_story_5014_50140602_2_dialog_content = "Mungkin mereka rekan kerja Aurorian yang diceritakan Ayah.",
  ui_story_5014_50140602_3_dialog_content = "Sebaiknya kita bicara kepada mereka dan mencari tahu.",
  ui_story_5014_50140602_4_dialog_content = "Orang luar rela bertarung satu sama lain demi sumber daya, dan sanggup melakukan apa saja demi kepentingan mereka sendiri...",
  ui_story_5014_50140602_5_dialog_content = "Mereka pasti akan berbohong demi mencapai tujuan.",
  ui_story_5014_50140602_6_dialog_content = "Itu yang Butler ajarkan kepada kita. Aku jadi makin percaya padanya.",
  ui_story_5014_50140602_7_dialog_content = "Mereka bukan Eclipsite, tapi juga bukan orang baik.",
  ui_story_5014_50140602_8_dialog_content = "Tapi, sekarang mereka melawan Eclipsite dan menyuruh kita sembunyi di tempat aman.",
  ui_story_5014_50140602_9_dialog_content = "Bukankah mereka melindungi kita?",
  ui_story_5014_50140602_10_dialog_content = "Mereka memang harus melawan Eclipsite. Itu tak ada hubungannya dengan melindungi kita!",
  ui_story_5014_50140602_11_dialog_content = "Tapi...",
  ui_story_5014_50140602_12_dialog_content = "Graaah!",
  ui_story_5014_50140602_13_dialog_content = "Selesai.",
  ui_story_5014_50140602_14_dialog_content = "Apa kita akan bicara kepada kakak beradik itu?",
  ui_story_5014_50140602_15_dialog_content = "Melihat situasinya, sepertinya itu akan sulit.",
  ui_story_5014_50140602_16_dialog_content = "Maaf, aku tak bermaksud menyela pembicaraan kalian.",
  ui_story_5014_50140602_17_dialog_content = "Tidak apa-apa, bukan salahmu.",
  ui_story_5014_50140602_18_dialog_content = "Biar kupikir dulu...",
  ui_story_5014_50140602_19_dialog_content = "Seamus yang kamu sebut tadi, apakah dia si legendaris...",
  ui_story_5014_50140602_20_dialog_content = "Benar. Master Seamus, pakar reruntuhan terhebat di Illumina selama 30 tahun terakhir.",
  ui_story_5014_50140602_21_dialog_content = "Seamus yang selalu melakukan ekspedisi sendirian itu? Astaga!",
  ui_story_5014_50140602_22_dialog_content = "Di buku tertulis bahwa Master Seamus telah hilang sejak lama.",
  ui_story_5014_50140602_23_dialog_content = "Benar. Pesan terakhirnya kepada markas dikirim lebih dari 10 tahun yang lalu dari tundra.",
  ui_story_5014_50140602_24_dialog_content = "Pasti dialah orangnya...",
  ui_story_5014_50140602_25_dialog_content = "Kalau begitu, pasti dia juga yang mengirim sinyal itu.",
  ui_story_5014_50140602_26_dialog_content = "Benar. Aku akan bicara kepada mereka.",
  ui_story_5014_50140602_27_dialog_content = "Mungkin aku ikut juga.",
  ui_story_5014_50140602_28_dialog_content = "Memangnya apa yang akan kamu katakan pada mereka?",
  ui_story_5014_50140602_29_dialog_content = "Aku ingin berganti pakaian, tapi aku juga tak mau diserang droid.",
  ui_story_5014_50140602_30_dialog_content = "Karena mereka mengendalikan robot-robot itu...",
  ui_story_5014_50140602_31_dialog_content = "Ehem, biar aku saja.",
  ui_story_5014_50140602_32_dialog_content = "Valencia, Gretel, kami berhasil menyingkirkan para Eclipsite itu.",
  ui_story_5014_50140602_33_dialog_content = "Mari kita bicara.",
  ui_story_5014_50140602_34_dialog_content = "Apa yang kamu bawa, Valencia?",
  ui_story_5014_50140602_35_dialog_content = "Hentikan, Gretel. Aku ingin menanyakan sesuatu kepadanya.",
  ui_story_5014_50140602_36_dialog_content = "Apa kamu tahu ini, Siobhan?",
  ui_story_5014_50140602_37_dialog_content = "Bukankah itu Exploration Badge yang diberikan Illumination kepada para penjelajah yang telah memberikan kontribusi besar?",
  ui_story_5014_50140602_38_dialog_content = "Ya. Itu lencana versi lama, dan merupakan tingkat penghargaan tertinggi.",
  ui_story_5014_50140602_39_dialog_content = "Meski tak melihatnya, aku tahu ada nama Seamus tertulis di situ.",
  ui_story_5014_50140602_40_dialog_content = "Benar. Ayah mewariskan ini.",
  ui_story_5014_50140602_41_dialog_content = "Apa Seamus... ayahmu meninggalkan pesan?",
  ui_story_5014_50140602_42_dialog_content = "Dia terus mengirim sinyal menggunakan Communicator Illumina.",
  ui_story_5014_50140602_43_dialog_content = "Kurasa ada yang ingin dia sampaikan.",
  ui_story_5014_50140602_44_dialog_content = "Dia...",
  ui_story_5014_50140602_45_dialog_content = "Jangan bicara lagi, Valencia!",
  ui_story_5014_50140602_46_dialog_content = "Apa kamu mau memberi tahu mereka segalanya?",
  ui_story_5014_50140602_47_dialog_content = "Kalau Butler sampai mati, itu salahmu!",
  ui_story_5014_50140602_48_dialog_content = "Aku tahu mana yang harus kukatakan dan mana yang tidak, Gretel!",
  ui_story_5014_50140602_49_dialog_content = "Bip... Bip...",
  ui_story_5014_50140602_50_dialog_content = "<color=#e8d9bb>Di sini... tidak aman...</color>",
  ui_story_5014_50140602_51_dialog_content = "Butler? Ada apa?",
  ui_story_5014_50140602_52_dialog_content = "<color=#e8d9bb>Eclipsite... datang.</color>",
  ui_story_5014_50140602_53_dialog_content = "<color=#e8d9bb>Tolong ikutlah denganku... ke tempat aman...</color>",
  ui_story_5014_50140602_54_dialog_content = "Ayo pergi, Valencia.",
  ui_story_5014_50140602_55_dialog_content = "Tapi, aku tidak merasakan Eclipsite di sekitar sini.",
  ui_story_5014_50140602_56_dialog_content = "Memangnya kita harus pergi?",
  ui_story_5014_50140602_57_dialog_content = "Tahu apa kamu?!",
  ui_story_5014_50140602_58_dialog_content = "Butler selalu benar!",
  ui_story_5014_50140602_59_dialog_content = "Ayo, Valencia. Kita pergi!",
  ui_story_5014_50140701_1_dialog_content = "Beri tahu kami lebih banyak tentang keluargamu, Valencia.",
  ui_story_5014_50140701_2_dialog_content = "Apakah ibumu juga peneliti dari Illumina?",
  ui_story_5014_50140701_3_dialog_content = "Bukan, dia berasal dari Lumopolis.",
  ui_story_5014_50140701_4_dialog_content = "Sepertinya istilah yang tepat adalah \"bangsawan\". Iya, 'kan?",
  ui_story_5014_50140701_5_dialog_content = "Ibumu bangsawan Lumopolis?",
  ui_story_5014_50140701_6_dialog_content = "Mungkin aku tahu dia. Siapa namanya?",
  ui_story_5014_50140701_7_dialog_content = "Ayah menyebutnya \"Nimbus\".",
  ui_story_5014_50140701_8_dialog_content = "Nimbus... Kedengarannya seperti nama samaran.",
  ui_story_5014_50140701_9_dialog_content = "Dia pernah bercerita tentang Lumopolis?",
  ui_story_5014_50140701_10_dialog_content = "Tidak juga. Dia tidak mau membicarakan masa lalunya di dunia luar.",
  ui_story_5014_50140701_11_dialog_content = "Kamu tahu bagaimana dia bisa kemari?",
  ui_story_5014_50140701_12_dialog_content = "Ayah bilang mereka tak sengaja kemari dan tak pernah menemukan jalan keluar.",
  ui_story_5014_50140701_13_dialog_content = "Aku tidak terlalu ingat karena masih kecil saat itu.",
  ui_story_5014_50140701_14_dialog_content = "Hmph!",
  ui_story_5014_50140701_15_dialog_content = "Sepertinya adikmu marah, Valencia. Apa ada masalah?",
  ui_story_5014_50140701_16_dialog_content = "Berhentilah bicara!",
  ui_story_5014_50140701_17_dialog_content = "Hei, kenapa kamu bersikap jahat padaku?",
  ui_story_5014_50140701_18_dialog_content = "Kenapa kamu masih marah, Gretel?",
  ui_story_5014_50140701_19_dialog_content = "Kenapa kamu menceritakan segalanya kepada mereka?",
  ui_story_5014_50140701_20_dialog_content = "Bukankah aku sudah bilang mereka bisa dipercaya?",
  ui_story_5014_50140701_21_dialog_content = "Jadi, kamu mau mengabaikan nasihat Butler?",
  ui_story_5014_50140701_22_dialog_content = "Teganya kamu bicara seperti itu padaku?",
  ui_story_5014_50140701_23_dialog_content = "<color=#e8d9bb>Cara yang baik... untuk menyelesaikan konflik adalah dengan... berkomunikasi.</color>",
  ui_story_5014_50140701_24_dialog_content = "Aku tidak peduli. Valencia yang salah!",
  ui_story_5014_50140701_25_dialog_content = "Ayo, Butler. Tinggalkan saja dia!",
  ui_story_5014_50140701_26_dialog_content = "Maaf, kami tidak bermaksud membuat kalian bertengkar...",
  ui_story_5014_50140701_27_dialog_content = "Tapi, kami berusaha untuk membuktikan bahwa kami berasal dari Illumina.",
  ui_story_5014_50140701_28_dialog_content = "Kenapa dia masih memusuhi kami?",
  ui_story_5014_50140701_29_dialog_content = "Sebenarnya, orang tua kami tewas karena serangan Eclipsite tak lama setelah Gretel lahir.",
  ui_story_5014_50140701_30_dialog_content = "Aku belajar tentang dunia luar dari mereka, tapi sayangnya Gretel tidak.",
  ui_story_5014_50140701_31_dialog_content = "Hanya Butler dan aku yang merawatnya.",
  ui_story_5014_50140701_32_dialog_content = "Begitu rupanya. Sepertinya kehadiran kami yang mendadak telah membuatnya tidak nyaman.",
  ui_story_5014_50140701_33_dialog_content = "Iya.",
  ui_story_5014_50140701_34_dialog_content = "Aku ingin memberitahunya lebih banyak tentang ibu dan ayah kami, tapi aku sendiri juga tidak terlalu paham.",
  ui_story_5014_50140701_35_dialog_content = "Berkas dan naskah ayahmu tersimpan di Illumina.",
  ui_story_5014_50140701_36_dialog_content = "Kalau mau, aku bisa menceritakannya padamu.",
  ui_story_5014_50140701_37_dialog_content = "Aku mau!",
  ui_story_5014_50140701_38_dialog_content = "Ayahmu adalah pakar reruntuhan dan teknologi kuno, serta penjelajahan.",
  ui_story_5014_50140701_39_dialog_content = "Tahu tidak?",
  ui_story_5014_50140701_40_dialog_content = "Aku tahu. Dia meneruskan penelitiannya di lokasi ini.",
  ui_story_5014_50140701_41_dialog_content = "Dia menyebutnya Ancient City dan para droid itu, \"Teknologi kuno yang hebat\".",
  ui_story_5014_50140701_42_dialog_content = "Dia bahkan memperbaiki banyak droid dan modul sistem dengan Butler.",
  ui_story_5014_50140701_43_dialog_content = "Dia pernah menulis esai tentang perbaikan mesin kuno.",
  ui_story_5014_50140701_44_dialog_content = "Mesin jual otomatis, drone pengantar kaleng, dan pabrik kaleng...",
  ui_story_5014_50140701_45_dialog_content = "Diperbaiki oleh ayahmu, 'kan?",
  ui_story_5014_50140701_46_dialog_content = "Ya, beberapa.",
  ui_story_5014_50140701_47_dialog_content = "Dia bilang beberapa bisa berfungsi sepenuhnya.",
  ui_story_5014_50140701_48_dialog_content = "Yang mana?",
  ui_story_5014_50140701_49_dialog_content = "Pabrik. Dia tidak banyak memperbaikinya.",
  ui_story_5014_50140701_50_dialog_content = "Butler yang mengoperasikan dan menghentikan produksi di pabrik.",
  ui_story_5014_50140701_51_dialog_content = "Pembuatan pakaian dan makanan di pabrik bersifat otomatis. Kemudian hasilnya dibawa ke supermarket.",
  ui_story_5014_50140701_52_dialog_content = "Supermarket? Apa itu?",
  ui_story_5014_50140701_53_dialog_content = "Oh, segalanya ada di sana. Kita boleh mengambil apa pun yang kita mau.",
  ui_story_5014_50140701_54_dialog_content = "Semuanya serba otomatis... Aku tidak paham lagi...",
  ui_story_5014_50140701_55_dialog_content = "Otomatisasi kaum Ancient memang luar biasa...",
  ui_story_5014_50140701_56_dialog_content = "Seperti apa rutinitas harian kalian?",
  ui_story_5014_50140701_57_dialog_content = "Yah, biasa saja...?",
  ui_story_5014_50140701_58_dialog_content = "Aku mau tanya lagi. Bagaimana kalau pakaian kalian kotor?",
  ui_story_5014_50140701_59_dialog_content = "Kami tinggal menaruhnya di mesin cuci, lalu mesin itu yang akan membersihkannya.",
  ui_story_5014_50140701_60_dialog_content = "Bagaimana kalau kalian ingin mandi?",
  ui_story_5014_50140701_61_dialog_content = "Kami tinggal memberi tahu Butler, lalu para droid akan memanaskan airnya.",
  ui_story_5014_50140701_62_dialog_content = "Lalu bagaimana kalau kalian ingin membersihkan kamar?",
  ui_story_5014_50140701_63_dialog_content = "Kami tinggal memberi tahu Butler. Para droid akan datang untuk membersihkannya.",
  ui_story_5014_50140701_64_dialog_content = "Nah, bagaimana kalau kalian ingin membaca buku?",
  ui_story_5014_50140701_65_dialog_content = "Kami tinggal memberi tahu Butler. Sebuah droid akan menampilkan isi buku itu.",
  ui_story_5014_50140701_66_dialog_content = "Bagaimana kalau kalian harus mengerjakan tugas dan menulis laporan?",
  ui_story_5014_50140701_67_dialog_content = "Tugas? Laporan? Itu sudah dikerjakan para droid, 'kan?",
  ui_story_5014_50140701_68_dialog_content = "Astaga, kehidupan kalian benar-benar menyenangkan!",
  ui_story_5014_50140701_69_dialog_content = "Itu justru kehidupan yang mengerikan. Karena tidak perlu melakukan apa pun, kalian seolah-olah hidup di dalam kandang...",
  ui_story_5014_50140701_70_dialog_content = "Aku juga ingin menanyakan beberapa hal.",
  ui_story_5014_50140701_71_dialog_content = "Apa pertanyaanmu?",
  ui_story_5014_50140701_72_dialog_content = "Apa ada pabrik yang membuat pakaian pria?",
  ui_story_5014_50140701_73_dialog_content = "Oh, kurasa yang itu sedang tidak beroperasi karena berkasnya rusak.",
  ui_story_5014_50140701_74_dialog_content = "Apa? Apa yang dulu ayahmu kenakan?",
  ui_story_5014_50140701_75_dialog_content = "Seingatku ayahku memakai pakaian Illumina.",
  ui_story_5014_50140701_76_dialog_content = "Tapi, bukankah para droid akan menyerangnya...?",
  ui_story_5014_50140701_77_dialog_content = "Dengan aksesnya yang cukup luas, dia bisa membuat perjanjian dengan Butler untuk menghindari itu.",
  ui_story_5014_50140701_78_dialog_content = "Tolong izinkan aku bicara kepada Butler!",
  ui_story_5014_50140701_79_dialog_content = "Di mana dia? Di mana droid yang bernama Butler?",
  ui_story_5014_50140701_80_dialog_content = "Benar, aku juga mau bicara dengan Butler.",
  ui_story_5014_50140701_81_dialog_content = "Seharusnya sekarang dia ada di distrik industri.",
  ui_story_5014_50140701_82_dialog_content = "Kita sudah sampai.",
  ui_story_5014_50140701_83_dialog_content = "<color=#e8d9bb>Selamat datang. Aku Butler.</color>",
  ui_story_5014_50140701_84_dialog_content = "Para droid ini kelihatan baru!",
  ui_story_5014_50140701_85_dialog_content = "<color=#e8d9bb>Mereka... baru saja dimodifikasi.</color>",
  ui_story_5014_50140701_86_dialog_content = "Kenapa kamu bisa berbicara dengan bahasa kami, Butler?",
  ui_story_5014_50140701_87_dialog_content = "<color=#e8d9bb>Belajar dari... Seamus.</color>",
  ui_story_5014_50140701_88_dialog_content = "Kamu mempelajarinya sendiri?",
  ui_story_5014_50140701_89_dialog_content = "Siapa yang mengendalikanmu?",
  ui_story_5014_50140701_90_dialog_content = "<color=#e8d9bb>Kamu mirip... Seamus, Nona.</color>",
  ui_story_5014_50140701_91_dialog_content = "<color=#e8d9bb>Menurut... terminologimu.</color>",
  ui_story_5014_50140701_92_dialog_content = "<color=#e8d9bb>Aku... AI autodidak.</color>",
  ui_story_5014_50140701_93_dialog_content = "...",
  ui_story_5014_50140701_94_dialog_content = "<color=#e8d9bb>Aku mengendalikan kota... Tolong ikuti arahanku.</color>",
  ui_story_5014_50140701_95_dialog_content = "<color=#e8d9bb>Kalau tidak... rasakan akibatnya.</color>",
  ui_story_5014_50140701_96_dialog_content = "Apa kamu bisa mengantar kami pulang?",
  ui_story_5014_50140701_97_dialog_content = "Dengan begitu, aku tak perlu mencemaskan pakaian lagi.",
  ui_story_5014_50140701_98_dialog_content = "<color=#e8d9bb>Keamanan kota ini... sangat penting.</color>",
  ui_story_5014_50140701_99_dialog_content = "<color=#e8d9bb>Untuk menghindari lebih banyak... penyusup.</color>",
  ui_story_5014_50140701_100_dialog_content = "<color=#e8d9bb>Kalian tidak boleh... pergi.</color>",
  ui_story_5014_50140701_101_dialog_content = "<color=#e8d9bb>Kuulangi... Tolong ikuti arahanku.</color>",
  ui_story_5014_50140701_102_dialog_content = "Baiklah, akan kuikuti arahanmu, tapi ada yang harus kuketahui...",
  ui_story_5014_50140701_103_dialog_content = "Bisikan sarang iblis akan membuatmu gila... Tolong minggir.",
  ui_story_5014_50140701_104_dialog_content = "<color=#e8d9bb>Ting!</color>",
  ui_story_5014_50140701_105_dialog_content = "Sebaiknya kamu minggir.",
  ui_story_5014_50140701_106_dialog_content = "Sedang apa kamu, Erica?!",
  ui_story_5014_50140701_107_dialog_content = "Droid dengan AI autodidak yang bisa memperbaiki droid lain...",
  ui_story_5014_50140701_108_dialog_content = "Dia adalah musuh Inquisition dan target yang harus dihancurkan.",
  ui_story_5014_50140701_109_dialog_content = "Minggir! Jangan-jangan kamu mau membawa mereka ke Illumina!",
  ui_story_5014_50140701_110_dialog_content = "Kalau memang iya, memangnya kamu juga mau membunuhku?",
  ui_story_5014_50140701_111_dialog_content = "Kalian memang ancaman yang sangat berbahaya.",
  ui_story_5014_50140701_112_dialog_content = "Kemarilah, Valencia. Jangan dekat-dekat mereka!",
  ui_story_5014_50140701_113_dialog_content = "Sebentar, biar kujelaskan!",
  ui_story_5014_50140701_114_dialog_content = "Maaf, Gretel. Kurasa mereka tidak bermaksud menghancurkan Butler.",
  ui_story_5014_50140701_115_dialog_content = "Itu karena kamu memang mudah tertipu.",
  ui_story_5014_50140701_116_dialog_content = "Ini gara-gara para bandit dan tukang tipu ini!",
  ui_story_5014_50140701_117_dialog_content = "Kerahkan droid petarung, Butler.",
  ui_story_5014_50140701_118_dialog_content = "Habisi mereka!",
  ui_story_5014_50140702_1_dialog_content = "Gawat, para Eclipsite juga kemari.",
  ui_story_5014_50140702_2_dialog_content = "Belum lagi gelombang droid yang tak ada habisnya. Kita harus pergi dari sini.",
  ui_story_5014_50140702_3_dialog_content = "Valencia, Gretel, ikutlah dengan kami.",
  ui_story_5014_50140702_4_dialog_content = "Di sini terlalu berbahaya!",
  ui_story_5014_50140702_5_dialog_content = "Kenapa kamu bersusah payah meyakinkan mereka?",
  ui_story_5014_50140702_6_dialog_content = "Seharusnya cemaskan saja diri kalian!",
  ui_story_5014_50140702_7_dialog_content = "Kepung mereka, droid petarung!",
  ui_story_5014_50140702_8_dialog_content = "Bip... Bip...",
  ui_story_5014_50140702_9_dialog_content = "Kamu benar-benar ingin melihat kami mati, Valencia?",
  ui_story_5014_50140702_10_dialog_content = "...",
  ui_story_5014_50140702_11_dialog_content = "Kuserahkan ini padamu, Butler.",
  ui_story_5014_50140702_12_dialog_content = "Ayo, Gretel. Kita pergi ke tempat aman.",
  ui_story_5014_50140702_13_dialog_content = "Baiklah.",
  ui_story_5014_50140702_14_dialog_content = "Valencia!",
  ui_story_5014_50140702_15_dialog_content = "Lupakan saja. Sekarang kita musuh.",
  ui_story_5014_50140702_16_dialog_content = "Bukankah ini semua salahmu?",
  ui_story_5014_50140702_17_dialog_content = "Menyerang Butler tanpa provokasi?",
  ui_story_5014_50140702_18_dialog_content = "Butler? Kamu pikir dia manusia?",
  ui_story_5014_50140702_19_dialog_content = "Tidak, tapi dia keluarga mereka...",
  ui_story_5014_50140702_20_dialog_content = "Dia hanya AI!",
  ui_story_5014_50140702_21_dialog_content = "Ada apa dengan AI-nya? Itu masih keluarga mereka, 'kan?",
  ui_story_5014_50140702_22_dialog_content = "Kalau Soroz masih ada di sini, apa kamu akan menyerang?",
  ui_story_5014_50140702_23_dialog_content = "Soroz... Benar juga, kamu kan Navigator.",
  ui_story_5014_50140702_24_dialog_content = "Benar, aku Navigator Colossus. Aku terkurung selama 17 tahun di bawah tanah. Hanya Soroz yang aku miliki.",
  ui_story_5014_50140702_25_dialog_content = "Begitu juga dengan mereka. Mereka hanya punya pelayan itu.",
  ui_story_5014_50140702_26_dialog_content = "Apa tadi kamu sengaja menyerangnya untuk membuat onar?",
  ui_story_5014_50140702_27_dialog_content = "...",
  ui_story_5014_50140702_28_dialog_content = "Maaf. Kami tidak berpikir panjang.",
  ui_story_5014_50140702_29_dialog_content = "Presiden... Apa aku salah? Aku melakukannya... Seharusnya aku...",
  ui_story_5014_50140702_30_dialog_content = "Tidak, kamu hanya mempertahankan keyakinan kita.",
  ui_story_5014_50140702_31_dialog_content = "Rupanya demi kepercayaan pribadi...",
  ui_story_5014_50140702_32_dialog_content = "Ini bukan sekadar kepercayaan pribadi!",
  ui_story_5014_50140702_33_dialog_content = "Cukup. Sekarang kita harus keluar dari pabrik.",
  ui_story_5014_50140702_34_dialog_content = "<color=#e8d9bb>Sayangnya... Ini perintah Gretel.</color>",
  ui_story_5014_50140702_35_dialog_content = "<color=#e8d9bb>Kalian dikepung.</color>",
  ui_story_5014_50140702_36_dialog_content = "Kamu Butler? Kamu tidak seperti android sebelumnya...",
  ui_story_5014_50140702_37_dialog_content = "Dia bisa berpindah ke mesin lain dengan sesuka hati?",
  ui_story_5014_50140702_38_dialog_content = "Dia mengendalikan semua android di sini.",
  ui_story_5014_50140702_39_dialog_content = "Sekarang kita harus bagaimana?",
  ui_story_5014_50140702_40_dialog_content = "Kamu dan Erica harus memandu tim untuk keluar.",
  ui_story_5014_50140702_41_dialog_content = "Kalian pasti bisa mencari jalan keluar bersama-sama. Aku akan jaga bagian belakang.",
  ui_story_5014_50140702_42_dialog_content = "Tidak, musuh sangat banyak. Itu terlalu berbahaya untukmu.",
  ui_story_5014_50140702_43_dialog_content = "Aku akan tetap di sini!",
  ui_story_5014_50140702_44_dialog_content = "Kamu adalah penjelajah terhebat dari Lumopolis. Lebih baik kamu memimpin mereka meloloskan diri dari kepungan. Biar aku yang di sini.",
  ui_story_5014_50140702_45_dialog_content = "Inilah kesempatan terbaik kita untuk bertahan.",
  ui_story_5014_50140702_46_dialog_content = "Sebagai penjelajah hebat dari Illumina, kenapa bukan kamu saja yang memimpin pelarian? Biar aku yang menghadapi musuh.",
  ui_story_5014_50140702_47_dialog_content = "Jabatanku paling tinggi. Mana mungkin kubiarkan orang Lumopolis melindungiku?",
  ui_story_5014_50140702_48_dialog_content = "<color=#e8d9bb>Illumina dan Lumopolis... Terakhir kalinya kudengar perdebatan seperti ini...</color>",
  ui_story_5014_50140702_49_dialog_content = "<color=#e8d9bb>Saat Seamus dan Nimbus masih ada.</color>",
  ui_story_5014_50140702_50_dialog_content = "Apa maksudmu?",
  ui_story_5014_50140702_51_dialog_content = "<color=#e8d9bb>Kalian para Aurorian memang cukup menarik.</color>",
  ui_story_5014_50140702_52_dialog_content = "Jadi, kamu... Cara bicaramu makin mirip dengan kami.",
  ui_story_5014_50140702_53_dialog_content = "<color=#e8d9bb>Aku adalah AI yang bisa belajar.</color>",
  ui_story_5014_50140702_54_dialog_content = "Semoga kamu belum belajar memimpin pertempuran dari Seamus...",
  ui_story_5014_50140702_55_dialog_content = "PlayerName, Florine dan aku akan menjaga bagian belakang. Pimpin tim untuk meloloskan diri dari kepungan. Cepat!",
  ui_story_5014_50140702_56_dialog_content = "Erica, lindungi Yang Mulia Putri Carleen!",
  ui_story_5014_50140702_57_dialog_content = "Siap, Presiden.",
  ui_story_5014_50140702_58_dialog_content = "Baiklah. Aku akan mengambil alih komando pertempuran.",
  ui_story_5014_50140801_1_dialog_content = "Bagaimana ini? Para android itu makin dekat.",
  ui_story_5014_50140801_2_dialog_content = "Lari lebih cepat. Kita sudah berusaha keras untuk meloloskan diri dari kepungan...",
  ui_story_5014_50140801_3_dialog_content = "<color=#e8d9bb>Gruk!</color>",
  ui_story_5014_50140801_4_dialog_content = "Ada gempa bumi lagi. Waspadai batu-batu yang berguguran!",
  ui_story_5014_50140801_5_dialog_content = "Ada tempat terbuka di sebelah sana. Biar kutunjukkan jalannya.",
  ui_story_5014_50140801_6_dialog_content = "<size=30><color=#e8d9bb>Duar...</color></size>",
  ui_story_5014_50140801_7_dialog_content = "<color=#e8d9bb>Awas... Gempa...</color>",
  ui_story_5014_50140801_8_dialog_content = "<color=#e8d9bb>Bip... Bip.</color>",
  ui_story_5014_50140801_9_dialog_content = "Android jahat itu hancur.",
  ui_story_5014_50140801_10_dialog_content = "Master Siobhan bilang gempa bumi itu mungkin memengaruhi fasilitas di sini.",
  ui_story_5014_50140801_11_dialog_content = "Mungkin Butler kehilangan kendali atas para droid itu untuk sementara...",
  ui_story_5014_50140801_12_dialog_content = "<color=#e8d9bb>Ksss... Ksss.</color>",
  ui_story_5014_50140801_13_dialog_content = "Communicator milikku berbunyi lagi.",
  ui_story_5014_50140801_14_dialog_content = "Sumber sinyalnya sama?",
  ui_story_5014_50140801_15_dialog_content = "Berbeda. Yang ini memiliki sandi enkripsi. Aku harus menguraikan kodenya dulu.",
  ui_story_5014_50140801_16_dialog_content = "Apa bedanya? Yang sebelumnya juga menggunakan sandi enkripsi.",
  ui_story_5014_50140801_17_dialog_content = "Communicator yang digunakan Illumina Expedition bisa mengirim data terenkripsi pada satu sama lain...",
  ui_story_5014_50140801_18_dialog_content = "Yang terakhir adalah sinyal posisi. Dan ini adalah siaran data.",
  ui_story_5014_50140801_19_dialog_content = "Gempa bumi itu mungkin telah memicunya di alat Seamus.",
  ui_story_5014_50140801_20_dialog_content = "Apa yang Seamus siarkan?",
  ui_story_5014_50140801_21_dialog_content = "Aku tidak begitu mengenal sistem enkripsi mereka. Aku bisa membaca sebagian dengan kunci umum ekspedisi itu.",
  ui_story_5014_50140801_22_dialog_content = "Sebentar!",
  ui_story_5014_50140801_23_dialog_content = "<size=30><color=#e8d9bb>Gruk...</color></size>",
  ui_story_5014_50140801_24_dialog_content = "Vice, apa isinya?",
  ui_story_5014_50140801_25_dialog_content = "Hanya beberapa informasi terputus-putus yang tersisa dari sesi berbeda.",
  ui_story_5014_50140801_26_dialog_content = "Biar kubacakan...",
  ui_story_5014_50140801_27_dialog_content = "Di bagian pertama, dia menyebut pertempuran kuno.",
  ui_story_5014_50140801_28_dialog_content = "Apa pertempurannya terjadi di sini? Kok aku tidak pernah tahu...",
  ui_story_5014_50140801_29_dialog_content = "Kejadiannya sudah sangat lama. Pertempuran kuno itu tidak tercatat dalam dokumen sejarah mana pun.",
  ui_story_5014_50140801_30_dialog_content = "Tapi, banyak sejarawan sangat percaya pada sejarah itu.",
  ui_story_5014_50140801_31_dialog_content = "Seamus bilang kota ini adalah sisa tempat perlindungan besar yang dibuat oleh kaum Ancient.",
  ui_story_5014_50140801_32_dialog_content = "Kota ini dibangun untuk menghindari pertempuran atau mencegah bencana berikutnya.",
  ui_story_5014_50140801_33_dialog_content = "Tapi, kaum Ancient sudah dibinasakan sepenuhnya, dan hanya meninggalkan AI yang bernama Butler.",
  ui_story_5014_50140801_34_dialog_content = "Dialah penanggung jawab semua fasilitas di sini. Dia tak mau menjawab satu pun pertanyaanku tentang masa lalu.",
  ui_story_5014_50140801_35_dialog_content = "Waktu dan ruang di sini sangat aneh, tapi alasan di baliknya masih belum jelas.",
  ui_story_5014_50140801_36_dialog_content = "Aku tidak bisa memecahkan bagian selanjutnya. Sistem multicrypt-nya rumit.",
  ui_story_5014_50140801_37_dialog_content = "Kenapa harus dibuat sangat rumit?",
  ui_story_5014_50140801_38_dialog_content = "Datanya diberi sandi enkripsi untuk alasan keamanan. Isinya pasti informasi yang sangat penting.",
  ui_story_5014_50140801_39_dialog_content = "Aku harus mencatatnya dan membawanya kembali ke Illumina agar Master Siobhan bisa memecahkannya.",
  ui_story_5014_50140801_40_dialog_content = "Baiklah. Apa lagi yang dikirim Seamus?",
  ui_story_5014_50140801_41_dialog_content = "Di bagian kedua siaran, dia mencatat pertemuannya dengan seorang wanita muda dari Lumopolis sebelum memasuki tempat ini.",
  ui_story_5014_50140801_42_dialog_content = "Aku bertemu dengan seorang wanita dari Lumopolis saat menjelajahi tundra.",
  ui_story_5014_50140801_43_dialog_content = "Secara kebetulan kami melarikan diri ke kota ini saat diserang Eclipsite.",
  ui_story_5014_50140801_44_dialog_content = "Wanita muda itu pasti istrinya, 'kan?",
  ui_story_5014_50140801_45_dialog_content = "Benar, saat menyadari bahwa mereka terjebak di dalam, keduanya pun menjadi sepasang kekasih...",
  ui_story_5014_50140801_46_dialog_content = "Tidak ada fasilitas pembuatan senjata di kota ini. Butler juga tidak bisa melindungi kami dengan efektif.",
  ui_story_5014_50140801_47_dialog_content = "Untungnya, kami berhasil memperbaiki modul biokimia sistem.",
  ui_story_5014_50140801_48_dialog_content = "Butler menyebutnya Abby. Dia membantu kami bertahan dari krisis Eclipsite.",
  ui_story_5014_50140801_49_dialog_content = "Modul biokimia apa? Namanya Abby?",
  ui_story_5014_50140801_50_dialog_content = "Abby juga bisa menjadi modul biologis. Aku tidak yakin apa yang dimaksudnya.",
  ui_story_5014_50140801_51_dialog_content = "Bagian selanjutnya dicatat bertahun-tahun setelahnya...",
  ui_story_5014_50140801_52_dialog_content = "Jumlah Eclipsite terus bertambah. Kami tidak yakin dari mana mereka masuk.",
  ui_story_5014_50140801_53_dialog_content = "Tentu saja Butler menolak menjawab pertanyaan ini.",
  ui_story_5014_50140801_54_dialog_content = "Aku butuh solusi efektif untuk melawan para penyusup ini. Akan lebih baik lagi kalau aku bisa menemukan jalan keluar.",
  ui_story_5014_50140801_55_dialog_content = "Butler mengawasiku. Aku harus sembunyi.",
  ui_story_5014_50140801_56_dialog_content = "Wahai umat manusia, kuharap kalian akan menerima pesan ini...",
  ui_story_5014_50140801_57_dialog_content = "Lalu ada satu lagi...",
  ui_story_5014_50140801_58_dialog_content = "Mungkin aku sudah mati saat kalian membaca ini.",
  ui_story_5014_50140801_59_dialog_content = "Tapi, aku sudah tahu cara melindungi mereka. Aku membuat kesepakatan dengan Butler...",
  ui_story_5014_50140801_60_dialog_content = "Istri dan putriku akan tinggal di sini dengan aman.",
  ui_story_5014_50140801_61_dialog_content = "Tolong jaga mereka... Tolong bawa mereka keluar dari kota ini.",
  ui_story_5014_50140801_62_dialog_content = "Ada informasi yang kutinggalkan di kamarku. Koordinatnya adalah...",
  ui_story_5014_50140801_63_dialog_content = "Berapa koordinatnya?",
  ui_story_5014_50140801_64_dialog_content = "Hmm... Maaf... Aku tak bisa menguraikan lokasinya.",
  ui_story_5014_50140801_65_dialog_content = "Apa lagi yang dia katakan?",
  ui_story_5014_50140801_66_dialog_content = "Kata-kata terakhirnya adalah, \"Rekan-rekan sebangsa Illumina... aku mengandalkan kalian.\"",
  ui_story_5014_50140801_67_dialog_content = "Jayalah Illumina!",
  ui_story_5014_50140801_68_dialog_content = "Itu saja?",
  ui_story_5014_50140801_69_dialog_content = "Ya, hanya itu yang bisa kuuraikan dari siaran data.",
  ui_story_5014_50140801_70_dialog_content = "<size=30><color=#e8d9bb>Gruk...</color></size>",
  ui_story_5014_50140801_71_dialog_content = "Ada gempa susulan lagi... Aku ingin tahu bagaimana keadaan Guru Siobhan...",
  ui_story_5014_50140801_72_dialog_content = "Hmm...",
  ui_story_5014_50140801_73_dialog_content = "Jangan khawatir. Vice bilang gempa bumi mungkin memengaruhi kendali Butler atas android.",
  ui_story_5014_50140801_74_dialog_content = "Sepertinya tak butuh waktu lama bagi mereka untuk melumpuhkan mesin-mesin itu dan bertemu kita.",
  ui_story_5014_50140801_75_dialog_content = "Terima kasih... Yang Mulia Putri Carleen.",
  ui_story_5014_50140801_76_dialog_content = "<color=#e8d9bb>Hentikan... Perjuangan sia-sia...</color>",
  ui_story_5014_50140801_77_dialog_content = "<color=#e8d9bb>Menyerahlah... Sekarang.</color>",
  ui_story_5014_50140801_78_dialog_content = "Florine, sekarang saatnya!",
  ui_story_5014_50140801_79_dialog_content = "Baiklah. Aku tidak butuh aba-abamu.",
  ui_story_5014_50140801_80_dialog_content = "Bagikan hukumannya, Wrath dari Razer!",
  ui_story_5014_50140801_81_dialog_content = "<color=#e8d9bb>Ksss! Duar!</color>",
  ui_story_5014_50140801_82_dialog_content = "<color=#e8d9bb>Ini Luminatics-mu?</color>",
  ui_story_5014_50140801_83_dialog_content = "<color=#e8d9bb>Sungguh menarik... Ini pantas dipelajari.</color>",
  ui_story_5014_50140801_84_dialog_content = "Menyebalkan sekali! Dia berpindah ke android lain.",
  ui_story_5014_50140801_85_dialog_content = "Pertempuran ini tak akan ada habisnya selama dia masih memimpin para android itu.",
  ui_story_5014_50140801_86_dialog_content = "Sebaiknya kita berusaha keluar selagi bisa.",
  ui_story_5014_50140801_87_dialog_content = "Tidak mudah. Butler memang membiarkan Carleen pergi, tapi dia mengawasi kita...",
  ui_story_5014_50140801_88_dialog_content = "Butler, apa mau kubacakan pesan dari Seamus?",
  ui_story_5014_50140801_89_dialog_content = "<color=#e8d9bb>Keamanan kota ini adalah prioritasku.</color>",
  ui_story_5014_50140801_90_dialog_content = "Aku mengerti. Ini demi keamanan informasi.",
  ui_story_5014_50140801_91_dialog_content = "Kalau terus menunda-nunda lagi, akan fatal akibatnya.",
  ui_story_5014_50140801_92_dialog_content = "Kamu perhatikan tidak? Para android ini makin kuat.",
  ui_story_5014_50140801_93_dialog_content = "Benar, dia mempelajari gaya bertarung kita.",
  ui_story_5014_50140801_94_dialog_content = "Mengerikan, 'kan?",
  ui_story_5014_50140801_95_dialog_content = "Kalau AI terus berkembang seperti ini, pada akhirnya dia bisa jadi cukup kuat dan mampu menghancurkan Aurorian.",
  ui_story_5014_50140801_96_dialog_content = "Aku paham maksudmu. Tapi, ayo kita keluar dulu.",
  ui_story_5014_50140801_97_dialog_content = "<color=#e8d9bb>Kalian... Tidak boleh pergi.</color>",
  ui_story_5014_50140801_98_dialog_content = "<color=#e8d9bb>Kalian... Tidak bisa keluar.</color>",
  ui_story_5014_50140801_99_dialog_content = "<size=30><color=#e8d9bb>Gruk...</color></size>",
  ui_story_5014_50140801_100_dialog_content = "Ada gempa susulan lagi. Ayo kita serang bersama!",
  ui_story_5014_50140801_101_dialog_content = "Sudah kubilang aku tahu harus bagaimana!",
  ui_story_5014_50140801_102_dialog_content = "<color=#e8d9bb>Kalian... Kss...</color>",
  ui_story_5014_50140801_103_dialog_content = "Kita berhasil lolos dari kepungan. Ayo pergi!",
  ui_story_5014_50140801_104_dialog_content = "Sepertinya taktik penundaan juga berhasil pada android.",
  ui_story_5014_50140801_105_dialog_content = "Tidak akan mempan lagi.",
  ui_story_5014_50140801_106_dialog_content = "Sekarang kita harus bagaimana?",
  ui_story_5014_50140801_107_dialog_content = "Communicator milikku baru saja menerima siaran data dari Seamus. Benda ini berfungsi lagi.",
  ui_story_5014_50140801_108_dialog_content = "Kita harus mencari tempat yang aman untuk bertemu dengan Vice.",
  ui_story_5014_50140801_109_dialog_content = "Baik. Aku akan mengirim Alba untuk mencari tempat yang tidak ada androidnya.",
  ui_story_5014_50140801_110_dialog_content = "Silakan. Aku harus mengirim informasi kepada Valencia.",
  ui_story_5014_50140801_111_dialog_content = "Kenapa?",
  ui_story_5014_50140801_112_dialog_content = "Mereka putri rekanku.",
  ui_story_5014_50140801_113_dialog_content = "Seamus meninggalkan pesan yang berisi permintaan untuk menjaga putrinya.",
  ui_story_5014_50140801_114_dialog_content = "Aku tak akan menyerah untuk membujuk mereka...",
  ui_story_5014_50140801_115_dialog_content = "<color=#e8d9bb>Kss... Kss...</color>",
  ui_story_5014_50140801_116_dialog_content = "Butler, apa kamu membiarkan mereka pergi?",
  ui_story_5014_50140801_117_dialog_content = "<color=#e8d9bb>Sinyal... Terganggu...</color>",
  ui_story_5014_50140801_118_dialog_content = "<color=#e8d9bb>Demi... Keamanan kalian...</color>",
  ui_story_5014_50140801_119_dialog_content = "<color=#e8d9bb>Tolong... Sembunyi... Di sini.</color>",
  ui_story_5014_50140801_120_dialog_content = "Kita tak bisa melakukan apa pun... Harus menunggu Butler pulih.",
  ui_story_5014_50140801_121_dialog_content = "<color=#e8d9bb>Tik... Tik.</color>",
  ui_story_5014_50140801_122_dialog_content = "Kak, relik milik Ayah!",
  ui_story_5014_50140801_123_dialog_content = "Biar kulihat!",
  ui_story_5014_50140801_124_dialog_content = "<color=#e8d9bb>Kss... Kss...</color>",
  ui_story_5014_50140801_125_dialog_content = "Valencia... Gre... Aku tahu kalian akan... Menerima pesan ini.",
  ui_story_5014_50140801_126_dialog_content = "Aku ingin... Memberi tahu kalian...",
  ui_story_5014_50140801_127_dialog_content = "Kami adalah... Rekan... Ayahmu... Akan... Melindungimu.",
  ui_story_5014_50140801_128_dialog_content = "Membawa kalian... Pulang... Ke Illumina.",
  ui_story_5014_50140801_129_dialog_content = "Pesan dari Siobhan...",
  ui_story_5014_50140801_130_dialog_content = "Wanita itu?",
  ui_story_5014_50140801_131_dialog_content = "Ini rumah kita. Dia tak perlu membawa kita ke mana-mana!",
  ui_story_5014_50140901_1_dialog_content = "Guru Siobhan ingin bertemu di... Arah ini...",
  ui_story_5014_50140901_2_dialog_content = "Baiklah. Aku tahu arah mana yang tidak ada musuhnya. Ikuti aku.",
  ui_story_5014_50140901_3_dialog_content = "Bip... Bip.",
  ui_story_5014_50140901_4_dialog_content = "Ada patroli android di jalan di depan sana. Kita harus berjalan memutar.",
  ui_story_5014_50140901_5_dialog_content = "Lewat sini...",
  ui_story_5014_50140901_6_dialog_content = "Bip... Bip.",
  ui_story_5014_50140901_7_dialog_content = "Kenapa mesin-mesin ini jadi mengamuk lagi?",
  ui_story_5014_50140901_8_dialog_content = "Kak Ruby, hati-hati...",
  ui_story_5014_50140901_9_dialog_content = "<color=#e8d9bb>Dor... Dor!</color>",
  ui_story_5014_50140901_10_dialog_content = "Kamu takut apa? Kita akan menghabisi mereka semua.",
  ui_story_5014_50140901_11_dialog_content = "Tidak bisa, Kak Ruby. Kekerasan hanya akan membuat mereka makin agresif...",
  ui_story_5014_50140901_12_dialog_content = "Vice dan Carleen, ada Aurorian yang bertarung dengan android di depan sana!",
  ui_story_5014_50140901_13_dialog_content = "Jangan-jangan itu presiden?",
  ui_story_5014_50140901_14_dialog_content = "Jangan asal mengambil kesimpulan begitu. Aku jadi takut!",
  ui_story_5014_50140901_15_dialog_content = "Aku tak bisa menerima sinyal presiden. Bagaimana denganmu?",
  ui_story_5014_50140901_16_dialog_content = "(Mungkin yang dia maksud adalah telepati... Untuk beberapa alasan dia sangat memedulikan Florine.)",
  ui_story_5014_50140901_17_dialog_content = "Bukan Florine. Tapi, dua Aurorian itu dikepung android.",
  ui_story_5014_50140901_18_dialog_content = "Ada orang lain yang terjebak di tempat ini? Kita harus membantu mereka.",
  ui_story_5014_50140901_19_dialog_content = "Tapi, presiden...",
  ui_story_5014_50140901_20_dialog_content = "Florine baik-baik saja. Siobhan baru saja mengirim pesan.",
  ui_story_5014_50140901_21_dialog_content = "Vice, hubungi Siobhan.",
  ui_story_5014_50140901_22_dialog_content = "Beri tahu mereka bahwa kita akan datang setelah menyelamatkan dua Aurorian yang terkepung.",
  ui_story_5014_50140901_23_dialog_content = "Baiklah.",
  ui_story_5014_50140901_24_dialog_content = "Bip... Tolong berhenti menyabotase. Kumohon...",
  ui_story_5014_50140901_25_dialog_content = "Diam. Minggir sana!",
  ui_story_5014_50140901_26_dialog_content = "Hu... Kwek!",
  ui_story_5014_50140901_27_dialog_content = "Sialan! Beberapa Eclipsite mendekat!",
  ui_story_5014_50140901_28_dialog_content = "Bukan hanya Eclipsite. Lihat itu.",
  ui_story_5014_50140901_29_dialog_content = "Bukankah orang itu...",
  ui_story_5014_50140901_30_dialog_content = "Aku yakin dia Putri Carleen yang terkenal!",
  ui_story_5014_50140901_31_dialog_content = "Carleen, kamu kenal mereka?",
  ui_story_5014_50140901_32_dialog_content = "... Tidak. Ayo kita habisi musuh dulu.",
  ui_story_5014_50140902_1_dialog_content = "Pukulan tongkat super!",
  ui_story_5014_50140902_2_dialog_content = "Sebentar. Jangan di sana!",
  ui_story_5014_50140902_3_dialog_content = "<color=#e8d9bb>Duar!</color>",
  ui_story_5014_50140902_4_dialog_content = "PlayerName!!",
  ui_story_5014_50140902_5_dialog_content = "Aduh... Dia malah pingsan.",
  ui_story_5014_50140902_6_dialog_content = "Kalau kamu sampai melukainya, aku tak akan tinggal diam.",
  ui_story_5014_50140902_7_dialog_content = "Maaf... Aku melihat Eclipsite di dekatnya, jadi...",
  ui_story_5014_50140902_8_dialog_content = "Tapi, aku tidak mengenainya, kok.",
  ui_story_5014_50140902_9_dialog_content = "Kamu jelas-jelas mengenainya!",
  ui_story_5014_50140902_10_dialog_content = "Maaf. Kak Ruby memang agak kikuk...",
  ui_story_5014_50140902_11_dialog_content = "Dulu aku pernah mengikuti pelatihan medis. Biar kuperiksa dia...",
  ui_story_5014_50140902_12_dialog_content = "Bagaimana keadaan PlayerName?",
  ui_story_5014_50140902_13_dialog_content = "Sepertinya dia baik-baik saja. Sebentar lagi dia pasti siuman...",
  ui_story_5014_50140902_14_dialog_content = "Aduh... Kepalaku sakit...",
  ui_story_5014_50140902_15_dialog_content = "Kamu sudah sadar?",
  ui_story_5014_50140902_16_dialog_content = "Eh... Kapan kalian tiba?",
  ui_story_5014_50140902_17_dialog_content = "Semua... baik-baik saja?",
  ui_story_5014_50140902_18_dialog_content = "Aku dan Siobhan baik-baik saja. Jangan khawatir.",
  ui_story_5014_50140902_19_dialog_content = "Meski baru saja kembali, kami sudah tahu apa yang terjadi.",
  ui_story_5014_50140902_20_dialog_content = "Setelah kuperiksa sebentar, sepertinya kamu baik-baik saja.",
  ui_story_5014_50140902_21_dialog_content = "Hai~ Apa kamu baik-baik saja?",
  ui_story_5014_50140902_22_dialog_content = "Maaf soal yang tadi, ya. Aku tak bermaksud menakutimu, kok.",
  ui_story_5014_50140902_23_dialog_content = "Aku tidak apa-apa, kok... Hanya saja ledakan tadi... membuatku terkejut...",
  ui_story_5014_50140902_24_dialog_content = "Benar. Itu salahku.",
  ui_story_5014_50140902_25_dialog_content = "Baiklah, aku akan memperkenalkan diri dulu.",
  ui_story_5014_50140902_26_dialog_content = "Ini adalah Siobhan, penjelajah terkenal dari Illumina...",
  ui_story_5014_50140902_27_dialog_content = "Dan petualang terhebat dari Lumopolis, Florine.",
  ui_story_5014_50140902_28_dialog_content = "Kamu kenal mereka?",
  ui_story_5014_50140902_29_dialog_content = "Kami sama terkenalnya di dunia petualangan.",
  ui_story_5014_50140902_30_dialog_content = "Omong-omong, siapa kamu?",
  ui_story_5014_50140902_31_dialog_content = "Aku lupa kalau ada crossdresser di kalangan petualang...",
  ui_story_5014_50140902_32_dialog_content = "Cukup. Tak usah diteruskan. Aku tak punya pilihan!",
  ui_story_5014_50140902_33_dialog_content = "(Aku hampir lupa soal ini... Kenapa mereka terus menggangguku...)",
  ui_story_5014_50140902_34_dialog_content = "Aku PlayerName, seorang Caelestite. Para petualang seperti kalian pasti telah mendengar...",
  ui_story_5014_50140902_35_dialog_content = "Kamu seorang Caelestite... Honcho Sinsa sering berkata...",
  ui_story_5014_50140902_36_dialog_content = "Sudah, Kak Ruby. Kita tak punya waktu untuk ini!",
  ui_story_5014_50140902_37_dialog_content = "Siobhan, tolong lanjutkan.",
  ui_story_5014_50140902_38_dialog_content = "Siapa kalian dan apa yang kalian lakukan di sini?",
  ui_story_5014_50140902_39_dialog_content = "Aku Ruby, ini Rouge.",
  ui_story_5014_50140902_40_dialog_content = "Kami petualang hebat dari Rediesel Wrench. Sungguh suatu kehormatan bertemu dengan Anda, Putri Carleen.",
  ui_story_5014_50140902_41_dialog_content = "Kalian kemari untuk mencari harta karun atau kriminal?",
  ui_story_5014_50140902_42_dialog_content = "Tidak.",
  ui_story_5014_50140902_43_dialog_content = "Bagaimana kalian bisa masuk? Apa kalian tahu di mana pintu keluarnya?",
  ui_story_5014_50140902_44_dialog_content = "Kami jatuh dari atas. Sejujurnya, kami tidak benar-benar tahu di mana kami berada sekarang~",
  ui_story_5014_50140902_45_dialog_content = "Biar aku saja!",
  ui_story_5014_50140902_46_dialog_content = "Kami menerima sinyal misterius dan mengikutinya hingga ke liang besar.",
  ui_story_5014_50140902_47_dialog_content = "Ada terowongan yang menuju ke bawah...",
  ui_story_5014_50140902_48_dialog_content = "Kami jatuh ke dalam setelah terjadi gempa bumi.",
  ui_story_5014_50140902_49_dialog_content = "Sudah kubilang jangan dekat-dekat terowongan itu. Kamu tidak pernah mau dengar, sih.",
  ui_story_5014_50140902_50_dialog_content = "Maafkan aku~",
  ui_story_5014_50140902_51_dialog_content = "Lalu? Di mana terowongannya?",
  ui_story_5014_50140902_52_dialog_content = "Kami tergelincir ke gua bawah tanah lain.",
  ui_story_5014_50140902_53_dialog_content = "Kami tak bisa menelusuri kembali jalan masuknya dan harus menyusuri gua...",
  ui_story_5014_50140902_54_dialog_content = "Kami tiba di sini setelah melalui sebuah terowongan.",
  ui_story_5014_50140902_55_dialog_content = "Kami tidak tahu ada kota kecil yang begitu besar yang penuh dengan harta karun.",
  ui_story_5014_50140902_56_dialog_content = "Kami pasti beruntung~",
  ui_story_5014_50140902_57_dialog_content = "Kak Ruby, sadarlah. Sekarang kita terjebak di sini!",
  ui_story_5014_50140902_58_dialog_content = "Kenapa? Kok kamu tahu kita terjebak?",
  ui_story_5014_50140902_59_dialog_content = "Mereka baru saja bertanya apa kita tahu jalan keluarnya. Sepertinya kita semua terjebak di sini!",
  ui_story_5014_50140902_60_dialog_content = "Oh. Sayang sekali.",
  ui_story_5014_50140902_61_dialog_content = "Hei. Kenapa kalian semua kaget begitu?",
  ui_story_5014_50140902_62_dialog_content = "Aku... aku tidak sadar bahwa ini adalah kota bawah tanah...",
  ui_story_5014_50140902_63_dialog_content = "Langitnya tidak nyata?",
  ui_story_5014_50140902_64_dialog_content = "Tidak, tapi itu memang terlihat seperti aslinya, sih.",
  ui_story_5014_50140902_65_dialog_content = "Aku ingin memukulnya dan mencari tahu terbuat dari apa benda itu.",
  ui_story_5014_50140902_66_dialog_content = "Hari sudah larut saat kami terjatuh. Kalau tidak, kami juga tak akan tahu.",
  ui_story_5014_50140902_67_dialog_content = "Karena waktu dan ruang di sini tampak aneh, kami tidak menyadari bahwa kami sebenarnya ada di bawah tanah...",
  ui_story_5014_50140902_68_dialog_content = "Para android itu juga terus mencegah kami menjelajahi kota.",
  ui_story_5014_50140902_69_dialog_content = "Bagaimana kalian bisa kemari?",
  ui_story_5014_50140902_70_dialog_content = "Yah, kurang lebih sama.",
  ui_story_5014_50140902_71_dialog_content = "Gempa bumi yang sering terjadi telah merusak beberapa fasilitas di bawah kota ini.",
  ui_story_5014_50140902_72_dialog_content = "Termasuk tempat kami masuk.",
  ui_story_5014_50140902_73_dialog_content = "Aku menduga Butler sengaja membukanya agar kami masuk.",
  ui_story_5014_50140902_74_dialog_content = "Jadi, dia bisa mengurung kami.",
  ui_story_5014_50140902_75_dialog_content = "Kurasa tidak...",
  ui_story_5014_50140902_76_dialog_content = "Butler diprogram untuk melindungi kakak beradik itu. Sepertinya dia tidak ingin mereka berdua berhubungan dengan orang luar.",
  ui_story_5014_50140902_77_dialog_content = "Butler apa? Kakak beradik apa? Kalian bicara apa, sih?",
  ui_story_5014_50140902_78_dialog_content = "Manusia purba membangun undercity ini untuk melarikan diri dari perang dan bencana.",
  ui_story_5014_50140902_79_dialog_content = "Tapi, tempat ini sangat berbeda dengan Illumina.",
  ui_story_5014_50140902_80_dialog_content = "Benar. Kota bawah Illumina semuanya dibangun dengan berbagai fasilitas militer.",
  ui_story_5014_50140902_81_dialog_content = "Tapi, hanya ada kehidupan dan fasilitas produksi serba otomatis serta android penegak hukum di kota ini.",
  ui_story_5014_50140902_82_dialog_content = "Ini adalah kota permukiman sederhana.",
  ui_story_5014_50140902_83_dialog_content = "Butler adalah sistem kecerdasan buatan yang bertanggung jawab atas kota kecil ini.",
  ui_story_5014_50140902_84_dialog_content = "Dia yang memastikan operasional kota dan keselamatan kaum Ancient.",
  ui_story_5014_50140902_85_dialog_content = "Rupanya sudah banyak yang kamu pelajari.",
  ui_story_5014_50140902_86_dialog_content = "Seamus... Seorang penjelajah Illumina pernah datang kemari.",
  ui_story_5014_50140902_87_dialog_content = "Dia tinggal di sini dengan istrinya dan meninggalkan banyak informasi penting.",
  ui_story_5014_50140902_88_dialog_content = "Bagaimana dengan jalan keluarnya?",
  ui_story_5014_50140902_89_dialog_content = "Butler mengetahui jalan keluarnya, tapi dia merasa tempat ini akan makin mudah ditemukan kalau kami pergi.",
  ui_story_5014_50140902_90_dialog_content = "Jadi, dia tidak mau membiarkan kami pergi.",
  ui_story_5014_50140902_91_dialog_content = "Kakak beradik yang kusebutkan tadi adalah anak Tuan dan Nyonya Seamus. Mereka lahir dan tumbuh besar di sini.",
  ui_story_5014_50140902_92_dialog_content = "Ada lebih banyak data yang tersimpan di rumahnya. Kami harus...",
  ui_story_5014_50140902_93_dialog_content = "Kalian harus mencari informasi tentang jalan keluarnya... Kami akan mencari harta karun!",
  ui_story_5014_50140902_94_dialog_content = "Kak Ruby?",
  ui_story_5014_50140902_95_dialog_content = "Toh kita juga tidak akan bisa keluar dalam waktu dekat. Biar mereka saja yang cari jalan keluarnya.",
  ui_story_5014_50140902_96_dialog_content = "Tolong beri tahu kami kalau jalan keluarnya sudah ketemu, ya.",
  ui_story_5014_50140902_97_dialog_content = "Sebentar. Tempat ini penuh Eclipsite dan android. Akan terlalu berbahaya kalau kalian pergi sendirian.",
  ui_story_5014_50140902_98_dialog_content = "Jangan cemas. Kami akan mengirim pesan kalau terjadi apa-apa.",
  ui_story_5014_50140902_99_dialog_content = "Siobhan, bagaimana kalau kita bertukar alamat Communicator?",
  ui_story_5014_50140902_100_dialog_content = "Kalian membuat Communicator sendiri? Coba lihat...",
  ui_story_5014_50140902_101_dialog_content = "Ya, benar.",
  ui_story_5014_50140902_102_dialog_content = "Berapa banyak Communicator kalian?",
  ui_story_5014_50140902_103_dialog_content = "Tentu saja ada dua. Kenapa kamu tanya?",
  ui_story_5014_50140902_104_dialog_content = "Bisa digunakan untuk berkomunikasi dengan satu sama lain di kota ini?",
  ui_story_5014_50140902_105_dialog_content = "Benar, tapi tidak bisa menjangkau dunia luar...",
  ui_story_5014_50140902_106_dialog_content = "Itu saja sudah cukup. Berikan satu Communicator-mu agar kita bisa terus berkomunikasi.",
  ui_story_5014_50140902_107_dialog_content = "Tentu saja. Memang itu rencana kami, kok!",
  ui_story_5014_50140902_108_dialog_content = "Guru Siobhan, kenapa kamu tidak ikut membujuk mereka?",
  ui_story_5014_50140902_109_dialog_content = "Mereka tahu lebih banyak soal perburuan harta karun di reruntuhan.",
  ui_story_5014_50140902_110_dialog_content = "Rediesel Wrench memang tidak tahu sopan santun, tapi pendekatan mereka sering kali langsung dan efektif.",
  ui_story_5014_50140902_111_dialog_content = "Maksudmu?",
  ui_story_5014_50140902_112_dialog_content = "Rediesel Wrench sering mencuri barang dari reruntuhan dan menjualnya. Mereka ahlinya di bidang ini. Jangan khawatir.",
  ui_story_5014_50140902_113_dialog_content = "Yah, kalau begitu aku tak perlu khawatir lagi... Semua orang di sini adalah penjelajah ulung.",
  ui_story_5014_50141001_1_dialog_content = "Koordinatnya merujuk pada lokasi ini, di dalam area tempat tinggal.",
  ui_story_5014_50141001_2_dialog_content = "Seamus meninggalkan data penelitiannya di kamarnya. Mungkin ada informasi mengenai jalan keluar itu.",
  ui_story_5014_50141001_3_dialog_content = "Kita...",
  ui_story_5014_50141001_4_dialog_content = "Hu... Hu...",
  ui_story_5014_50141001_5_dialog_content = "Gerombolan Eclipsite itu berkumpul. Kita harus hati-hati.",
  ui_story_5014_50141001_6_dialog_content = "Mereka berkumpul di mana?",
  ui_story_5014_50141001_7_dialog_content = "Di sana, bekas pabrik android.",
  ui_story_5014_50141001_8_dialog_content = "Sial... Valencia dan saudarinya mungkin masih di sana!",
  ui_story_5014_50141001_9_dialog_content = "Jangan bilang kau mau...",
  ui_story_5014_50141001_10_dialog_content = "Kita harus kembali dan menyelamatkan mereka.",
  ui_story_5014_50141001_11_dialog_content = "Tidak... Kau baru saja berhasil lolos dari cengkeraman mesin keji itu.",
  ui_story_5014_50141001_12_dialog_content = "Jangan kembali dalam pusaran itu.",
  ui_story_5014_50141001_13_dialog_content = "Ayo. Ayo kembali bersama Siobhan.",
  ui_story_5014_50141001_14_dialog_content = "Presiden?",
  ui_story_5014_50141001_15_dialog_content = "Siobhan, apa menurutmu gerombolan Eclipsite itu mengejar Valencia dan saudarinya?",
  ui_story_5014_50141001_16_dialog_content = "Ya, siaran data Seamus menyebutkan begitu.",
  ui_story_5014_50141001_17_dialog_content = "Gerombolan Eclipsite itu belum melukai mereka, dan si Butler menjaga mereka.",
  ui_story_5014_50141001_18_dialog_content = "Tapi, kita baru saja menghancurkan banyak android. Itu berarti...",
  ui_story_5014_50141001_19_dialog_content = "Kekuatan mereka mungkin tak akan cukup untuk membendung serangan Eclipsite itu.",
  ui_story_5014_50141001_20_dialog_content = "<color=#e8d9bb>Tolong... Mundur... Tolong.</color>",
  ui_story_5014_50141001_21_dialog_content = "Kwek!",
  ui_story_5014_50141001_22_dialog_content = "<color=#e8d9bb>Cepat... Mundur ke tempat yang aman.</color>",
  ui_story_5014_50141001_23_dialog_content = "Gretel, ayo!",
  ui_story_5014_50141001_24_dialog_content = "Tapi, Butler... Android-android baru itu...",
  ui_story_5014_50141001_25_dialog_content = "<color=#e8d9bb>Jangan khawatir... Kami akan melindunginya...</color>",
  ui_story_5014_50141001_26_dialog_content = "Lewat sini. Cepat!",
  ui_story_5014_50141001_27_dialog_content = "Aku bisa merasakannya!",
  ui_story_5014_50141001_28_dialog_content = "Para android itu sedang bertarung melawan Eclipsite. Valencia dan saudarinya tadi lewat sini.",
  ui_story_5014_50141001_29_dialog_content = "Banyak Eclipsite mengejar mereka.",
  ui_story_5014_50141001_30_dialog_content = "Florine dan PlayerName, tahan gerombolan Eclipsite itu sebisa kalian.",
  ui_story_5014_50141001_31_dialog_content = "Aku akan mencari kakak beradik itu.",
  ui_story_5014_50141002_1_dialog_content = "Bukannya kau sudah berhasil lolos? Kenapa kau malah kembali kemari?",
  ui_story_5014_50141002_2_dialog_content = "Siobhan.",
  ui_story_5014_50141002_3_dialog_content = "PlayerName memberitahuku lewat telepati bahwa kalian dikejar Eclipsite.",
  ui_story_5014_50141002_4_dialog_content = "Jadi, kami kembali untuk membantu.",
  ui_story_5014_50141002_5_dialog_content = "Aku tak bisa meninggalkan kalian begitu saja...",
  ui_story_5014_50141002_6_dialog_content = "Kami tak butuh bantuanmu!",
  ui_story_5014_50141002_7_dialog_content = "Butler kami bisa mengatasi gerombolan Eclipsite itu tanpa butuh waktu lama!",
  ui_story_5014_50141002_8_dialog_content = "<color=#e8d9bb>Jangan khawatir... Kami bisa memperbaikinya... Sebentar lagi.</color>",
  ui_story_5014_50141002_9_dialog_content = "Dia kepayahan menghadapi gempa bumi dan Eclipsite yang banyak itu.",
  ui_story_5014_50141002_10_dialog_content = "Gempa buminya memengaruhi transmisi sinyal. Sekarang ini, dia sudah kesulitan mengendalikan android dan mesin-mesin ini.",
  ui_story_5014_50141002_11_dialog_content = "Benar, 'kan, Butler?",
  ui_story_5014_50141002_12_dialog_content = "<color=#e8d9bb>Kami sedang... Memperbaikinya... Jangan khawatir.</color>",
  ui_story_5014_50141002_13_dialog_content = "Katakan di mana jalan keluarnya.",
  ui_story_5014_50141002_14_dialog_content = "Akan kukirimkan ilmuwan terbaik Illumina untuk membantumu, sama seperti dulu Seamus membantu kota ini.",
  ui_story_5014_50141002_15_dialog_content = "Prioritas utamamu adalah keselamatan kota ini, 'kan?",
  ui_story_5014_50141002_16_dialog_content = "Illumina tidak akan menghancurkan tempat ini.",
  ui_story_5014_50141002_17_dialog_content = "Kami akan membantumu memperbaiki semua fasilitas yang rusak itu.",
  ui_story_5014_50141002_18_dialog_content = "<color=#e8d9bb>Kami bisa... Memperbaiki diri sendiri.</color>",
  ui_story_5014_50141002_19_dialog_content = "<color=#e8d9bb>Tanggung jawabku adalah... Menjaga kota ini... Tetap utuh dan aman.</color>",
  ui_story_5014_50141002_20_dialog_content = "<color=#e8d9bb>Tidak boleh... Membiarkan kalian pergi.</color>",
  ui_story_5014_50141002_21_dialog_content = "<color=#e8d9bb>Aku akan... Meng-upgrade... Aku bisa mengatasi masalah... Dan Eclipsite.</color>",
  ui_story_5014_50141002_22_dialog_content = "Eclipsite... Ya, Seamus memang menyebut tentang Eclipsite.",
  ui_story_5014_50141002_23_dialog_content = "Dari mana datangnya para Eclipsite ini?",
  ui_story_5014_50141002_24_dialog_content = "<color=#e8d9bb>Izin... Ditolak.</color>",
  ui_story_5014_50141002_25_dialog_content = "Siobhan, gerombolan Eclipsite itu makin kuat... Kita tak bisa bertahan lebih lama lagi.",
  ui_story_5014_50141002_26_dialog_content = "Aku bisa merasakan para Eclipsite itu bertambah kuat.",
  ui_story_5014_50141002_27_dialog_content = "Butler, jawab aku. Dari mana datangnya para Eclipsite itu?",
  ui_story_5014_50141002_28_dialog_content = "Apa kau yang menyuruh mereka?",
  ui_story_5014_50141002_29_dialog_content = "<color=#e8d9bb>Tidak... Aku tidak menyuruh mereka.</color>",
  ui_story_5014_50141002_30_dialog_content = "Kalau begitu, siapa yang menyuruh mereka?",
  ui_story_5014_50141002_31_dialog_content = "<color=#e8d9bb>Izin... Ditolak.</color>",
  ui_story_5014_50141002_32_dialog_content = "Kwek!",
  ui_story_5014_50141002_33_dialog_content = "Sial. Cukup sudah. Kita lari saja!",
  ui_story_5014_50141002_34_dialog_content = "Valencia, Gretel, ikutlah dengan kami!",
  ui_story_5014_50141002_35_dialog_content = "Tidak!",
  ui_story_5014_50141002_36_dialog_content = "<color=#e8d9bb>Tolong... Mundurlah.</color>",
  ui_story_5014_50141002_37_dialog_content = "<color=#e8d9bb>Daya tempur... Tidak cukup... Tolong, larilah.</color>",
  ui_story_5014_50141002_38_dialog_content = "Butler, tadi kaubilang kau bisa memperbaikinya! Kaubilang...",
  ui_story_5014_50141002_39_dialog_content = "<color=#e8d9bb>Eclipsite... Terlalu banyak... Tolong, selamatkan diri kalian.</color>",
  ui_story_5014_50141002_40_dialog_content = "Groar! Groar!",
  ui_story_5014_50141002_41_dialog_content = "Gretel, bersembunyilah di tempat yang aman. Aku akan membantu Butler menangani para penyerang itu...",
  ui_story_5014_50141002_42_dialog_content = "Tidak... Aku sudah tak mau sembunyi lagi...",
  ui_story_5014_50141002_43_dialog_content = "Eclipsite-nya terlalu banyak... Si Butler akan mati... Begitu pula kakakku...",
  ui_story_5014_50141002_44_dialog_content = "Sama seperti ayah dan ibu...",
  ui_story_5014_50141002_45_dialog_content = "Aku tak ingin kau mati... Jangan mati...",
  ui_story_5014_50141002_46_dialog_content = "Gretel? Tenanglah...",
  ui_story_5014_50141002_47_dialog_content = "Tidak!",
  ui_story_5014_50141002_48_dialog_content = "<color=#e8d9bb>Duar!</color>",
  ui_story_5014_50141002_49_dialog_content = "<color=#e8d9bb>Wush...</color>",
  ui_story_5014_50141002_50_dialog_content = "Hmm... Apa yang terjadi?",
  ui_story_5014_50141002_51_dialog_content = "Tiba-tiba saja ada aliran Lumina yang kuat di dalam tubuhnya.",
  ui_story_5014_50141002_52_dialog_content = "Semua Eclipsite itu terhantam.",
  ui_story_5014_50141002_53_dialog_content = "Gretel, bangunlah! Jangan membuatku takut! Gretel!",
  ui_story_5014_50141002_54_dialog_content = "Fyuh... Kakak... Aku baik-baik saja...",
  ui_story_5014_50141002_55_dialog_content = "Syukurlah... Kau baik-baik saja...",
  ui_story_5014_50141002_56_dialog_content = "Aku akan membawamu kembali untuk dirawat. Bertahanlah...",
  ui_story_5014_50141002_57_dialog_content = "Butler, sini, bantu aku!",
  ui_story_5014_50141002_58_dialog_content = "<color=#e8d9bb>Sistem perawatan mendesak... Diaktifkan. Ikuti aku.</color>",
  ui_story_5014_50141002_59_dialog_content = "Valencia, kami akan ikut denganmu...",
  ui_story_5014_50141002_60_dialog_content = "Berhenti di sana!",
  ui_story_5014_50141002_61_dialog_content = "Kalian tak boleh ke mana-mana.",
  ui_story_5014_50141002_62_dialog_content = "Valencia, kami hanya ingin membantu...",
  ui_story_5014_50141002_63_dialog_content = "Tak usah!",
  ui_story_5014_50141002_64_dialog_content = "Adikku pasti juga tak menginginkan kalian di sini.",
  ui_story_5014_50141101_1_dialog_content = "... Apa Gretel yang melakukannya?",
  ui_story_5014_50141101_2_dialog_content = "Ya, kurasa dia terlalu terbawa perasaan, dan Lumina-nya meledak.",
  ui_story_5014_50141101_3_dialog_content = "Tak kusangka, gadis kecil sepertinya punya kekuatan sebesar itu.",
  ui_story_5014_50141101_4_dialog_content = "Presiden, perasaanku tidak enak...",
  ui_story_5014_50141101_5_dialog_content = "Aku paham kau pasti merasa sangat gelisah.",
  ui_story_5014_50141101_6_dialog_content = "Situasi jadi melenceng jauh dari harapan kita. Jujur saja, situasinya sekarang sudah tak bisa kita kendalikan lagi.",
  ui_story_5014_50141101_7_dialog_content = "Kita harus mencari jalan keluarnya dan menghubungi Elder Hedy.",
  ui_story_5014_50141101_8_dialog_content = "Kuharap laporanmu tidak membahayakan kakak beradik itu...",
  ui_story_5014_50141101_9_dialog_content = "Tidak akan. Lagi pula, mereka keturunan Lumopolis.",
  ui_story_5014_50141101_10_dialog_content = "Apa yang harus kita lakukan sekarang? Tadi, Valencia menyuruh kita tetap di sini.",
  ui_story_5014_50141101_11_dialog_content = "Kita akan mencari kamar Seamus.",
  ui_story_5014_50141101_12_dialog_content = "Setelah bercakap-cakap sebentar dengan Butler, kurasa kita harus mencari data riset Seamus sesegera mungkin.",
  ui_story_5014_50141101_13_dialog_content = "Aku ingat koordinatnya. Ikuti aku.",
  ui_story_5014_50141101_14_dialog_content = "<color=#e8d9bb>Bip... Bip... </color>",
  ui_story_5014_50141101_15_dialog_content = "Suara apa itu?",
  ui_story_5014_50141101_16_dialog_content = "Pesan dari Ruby...",
  ui_story_5014_50141101_17_dialog_content = "Hei! Kalian bisa dengar kami?",
  ui_story_5014_50141101_18_dialog_content = "Kami butuh bantuan!",
  ui_story_5014_50141101_19_dialog_content = "Kalau tidak, tak lama lagi Rouge akan mati karena marah!",
  ui_story_5014_50141101_20_dialog_content = "Aduh... Telingaku jadi sakit!",
  ui_story_5014_50141101_21_dialog_content = "Mereka dalam bahaya... Apa kita perlu membantu mereka?",
  ui_story_5014_50141101_22_dialog_content = "Mereka memang anggota Rediesel Wrench, tapi kau tak perlu sinis begitu kepada mereka.",
  ui_story_5014_50141101_23_dialog_content = "Kalau begitu, cepatlah. Jangan buang-buang waktu.",
  ui_story_5014_50141101_24_dialog_content = "Mereka tak jauh dari tempat yang kita tuju.",
  ui_story_5014_50141101_25_dialog_content = "Mungkin di sana ada android atau Eclipsite.",
  ui_story_5014_50141101_26_dialog_content = "Untuk dokumen yang ditinggalkan Seamus?",
  ui_story_5014_50141101_27_dialog_content = "Ya. Tapi, Butler mungkin sudah tahu bahwa kita ingin mengambil dokumen itu. Kita harus bergegas.",
  ui_story_5014_50141101_28_dialog_content = "Baiklah. Kami akan pimpin jalannya.",
  ui_story_5014_50141101_29_dialog_content = "Erica, tambah kecepatan dan kekuatan. Kita harus sampai di sana secepatnya dan mengamankan lokasi!",
  ui_story_5014_50141101_30_dialog_content = "Siap, Presiden.",
  ui_story_5014_50141101_31_dialog_content = "<color=#e8d9bb>Dor! Plok!</color>",
  ui_story_5014_50141101_32_dialog_content = "Kak Ruby, mereka datang!",
  ui_story_5014_50141101_33_dialog_content = "Ruby, Rouge! Kalian baik-baik saja?",
  ui_story_5014_50141101_34_dialog_content = "Cuit... Kriek... Cuit... Kriek...",
  ui_story_5014_50141101_35_dialog_content = "Syukurlah! Kukira kalian tak akan kemari.",
  ui_story_5014_50141101_36_dialog_content = "Apa yang terjadi? Apa kalian diserang android? Apa mereka bilang sesuatu?",
  ui_story_5014_50141101_37_dialog_content = "Mana kutahu? Kami tidak berbuat apa pun.",
  ui_story_5014_50141101_38_dialog_content = "Peringatan! Kembalikan barang! Peringatan! Kembalikan barang!",
  ui_story_5014_50141101_39_dialog_content = "Kak Ruby... Sudah kubilang, 'kan? Kita tak bisa mengambil apa pun langsung di depan mereka!",
  ui_story_5014_50141101_40_dialog_content = "... Apa yang kauambil?",
  ui_story_5014_50141101_41_dialog_content = "Sial! Ini relik! Mana ada orang yang punya relik?",
  ui_story_5014_50141101_42_dialog_content = "Kepingan-kepingan logam ini tak ada hubungannya dengan ini. Apa masalahnya?",
  ui_story_5014_50141101_43_dialog_content = "Program penangkapan. Diaktifkan!",
  ui_story_5014_50141101_44_dialog_content = "Graagh!",
  ui_story_5014_50141101_45_dialog_content = "Makin banyak Eclipsite mendesak kita!",
  ui_story_5014_50141101_46_dialog_content = "Kita dikepung musuh dari kedua sisi. Hati-hati...",
  ui_story_5014_50141102_1_dialog_content = "Satu, dan dua!",
  ui_story_5014_50141102_2_dialog_content = "Cuit... Gah...",
  ui_story_5014_50141102_3_dialog_content = "Tiga, dan empat...",
  ui_story_5014_50141102_4_dialog_content = "Ruby, ini bukan saatnya menikmati pertarungan. Musuh yang berdatangan makin banyak.",
  ui_story_5014_50141102_5_dialog_content = "Kita harus mengambil dokumen yang ditinggalkan Seamus.",
  ui_story_5014_50141102_6_dialog_content = "Orang yang tadi kausebut-sebut itu, ya? Di mana dokumennya?",
  ui_story_5014_50141102_7_dialog_content = "Di dalam area tempat tinggal... Ikuti aku. Florine dan rombongannya sudah pergi untuk membuka jalan.",
  ui_story_5014_50141102_8_dialog_content = "Oh? Kalau begitu, kita tertinggal di belakang mereka.",
  ui_story_5014_50141102_9_dialog_content = "Siobhan, kamarnya ada di dalam bangunan di depan sana. Kami menemukannya!",
  ui_story_5014_50141102_10_dialog_content = "Bagus. Untuk sementara ini, kami berhasil membendung gerombolan android itu. Cepatlah.",
  ui_story_5014_50141102_11_dialog_content = "Fyuh... Akhirnya... Berhasil.",
  ui_story_5014_50141102_12_dialog_content = "Apa bangunan ini kokoh?",
  ui_story_5014_50141102_13_dialog_content = "Apa bangunan ini akan roboh kalau kita terpaksa bertarung melawan musuh?",
  ui_story_5014_50141102_14_dialog_content = "Mungkin saja. Bangunan tempat tinggal ini sudah cukup uzur.",
  ui_story_5014_50141102_15_dialog_content = "Kalau kita terpaksa bertarung, tahan sedikit.",
  ui_story_5014_50141102_16_dialog_content = "Gaya bertarungmu cukup liar.",
  ui_story_5014_50141102_17_dialog_content = "Siap. Mulai sekarang, kita satu tim petualangan.",
  ui_story_5014_50141102_18_dialog_content = "Kita berhasil... Ini kamar Seamus.",
  ui_story_5014_50141102_19_dialog_content = "Kamar ini...",
  ui_story_5014_50141102_20_dialog_content = "Sudah cukup lama tidak ditempati.",
  ui_story_5014_50141102_21_dialog_content = "Memangnya kenapa? Semua kamar di sini kosong.",
  ui_story_5014_50141102_22_dialog_content = "Lihat... Semua pakaian dan buku ini tidak berdebu sama sekali.",
  ui_story_5014_50141102_23_dialog_content = "Mereka... Menjaganya agar tetap bersih.",
  ui_story_5014_50141102_24_dialog_content = "Wow... Ini gaun wanita. Aku ingin tahu apa pakaian ini mudah laku dijual.",
  ui_story_5014_50141102_25_dialog_content = "Kak Ruby, jangan. Kakak beradik itu akan membunuh kita!",
  ui_story_5014_50141102_26_dialog_content = "Aku hanya bercanda, kok... Ini pasti relik Tuan dan Nyonya Seamus, ya?",
  ui_story_5014_50141102_27_dialog_content = "Aku tak akan mengambil apa pun di depanmu.",
  ui_story_5014_50141102_28_dialog_content = "Kamu...",
  ui_story_5014_50141102_29_dialog_content = "Aku hanya bercanda. Jangan serius melulu, dong.",
  ui_story_5014_50141102_30_dialog_content = "Kami petualang profesional. Kami harus mematuhi etika profesi dengan ketat.",
  ui_story_5014_50141102_31_dialog_content = "Tapi, kita harus mengambil data riset Seamus.",
  ui_story_5014_50141102_32_dialog_content = "Terlalu banyak, sulit memilihnya... Vice, sini, bantu kami memilah dokumen yang penting.",
  ui_story_5014_50141102_33_dialog_content = "Siap!",
  ui_story_5014_50141102_34_dialog_content = "Guru Siobhan, jadi senior Seamus meninggalkan semua catatan ini?",
  ui_story_5014_50141102_35_dialog_content = "Ya, ini tulisan tangan Seamus.",
  ui_story_5014_50141102_36_dialog_content = "Persis seperti yang kuingat...",
  ui_story_5014_50141102_37_dialog_content = "Guru Siobhan, kenapa tanganmu gemetar?",
  ui_story_5014_50141102_38_dialog_content = "Hmm... Aku tak mengira bisa melihat makalah riset berharga ini lagi...",
  ui_story_5014_50141102_39_dialog_content = "Aku hanya terlalu gembira... Jangan khawatir. Fokus saja pada dokumennya.",
  ui_story_5014_50141102_40_dialog_content = "Guru Siobhan, ada terlalu banyak kode rahasia... yang tak bisa kuuraikan.",
  ui_story_5014_50141102_41_dialog_content = "Jangan khawatir. Uraikan saja sebisamu dengan kunci umum itu. Biar kutangani multicrypt-nya nanti.",
  ui_story_5014_50141102_42_dialog_content = "Baik!",
  ui_story_5014_50141102_43_dialog_content = "Carleen, mereka akan butuh waktu agak lama untuk mengambil data.",
  ui_story_5014_50141102_44_dialog_content = "Kalau Eclipsite dan android itu kemari...",
  ui_story_5014_50141102_45_dialog_content = "Aku paham. Kami akan berjaga di pintu. Tak akan kubiarkan seorang pun masuk.",
  ui_story_5014_50141102_46_dialog_content = "Presiden, lihat.",
  ui_story_5014_50141102_47_dialog_content = "Ada apa, Erica?",
  ui_story_5014_50141102_48_dialog_content = "Masih ada buku harian lagi.",
  ui_story_5014_50141102_49_dialog_content = "Dan stempel emas...",
  ui_story_5014_50141102_50_dialog_content = "Apa ini jejak God of Light di negeri yang gelap dan sesat ini?",
  ui_story_5014_50141102_51_dialog_content = "Tanda ini seperti tanda dari Lumopolis... Kurasa ini milik Cloud.",
  ui_story_5014_50141102_52_dialog_content = "Apa perlu kita buka, Presiden?",
  ui_story_5014_50141102_53_dialog_content = "Ya... Aku ingin tahu bagaimana seorang bangsawan Lumopolis bisa ada di sini.",
  ui_story_5014_50141102_54_dialog_content = "Apa kau membaca buku harian Cloud?",
  ui_story_5014_50141102_55_dialog_content = "Hei! Jangan mendekat tiba-tiba, dong...",
  ui_story_5014_50141102_56_dialog_content = "Maaf. Aku hanya penasaran.",
  ui_story_5014_50141102_57_dialog_content = "Jangan khawatir. Kurasa sang Presiden tidak terlalu paham.",
  ui_story_5014_50141102_58_dialog_content = "Uhh? Coretan-coretan ini apa?",
  ui_story_5014_50141102_59_dialog_content = "Ini huruf rahasia yang digunakan oleh kalangan bangsawan. Aku hanya paham sedikit.",
  ui_story_5014_50141102_60_dialog_content = "Apa itu \"steganografi\"?",
  ui_story_5014_50141102_61_dialog_content = "Kata-kata yang ditulis dengan cara khusus untuk membuat sandi. Hanya kalangan mereka saja yang bisa memahaminya.",
  ui_story_5014_50141102_62_dialog_content = "Rupanya pasangan ini sangat suka sandi.",
  ui_story_5014_50141102_63_dialog_content = "Mungkin Cloud ingin mengirimkan sesuatu kembali ke Lumopolis...",
  ui_story_5014_50141102_64_dialog_content = "Dan Seamus punya sesuatu yang ingin diberitahukannya kepada Illumina?",
  ui_story_5014_50141102_65_dialog_content = "Ini seperti hubungan antara Lumopolis dan Illumina. Saling menyembunyikan rahasia.",
  ui_story_5014_50141102_66_dialog_content = "Bukannya mereka itu sejoli?",
  ui_story_5014_50141102_67_dialog_content = "Aneh sekali sih kehidupan pernikahan mereka?",
  ui_story_5014_50141102_68_dialog_content = "Diam, pasangan Rediesel ini... Dalam catatannya, Seamus menyatakan cintanya untuk istrinya.",
  ui_story_5014_50141102_69_dialog_content = "Mereka saling menghormati dan saling memberikan kebebasan.",
  ui_story_5014_50141102_70_dialog_content = "Mereka tahu tentang file-file bersandi ini... Cloud juga menyebutkannya dalam buku hariannya.",
  ui_story_5014_50141102_71_dialog_content = "<color=#e8d9bb>Kriek... Gah.</color>",
  ui_story_5014_50141102_72_dialog_content = "Ada sesuatu yang masuk?",
  ui_story_5014_50141102_73_dialog_content = "Android atau Eclipsite?",
  ui_story_5014_50141102_74_dialog_content = "Android... Tapi...",
  ui_story_5014_50141102_75_dialog_content = "Dia tidak menyerang?",
  ui_story_5014_50141102_76_dialog_content = "Bibu.",
  ui_story_5014_50141102_77_dialog_content = "Anjing robot... Dia pasti peliharaan senior Seamus?",
  ui_story_5014_50141102_78_dialog_content = "Dia tidak tampak galak.",
  ui_story_5014_50141102_79_dialog_content = "Kalau dia tidak mengancam, biarkan saja... Kita fokus saja untuk mengumpulkan info.",
  ui_story_5014_50141102_80_dialog_content = "Baiklah, setuju.",
  ui_story_5014_50141102_81_dialog_content = "Profesor Siobhan, tolong lihat catatanku ini...",
  ui_story_5014_50141102_82_dialog_content = "Bip, bip, bip, bip...",
  ui_story_5014_50141102_83_dialog_content = "Sepertinya anjing kecil ini ingin pergi.",
  ui_story_5014_50141102_84_dialog_content = "Rouge, kita kan sedang tidak banyak kerjaan... Bolehkah aku bermain dengannya?",
  ui_story_5014_50141102_85_dialog_content = "Huh... Baiklah, tapi jangan jauh-jauh.",
  ui_story_5014_50141102_86_dialog_content = "Bukan masalah!",
  ui_story_5014_50141102_87_dialog_content = "Anak anjing ini lucu sekali...",
  ui_story_5014_50141102_88_dialog_content = "<color=#e8d9bb>Aurorian... Menerobos ke... Kamar Seamus.</color>",
  ui_story_5014_50141102_89_dialog_content = "Aku lihat mereka... Sial.",
  ui_story_5014_50141102_90_dialog_content = "<color=#e8d9bb>Tolong... Perintahkan...</color>",
  ui_story_5014_50141102_91_dialog_content = "Kerahkan semua robot yang ada, sekarang!",
  ui_story_5014_50141102_92_dialog_content = "<color=#e8d9bb>Mengumpulkan... Mengerahkan ke... Area tempat tinggal.</color>",
  ui_story_5014_50141102_93_dialog_content = "Kak... Kau mau ke sana?",
  ui_story_5014_50141102_94_dialog_content = "Yah, aku harus menghentikan mereka agar... tidak menghancurkan kamar ayah dan ibu.",
  ui_story_5014_50141102_95_dialog_content = "Kalau begitu, aku juga ikut!",
  ui_story_5014_50141102_96_dialog_content = "Sebaiknya tidak usah... Bagaimana kalau kau di sini saja dan istirahat?",
  ui_story_5014_50141102_97_dialog_content = "Akan kutangani mereka dan langsung kembali ke sini.",
  ui_story_5014_50141102_98_dialog_content = "Tapi, Kak, kau tak akan bisa mengalahkan mereka sendirian.",
  ui_story_5014_50141102_99_dialog_content = "Aku sudah mendapatkan kekuatan ini. Aku pasti bisa...",
  ui_story_5014_50141102_100_dialog_content = "Jangan bertindak gegabah. Utamakan keselamatanmu sendiri.",
  ui_story_5014_50141102_101_dialog_content = "Tadinya aku tak mau melawan mereka.",
  ui_story_5014_50141102_102_dialog_content = "Sekarang... Aku tahu apa yang harus kulakukan.",
  ui_story_5014_50141102_103_dialog_content = "Tolong biarkan aku ikut denganmu... Aku tak mau menunggu di sini sendirian.",
  ui_story_5014_50141102_104_dialog_content = "Kumohon, Kak... Aku takut kalau harus tinggal di sini sendirian.",
  ui_story_5014_50141102_105_dialog_content = "Huh... Baiklah, tapi berjanjilah kamu tak akan memaksakan diri atau melebihi batas kemampuanmu.",
  ui_story_5014_50141102_106_dialog_content = "Aku janji!",
  ui_story_5014_50141201_1_dialog_content = "Teman-teman... Ada robot yang masuk!",
  ui_story_5014_50141201_2_dialog_content = "Oh? Sepertinya ini saatnya menunjukkan kemampuan kita kepada mereka.",
  ui_story_5014_50141201_3_dialog_content = "Lanjutkan saja menguraikan sandinya. Kami akan berjaga di pintu.",
  ui_story_5014_50141201_4_dialog_content = "Aku khawatir pintu ini tak bisa menahan mereka lebih lama lagi...",
  ui_story_5014_50141201_5_dialog_content = "Kenapa kamu bilang begitu?",
  ui_story_5014_50141201_6_dialog_content = "Karena Valencia dan Gretel ada di sini...",
  ui_story_5014_50141201_7_dialog_content = "Kita tidak berhak menghalangi mereka... memasuki kamar ayah mereka.",
  ui_story_5014_50141201_8_dialog_content = "Biar aku saja yang bicara dengan Valencia.",
  ui_story_5014_50141201_9_dialog_content = "Dasar maling!",
  ui_story_5014_50141201_10_dialog_content = "Valencia, dengarkan aku dulu...",
  ui_story_5014_50141201_11_dialog_content = "Keluar dari kamar orang tuaku!",
  ui_story_5014_50141201_12_dialog_content = "Kenapa teriak-teriak, sih?!",
  ui_story_5014_50141201_13_dialog_content = "Kami hanya merapikan kamar ini! Kami bukan maling!",
  ui_story_5014_50141201_14_dialog_content = "Informasi itu milik orang tuaku! Berani-beraninya kalian mengobrak-abrik barang-barang mereka!",
  ui_story_5014_50141201_15_dialog_content = "Valencia, kami kemari karena ada siaran dari Seamus.",
  ui_story_5014_50141201_16_dialog_content = "Ini keinginan ayahmu...",
  ui_story_5014_50141201_17_dialog_content = "Siaran apa yang kaumaksud? Aku tak tahu apa pun tentang siaran itu.",
  ui_story_5014_50141201_18_dialog_content = "Siaran itu berasal dari Communicator milik ayahmu. Kau bisa memeriksanya...",
  ui_story_5014_50141201_19_dialog_content = "<color=#e8d9bb>Meminta untuk memeriksa... Communicator... Seamus...</color>",
  ui_story_5014_50141201_20_dialog_content = "Kak, berikan Communicator ayah kepada Butler.",
  ui_story_5014_50141201_21_dialog_content = "Baiklah...",
  ui_story_5014_50141201_22_dialog_content = "<color=#e8d9bb>Pemeriksaan selesai... Siaran... Tidak... Ditemukan...</color>",
  ui_story_5014_50141201_23_dialog_content = "Mustahil! Kami jelas-jelas menerima pesan itu.",
  ui_story_5014_50141201_24_dialog_content = "Butler tak pernah bohong. Kalian semua memang penipu!",
  ui_story_5014_50141201_25_dialog_content = "Tidak, dengarkan aku. Butler hanya tak bisa mendeteksinya.",
  ui_story_5014_50141201_26_dialog_content = "Seamus hanya mencoba menyembunyikannya dari Butler...",
  ui_story_5014_50141201_27_dialog_content = "Aku—aku tidak berpikir sampai ke sana... Maaf.",
  ui_story_5014_50141201_28_dialog_content = "Tak apa.",
  ui_story_5014_50141201_29_dialog_content = "Valencia, aku punya bukti lagi yang bisa kau...",
  ui_story_5014_50141201_30_dialog_content = "Kak, jangan dengarkan mereka! Mereka hanya berusaha memperdayamu lagi!",
  ui_story_5014_50141201_31_dialog_content = "Menerobos ke rumah kita, menghancurkan semua robot ini, dan menyerang Butler...",
  ui_story_5014_50141201_32_dialog_content = "Bahkan, setelah sekarang jadi begini... Mereka masih saja berani terang-terangan berbohong!",
  ui_story_5014_50141201_33_dialog_content = "*Kriek*",
  ui_story_5014_50141201_34_dialog_content = "Robot-robot itu kemari lagi.",
  ui_story_5014_50141201_35_dialog_content = "P-presiden...!",
  ui_story_5014_50141201_36_dialog_content = "Tenangkan dirimu, Erica... Jangan sampai kita bertindak gegabah.",
  ui_story_5014_50141201_37_dialog_content = "Yah, berdasarkan apa yang dulu terjadi di sini, asalkan kita tidak menyerang duluan, mereka juga tidak akan menyerang...",
  ui_story_5014_50141201_38_dialog_content = "Enak saja! Aku punya satu juta cara untuk membuat mereka menyerang! Dasar pembohong! Maling! Pengacau!",
  ui_story_5014_50141201_39_dialog_content = "Gretel, jangan gegabah...",
  ui_story_5014_50141201_40_dialog_content = "Butler, tumpas mereka semua!",
  ui_story_5014_50141201_41_dialog_content = "Para Aurorian ini musuh kita! Mereka adalah ancaman bagi kita dan kota ini!",
  ui_story_5014_50141201_42_dialog_content = "<color=#e8d9bb>Diterima... Lady Gretel...</color>",
  ui_story_5014_50141201_43_dialog_content = "*Suara derak kencang*",
  ui_story_5014_50141201_44_dialog_content = "Situasinya buruk... Dia sudah memberikan perintah kepada mesin itu untuk membunuh!",
  ui_story_5014_50141201_45_dialog_content = "Bagaimana dia bisa memerintah mesin-mesin di sini?!",
  ui_story_5014_50141201_46_dialog_content = "Awas, PlayerName!",
  ui_story_5014_50141201_47_dialog_content = "<color=#e8d9bb>Brak!</color>",
  ui_story_5014_50141201_48_dialog_content = "Tangkap... Tangkap...",
  ui_story_5014_50141201_49_dialog_content = "<color=#e8d9bb>Peringatan... Perintah baru... Ditingkatkan...</color>",
  ui_story_5014_50141201_50_dialog_content = "Perintah baru... Hancurkan para penyusup ini!",
  ui_story_5014_50141201_51_dialog_content = "Semuanya! Bersiaplah...",
  ui_story_5014_50141201_52_dialog_content = "Graagh!",
  ui_story_5014_50141201_53_dialog_content = "Waow, dari mana datangnya semua Eclipsite ini?!",
  ui_story_5014_50141201_54_dialog_content = "Valencia, Gretel, awas, di belakang kalian!",
  ui_story_5014_50141201_55_dialog_content = "Apa maksudmu? Kaukira mereka mengincar kami?",
  ui_story_5014_50141201_56_dialog_content = "Graagh—graagh!",
  ui_story_5014_50141201_57_dialog_content = "Siobhan, mereka makin mendekat ke arah kita.",
  ui_story_5014_50141201_58_dialog_content = "Para Eclipsite itu seolah-olah tidak melihat Valencia dan Gretel!",
  ui_story_5014_50141201_59_dialog_content = "Siobhan, kenapa para Eclipsite bertingkah seperti itu?",
  ui_story_5014_50141201_60_dialog_content = "Robot-robot ini... Bukannya mereka seharusnya menyerang Eclipsite?",
  ui_story_5014_50141201_61_dialog_content = "Begini...",
  ui_story_5014_50141201_62_dialog_content = "Dulu, saat Eclipsite menyerang kita, robot-robot itu menyerang mereka... Tapi, sekarang mereka malah bekerja sama...",
  ui_story_5014_50141201_63_dialog_content = "Robot ini menerima perintah dari kakak beradik itu... dan melindungi mereka dari gerombolan Eclipsite.",
  ui_story_5014_50141201_64_dialog_content = "Gretel dan Valencia... Mungkinkah...",
  ui_story_5014_50141201_65_dialog_content = "Jangan bilang mereka sekarang bisa mengendalikan para Eclipsite itu?!",
  ui_story_5014_50141202_1_dialog_content = "Vice, habisi mereka!",
  ui_story_5014_50141202_2_dialog_content = "Senapanku tidak bisa keluar dari sarungnya!",
  ui_story_5014_50141202_3_dialog_content = "Serahkan saja padaku—Rapid Torrent!",
  ui_story_5014_50141202_4_dialog_content = "*Kriek*",
  ui_story_5014_50141202_5_dialog_content = "Carleen, jangan memaksakan diri. Hati-hati, kamu sedang cedera...",
  ui_story_5014_50141202_6_dialog_content = "Jangan khawatir. Aku tak akan membiarkan luka kecil ini menghalangiku.",
  ui_story_5014_50141202_7_dialog_content = "Aku sudah selesai mengatasi robot-robot yang jadi jatahku ini.",
  ui_story_5014_50141202_8_dialog_content = "Baiklah, ayo kita bantu Profesor Siobhan!",
  ui_story_5014_50141202_9_dialog_content = "Graagh!",
  ui_story_5014_50141202_10_dialog_content = "Mundurlah, dasar makhluk menjijikkan!!",
  ui_story_5014_50141202_11_dialog_content = "<color=#e8d9bb>*Gruk*</color>",
  ui_story_5014_50141202_12_dialog_content = "Jangan gempa lagi, dong!",
  ui_story_5014_50141202_13_dialog_content = "Presiden, dengarkan aku... Kita tak bisa mengalahkan mesin-mesin dan gerombolan Eclipsite ini. Kita harus keluar dari sini.",
  ui_story_5014_50141202_14_dialog_content = "Jumlah mereka terlalu banyak. Kita harus menguras sumber energi mereka.",
  ui_story_5014_50141202_15_dialog_content = "Aku mengerti. Biar kuberi tahu mereka...",
  ui_story_5014_50141202_16_dialog_content = "Siobhan! Butler pasti sudah membuat beberapa robot baru. Mereka akan segera sampai di sini.",
  ui_story_5014_50141202_17_dialog_content = "Kita harus keluar dari sini sekarang sementara mereka masih terpengaruh oleh gempa ini.",
  ui_story_5014_50141202_18_dialog_content = "Kusarankan kaubiarkan saja kakak beradik itu untuk sementara ini, dan berkonsentrasi saja untuk mencari jalan keluar.",
  ui_story_5014_50141202_19_dialog_content = "...",
  ui_story_5014_50141202_20_dialog_content = "Ayo, kau harus memutuskan langkah berikutnya!",
  ui_story_5014_50141202_21_dialog_content = "Vice, ambil catatan terakhir yang kita lihat tadi...",
  ui_story_5014_50141202_22_dialog_content = "Sementara itu, ayo keluar dulu dari sini!",
  ui_story_5014_50141202_23_dialog_content = "Baik!",
  ui_story_5014_50141202_24_dialog_content = "<color=#e8d9bb>Tolong... Cepat... Hindari gempa... Sinyal...</color>",
  ui_story_5014_50141202_25_dialog_content = "*Kriek*",
  ui_story_5014_50141202_26_dialog_content = "Oh, tidak, kita juga harus berlindung dari gempa ini... Gretel!",
  ui_story_5014_50141202_27_dialog_content = "Uhh... Kak... Mereka...",
  ui_story_5014_50141202_28_dialog_content = "Gretel? Apa yang terjadi?",
  ui_story_5014_50141202_29_dialog_content = "Uhm... Aku baik-baik saja. Hanya saja... Kepalaku sakit.",
  ui_story_5014_50141202_30_dialog_content = "Biar kulihat!",
  ui_story_5014_50141202_31_dialog_content = "Uhh... Aku baik-baik saja. Sungguh, Kak, kau...",
  ui_story_5014_50141202_32_dialog_content = "Kau kejar mereka saja... Mereka mengambil... barang-barang ayah dan ibu.",
  ui_story_5014_50141202_33_dialog_content = "... Baiklah. Begitu gempanya berhenti, aku akan langsung mengejar mereka.",
  ui_story_5014_50141202_34_dialog_content = "Butler, kau harus menjaga Gretel baik-baik.",
  ui_story_5014_50141202_35_dialog_content = "<color=#e8d9bb>Aku akan... Menjaganya...</color>",
  ui_story_5014_50141301_1_dialog_content = "...",
  ui_story_5014_50141301_2_dialog_content = "Hai... Hai, kamu yang di sana...!",
  ui_story_5014_50141301_3_dialog_content = "PlayerName. Iya, kamu. Mereka masih mengejar kita tidak?",
  ui_story_5014_50141301_4_dialog_content = "Oh, maaf. Aku sedang memikirkan langkah selanjutnya.",
  ui_story_5014_50141301_5_dialog_content = "... Aku tidak melihat mesin apa pun atau Eclipsite, sih.",
  ui_story_5014_50141301_6_dialog_content = "Bagus, ini berkat Rouge...",
  ui_story_5014_50141301_7_dialog_content = "Rute penyelamatan diri yang kauambil untuk kami tadi cukup rumit, Rouge!",
  ui_story_5014_50141301_8_dialog_content = "Kedengarannya itu seperti bukan pujian, Kak Ruby...",
  ui_story_5014_50141301_9_dialog_content = "Kalau begitu, sekarang kita harus bagaimana?",
  ui_story_5014_50141301_10_dialog_content = "Diamlah... Profesor Siobhan dan Florine sedang berusaha menguraikan pesannya.",
  ui_story_5014_50141301_11_dialog_content = "Maaf. Kita bicara di sana saja...",
  ui_story_5014_50141301_12_dialog_content = "Apa Profesor Siobhan mengalami kesulitan? Dia tampak bingung...",
  ui_story_5014_50141301_13_dialog_content = "Yah, catatannya memang tidak ditulis dengan gamblang. Dia butuh waktu sedikit lagi.",
  ui_story_5014_50141301_14_dialog_content = "Apa Florine juga membantu menguraikan sandi catatan itu?",
  ui_story_5014_50141301_15_dialog_content = "Presiden sedang berusaha memahami kata-kata misterius yang ditinggalkan oleh Nimbus.",
  ui_story_5014_50141301_16_dialog_content = "Dia berusaha mati-matian untuk mengungkap misteri ini, dan pada akhirnya dia berhasil!",
  ui_story_5014_50141301_17_dialog_content = "Oh, begitu. Maksudmu, dia akhirnya menemukan solusinya setelah mencoba beberapa kali.",
  ui_story_5014_50141301_18_dialog_content = "<color=#e8d9bb>*Gruk*</color>",
  ui_story_5014_50141301_19_dialog_content = "PlayerName, apa kau tahu bagaimana Gretel bisa mengendalikan Eclipsite itu?",
  ui_story_5014_50141301_20_dialog_content = "Aku bisa paham kalau dia bisa mengendalikan robot... Tapi, Profesor Siobhan bilang, dia juga bisa mengendalikan para Eclipsite itu.",
  ui_story_5014_50141301_21_dialog_content = "Itu membuatku teringat pada kemampuan psikis Caelestite. Bukankah Caelestite juga bisa mengendalikan tindakan Aurorian?",
  ui_story_5014_50141301_22_dialog_content = "Tidak, aku tak bisa. Itu hanya gosip tak berdasar.",
  ui_story_5014_50141301_23_dialog_content = "Aku hanya bisa mengirimkan informasi dalam jumlah terbatas dengan kemampuan psikisku.",
  ui_story_5014_50141301_24_dialog_content = "Kurasa sebaiknya kita tanyakan saja hal ini kepada Profesor Siobhan... Yah, nanti setelah dia selesai.",
  ui_story_5014_50141301_25_dialog_content = "Baiklah kalau begitu.",
  ui_story_5014_50141301_26_dialog_content = "Teman-teman, kami punya informasi baru.",
  ui_story_5014_50141301_27_dialog_content = "Apa yang disebutkan Seamus dalam catatannya?",
  ui_story_5014_50141301_28_dialog_content = "Tenanglah, separuh bagian pertama catatan ini berisi cerita Seamus sendiri, serta petunjuk bagi kita, Illumina.",
  ui_story_5014_50141301_29_dialog_content = "Separuh bagian keduanya berisi beberapa informasi penting tentang fasilitas yang ada jauh di dalam kota.",
  ui_story_5014_50141301_30_dialog_content = "Akan kubagikan informasi ini dengan semua orang di sini.",
  ui_story_5014_50141301_31_dialog_content = "Kurasa sebaiknya kubacakan dulu separuh bagian pertamanya...",
  ui_story_5014_50141301_32_dialog_content = "\"Aku dan Nimbus menemukan tempat ini secara tak sengaja.\"",
  ui_story_5014_50141301_33_dialog_content = "\"Meski sudah berusaha mencari tahu lokasi catatan sejarah tentang tempat ini, aku sama sekali tak tahu harus mulai dari mana...\"",
  ui_story_5014_50141301_34_dialog_content = "Ada banyak robot di sini, masing-masing dengan tanggung jawab sendiri-sendiri, dan saat ini aku sedang mengevaluasi efisiensi mereka.",
  ui_story_5014_50141301_35_dialog_content = "Agak aneh, memang, tapi aku dan Nimbus terpaksa mengenakan pakaian khusus agar bisa bergerak dengan leluasa.",
  ui_story_5014_50141301_36_dialog_content = "Aku benar-benar harus mencari cara untuk bebas dari pakaian ini... Aku tak kunjung terbiasa mengenakannya.",
  ui_story_5014_50141301_37_dialog_content = "Aku mencoba menangkap beberapa robot agar bisa memodifikasinya. Aku bahkan juga sengaja menghancurkan beberapa...",
  ui_story_5014_50141301_37X_dialog_content = "Tapi, aku tetap tidak bisa menemukan informasi apa pun yang berharga.",
  ui_story_5014_50141301_38_dialog_content = "Mesin-mesin di sini tak pernah bersikap bermusuhan kepada kami. Kurasa kami bisa hidup di antara mereka dengan aman.",
  ui_story_5014_50141301_39_dialog_content = "Satu-satunya hal yang membuatku khawatir adalah... para Eclipsite. Jumlah mereka banyak sekali, sama seperti banyaknya hewan liar di sini.",
  ui_story_5014_50141301_40_dialog_content = "Untungnya, setiap kali para Eclipsite itu berusaha menyerang kami... Robot-robot ini akan melindungi kami.",
  ui_story_5014_50141301_41_dialog_content = "Barangkali, misi mereka adalah melindungi penghuni tempat ini, dan kami dianggap sebagai penghuni di sini.",
  ui_story_5014_50141301_42_dialog_content = "Tak lama kemudian, muncul AI bernama \"Butler\" yang menyambut kami.",
  ui_story_5014_50141301_43_dialog_content = "Dia juga menjawab sebagian pertanyaan kami.",
  ui_story_5014_50141301_44_dialog_content = "Para Ancient membangun tempat ini untuk bertahan hidup dan meneruskan garis keturunan di sini hingga bencana berlalu.",
  ui_story_5014_50141301_45_dialog_content = "Aku penasaran, bencana apa kiranya yang memaksa orang-orang ini melarikan diri ke bawah tanah...",
  ui_story_5014_50141301_46_dialog_content = "Aku sudah mencoba menanyakannya kepada Butler, tetapi setiap kali kutanya, jawabannya selalu sama—",
  ui_story_5014_50141301_47_dialog_content = "Tanpa izin...",
  ui_story_5014_50141301_48_dialog_content = "Selain tentang hal itu, sepertinya dia selalu menjawab jujur jika ditanya tentang hal-hal lain.",
  ui_story_5014_50141301_49_dialog_content = "Sekarang aku benar-benar pusing bukan kepalang. Sebenarnya apa peran Butler? Jika tugasnya adalah melindungi penghuni tempat ini...",
  ui_story_5014_50141301_50_dialog_content = "Ke mana perginya mereka semua?",
  ui_story_5014_50141301_51_dialog_content = "Tak ada jawaban.",
  ui_story_5014_50141301_52_dialog_content = "Kami terjebak...",
  ui_story_5014_50141301_53_dialog_content = "Butler tinggal jauh dari kami, dan aku tak bisa mendapatkan informasi lagi darinya.",
  ui_story_5014_50141301_54_dialog_content = "Tapi, Nimbus berkata bahwa... dia ingin tinggal di sini.",
  ui_story_5014_50141301_55_dialog_content = "Jauh dari peperangan dan pengadilan bidah.",
  ui_story_5014_50141301_56_dialog_content = "Setelah itu... Aku dan Nimbus punya anak, dan Butler membawa sebuah robot pengajar.",
  ui_story_5014_50141301_57_dialog_content = "Kukira aku akhirnya punya kesempatan untuk mencari tahu tentang masa lalu tempat ini.",
  ui_story_5014_50141301_58_dialog_content = "Tapi, materi belajarnya tidak lengkap dan informasinya terbatas.",
  ui_story_5014_50141301_59_dialog_content = "Terutama kepingan informasi yang paling penting—cara untuk memodifikasi otorisasi.",
  ui_story_5014_50141301_60_dialog_content = "Aku berhasil memodifikasi sejumlah otorisasi... Tapi, tak pernah cukup.",
  ui_story_5014_50141301_61_dialog_content = "Butler tak mau memberitahukan jalan keluarnya kepada kami.",
  ui_story_5014_50141301_62_dialog_content = "Apa kami harus tinggal di sini selamanya?",
  ui_story_5014_50141301_63_dialog_content = "Bagaimana dengan Valencia? Dan Gretel?",
  ui_story_5014_50141301_64_dialog_content = "Kalau kami tak bisa keluar dari sini, bagaimana aku bisa memberi tahu mereka... bahwa aku berasal dari Illumina?",
  ui_story_5014_50141301_65_dialog_content = "Bagaimana aku bisa menjelaskan kepada mereka bahwa ada dunia yang lebih luas di luar sana?",
  ui_story_5014_50141301_66_dialog_content = "Saat Nimbus menatapku dalam hening setiap malam, aku pun tahu...",
  ui_story_5014_50141301_67_dialog_content = "Kalaupun hanya untuk mereka... Aku harus mencari solusi.",
  ui_story_5014_50141301_68_dialog_content = "Mencari jalan keluar tanpa sepengetahuan Butler mungkin adalah hal berbahaya, tapi aku harus melakukannya.",
  ui_story_5014_50141301_69_dialog_content = "Aku harus mengajarkan lebih banyak pengetahuan dan keterampilan kepada Valencia dan Gretel.",
  ui_story_5014_50141301_70_dialog_content = "Kuharap, suatu hari nanti... Mereka akan mengambil pilihan yang tepat.",
  ui_story_5014_50141301_71_dialog_content = "Aku yakin bahwa masa depan tidaklah jauh, dan bahwa Illumina akan menuntun semua orang untuk meraih kemenangan dalam perang ini.",
  ui_story_5014_50141301_72_dialog_content = "Mungkin suatu hari nanti kami akan menemukan jalan keluar dan kembali pulang.",
  ui_story_5014_50141301_72X_dialog_content = "Mungkin saja sebelum itu, rekan-rekan kami akan kemari.",
  ui_story_5014_50141301_73_dialog_content = "Sampai saat itu tiba, aku tak tahu apakah aku dan Nimbus akan aman di sini...",
  ui_story_5014_50141301_74_dialog_content = "Kalau sampai terjadi sesuatu... Informasi ini... Semua informasi ini... Akan menjadi peninggalanku.",
  ui_story_5014_50141301_75_dialog_content = "Kutinggalkan informasi ini untuk istri dan putri-putriku, dan untuk para rekanku.",
  ui_story_5014_50141301_76_dialog_content = "Semoga siapa pun yang kelak menemukannya dan bisa menguraikannya bisa memanfaatkannya dengan baik.",
  ui_story_5014_50141301_77_dialog_content = "Seamus juga meninggalkan pesan untuk Valencia.",
  ui_story_5014_50141301_78_dialog_content = "Apa kau ingin kami memberikan surat itu kepadanya?",
  ui_story_5014_50141301_79_dialog_content = "Yah, dia memang berharap \"rekan-rekannya dari Illumina\" akan mewakilinya menyampaikan surat ini.",
  ui_story_5014_50141301_80_dialog_content = "Tapi, hanya jika Valencia sudah siap melihat dunia luar.",
  ui_story_5014_50141301_81_dialog_content = "Dia bilang catatan itu dienkripsi sedemikian rupa dan hanya Valencia yang bisa menguraikannya.",
  ui_story_5014_50141301_82_dialog_content = "Selain meninggalkan informasi untuk Illumina, dia juga meninggalkan pesan untuk putrinya...",
  ui_story_5014_50141301_83_dialog_content = "Ya. Masih ada satu bagian lagi... dan aku masih berusaha menguraikannya, tapi kira-kira itulah isinya.",
  ui_story_5014_50141301_84_dialog_content = "Di samping itu, catatan Nimbus jauh lebih sederhana.",
  ui_story_5014_50141301_85_dialog_content = "Apa kau juga sudah selesai?",
  ui_story_5014_50141301_86_dialog_content = "Yap. Kecuali beberapa catatan... yang tidak bisa kuberitahukan, aku sudah selesai membaca sandi terakhir.",
  ui_story_5014_50141301_87_dialog_content = "Apa isinya?",
  ui_story_5014_50141301_88_dialog_content = "...",
  ui_story_5014_50141301_89_dialog_content = "\"Satu-satunya yang bisa menguraikan sandi ini adalah Lumopolis Church.\"",
  ui_story_5014_50141301_90_dialog_content = "\"Tolong, biarlah dosa-dosaku ikut mati bersamaku. Putri-putriku tak bersalah.\"",
  ui_story_5014_50141301_91_dialog_content = "\"Jika perang sudah usai, tolong lindungilah anak-anakku yang tak bersalah ini.\"",
  ui_story_5014_50141301_92_dialog_content = "\"Jika dunia masih dikuasai kejahatan, tolong pergilah dan tinggalkan negeri suci ini dalam damai.\"",
  ui_story_5014_50141301_93_dialog_content = "\"Tolong... Kumohon... Jangan sakiti putri-putriku.\"",
  ui_story_5014_50141301_94_dialog_content = "\"Valencia... Gretel... Teruslah melangkah maju, entah menuju White Night atau menjaga keselamatan.\"",
  ui_story_5014_50141301_95_dialog_content = "\"Di mana pun Ibu berada, Ibu akan selalu bersama kalian...\"",
  ui_story_5014_50141301_96_dialog_content = "\"Ibu akan selalu menggandeng dan menemani kalian. Selalu...\"",
  ui_story_5014_50141301_97_dialog_content = "\"Bahkan di masa depan sekalipun, segalanya akan tetap sama.\"",
  ui_story_5014_50141301_98_dialog_content = "Aku... Aku merasa...",
  ui_story_5014_50141301_99_dialog_content = "Bahkan God of Light sekalipun pasti tersentuh kalau mendengar ungkapan kasih semurni ini.",
  ui_story_5014_50141301_100_dialog_content = "Seamus... Nimbus... Mereka sangat mencintai putri-putri mereka.",
  ui_story_5014_50141301_101_dialog_content = "Sekian tahun lalu, Nimbus tiba di sini secara tak sengaja akibat \"kejahatan\" yang dilakukannya, serta akibat ancaman perang.",
  ui_story_5014_50141301_102_dialog_content = "Seamus juga tiba di sini secara tak sengaja karena ingin melakukan ekspedisi dan akibat pengaruh perang.",
  ui_story_5014_50141301_103_dialog_content = "AI dan para robot itulah yang melindungi mereka.",
  ui_story_5014_50141301_104_dialog_content = "Selain itu, Butler juga tak mau membiarkan mereka pergi... Mereka tak punya pilihan selain tinggal di tengah AI dan para Eclipsite itu.",
  ui_story_5014_50141301_105_dialog_content = "...",
  ui_story_5014_50141301_106_dialog_content = "Kau baik-baik saja, PlayerName?",
  ui_story_5014_50141301_107_dialog_content = "Aku baik-baik saja. Hanya saja...",
  ui_story_5014_50141301_108_dialog_content = "Walaupun mereka sudah tiada, kasih mereka tetap hidup...",
  ui_story_5014_50141301_109_dialog_content = "Masih tertinggal dalam catatan-catatan itu... di dalam kota ini.",
  ui_story_5014_50141301_110_dialog_content = "Hmm, ya...",
  ui_story_5014_50141301_111_dialog_content = "*Batuk-batuk* Maaf menyela, tapi karena sekarang kita sudah tahu apa yang terjadi...",
  ui_story_5014_50141301_112_dialog_content = "Kedua catatan ini... Bukankah sebaiknya kita kembalikan saja untuk mereka?",
  ui_story_5014_50141301_113_dialog_content = "Dan minta maaf kepada mereka <size=45>dengan tulus</size>?",
  ui_story_5014_50141301_114_dialog_content = "Mungkin... mereka akan mau mendengarkan kita kalau sudah tenang?",
  ui_story_5014_50141301_115_dialog_content = "Valencia mungkin akan mau mendengarkan kita, tapi Gretel...",
  ui_story_5014_50141301_116_dialog_content = "Astaga... Kenapa Tuan dan Nyonya Seamus tidak berterus terang saja kepada mereka?",
  ui_story_5014_50141301_117_dialog_content = "Misalnya dengan bilang, \"Kalau ada yang datang, tunjukkan kedua catatan ini kepada mereka.\"",
  ui_story_5014_50141301_118_dialog_content = "\"Ikuti saja siapa pun yang bisa menguraikan pesan ini\"... Seandainya saja begitu, bagus, 'kan?",
  ui_story_5014_50141301_119_dialog_content = "Aku bisa memahami niatnya... Dia berbuat hal yang benar dengan meminta agar kakak beradik itu tetap waspada dengan dunia luar.",
  ui_story_5014_50141301_120_dialog_content = "Lagi pula, tak seorang pun tahu orang macam apa yang akan datang kemari.",
  ui_story_5014_50141301_121_dialog_content = "<color=#e8d9bb>*Gruk*</color>",
  ui_story_5014_50141301_122_dialog_content = "Gempa lagi? Astaga!",
  ui_story_5014_50141301_123_dialog_content = "Siobhan, ke mana kita harus pergi selanjutnya...",
  ui_story_5014_50141301_124_dialog_content = "Ayo kita masuk lebih dalam. Sistem kontrol dan fasilitas inti sistem... ada di kedalaman kota ini.",
  ui_story_5014_50141301_125_dialog_content = "Masuk lebih dalam berarti kita menghadapi risiko akan terkena gempa lagi... Apa menurutmu kita bisa menemukan jalan keluarnya di sana?",
  ui_story_5014_50141301_126_dialog_content = "Yah, ada dua alasan yang membuat Seamus meninggalkan koordinatnya jauh di dalam kota...",
  ui_story_5014_50141301_127_dialog_content = "Alasan pertama adalah karena informasi tentang cara masuk dan keluar kota ini mungkin tersimpan di sistem kontrol.",
  ui_story_5014_50141301_128_dialog_content = "Alasan kedua adalah karena gempa sering terjadi di sini akibat inti energinya tidak stabil.",
  ui_story_5014_50141301_129_dialog_content = "Mungkin saja Seamus ingin ke sana untuk memperbaikinya.",
  ui_story_5014_50141301_130_dialog_content = "Apa dia bilang bahwa dia berniat memperbaikinya?",
  ui_story_5014_50141301_131_dialog_content = "Semua itu hanya teori... Catatan ini ditulis sebelum dia masuk jauh ke dalam kota.",
  ui_story_5014_50141301_132_dialog_content = "Dia meninggalkan beberapa koordinat jalan masuk ke dalam kota. Kita harus memeriksanya satu per satu...",
  ui_story_5014_50141301_133_dialog_content = "Coba kita cari tahu mana yang masih bisa digunakan, atau mana yang belum disegel oleh Butler.",
  ui_story_5014_50141301_134_dialog_content = "<color=#e8d9bb>*Suara bergemuruh, disusul ledakan*</color>",
  ui_story_5014_50141301_135_dialog_content = "Aduh, semoga kita tidak terkubur di tengah jalan akibat gempa ini...",
  ui_story_5014_50141301_136_dialog_content = "Ini kan memang Undercity. Artinya, bisa dibilang kita sebenarnya memang sudah terkubur di bawah tanah.",
  ui_story_5014_50141301_137_dialog_content = "Tapi... Aku tak mau melihat langit runtuh.",
  ui_story_5014_50141301_138_dialog_content = "Siobhan, apa ada kemungkinan kota ini akan runtuh?",
  ui_story_5014_50141301_139_dialog_content = "Tergantung kondisi inti energinya. Aku tak bisa tahu kalau belum melihatnya secara langsung.",
  ui_story_5014_50141301_140_dialog_content = "Apa pun itu, kita harus bergerak cepat.",
  ui_story_5014_50141301_141_dialog_content = "Kami juga akan ikut denganmu. Aku bisa membantu.",
  ui_story_5014_50141301_142_dialog_content = "Yah, toh memang tak ada tempat lain yang bisa kita tuju.",
  ui_story_5014_50141301_143_dialog_content = "Baiklah, kalau begitu, aku akan mencari lokasi Valencia dan Gretel bersama PlayerName.",
  ui_story_5014_50141301_144_dialog_content = "Kalian pastikan lokasi pintu masuknya, dan mulailah memeriksa jalan menuju bagian dalam kota.",
  ui_story_5014_50141301_145_dialog_content = "Memangnya kau tak takut bahwa aku dan Erica mungkin saja akan menghancurkan teknologi kuno itu begitu kami berhasil menemukannya?",
  ui_story_5014_50141301_146_dialog_content = "Aku sepenuhnya sadar akan niatmu itu, tapi masih ada satu teknologi kuno lagi.",
  ui_story_5014_50141301_147_dialog_content = "Keturunan rekan-rekan sebangsa ini memang unik.",
  ui_story_5014_50141301_148_dialog_content = "Rupanya harapanmu kepada mereka belum pupus...",
  ui_story_5014_50141301_149_dialog_content = "Setelah membaca catatan Nimbus, memangnya apa kau mau begitu saja menyerah untuk mengharapkan mereka?",
  ui_story_5014_50141301_150_dialog_content = "Karena mereka keturunan Lumopolis... Tentu saja, kami juga tak ingin mereka mengalami hal buruk.",
  ui_story_5014_50141301_151_dialog_content = "Kalau begitu, kuserahkan Valencia dan Gretel kepadamu, Siobhan. Berusahalah semampumu untuk membujuk mereka...",
  ui_story_5014_50141301_152_dialog_content = "Ayo kita bawa mereka keluar dari tempat berbahaya ini dan pulang bersama kita.",
  ui_story_5014_50141301_153_dialog_content = "Terserah mereka apakah mau pulang ke Illumina atau Lumopolis.",
  ui_story_5014_50141301_154_dialog_content = "Baiklah, akan kulakukan.",
  ui_story_5014_50141301_155_dialog_content = "Sebagai gantinya, kecuali AI itu... aku akan pura-pura tidak menemukan apa-apa lagi di sini.",
  ui_story_5014_50141301_156_dialog_content = "Bagaimana kau bisa yakin kau lebih cepat dari aku?",
  ui_story_5014_50141301_157_dialog_content = "Menurutmu, mana yang lebih sulit? Mencari jalan keluar atau meyakinkan kakak beradik itu?",
  ui_story_5014_50141301_158_dialog_content = "*Tertawa*... Jalan menuju dalam kota mungkin saja berbahaya. Jadi, hati-hatilah.",
  ui_story_5014_50141301_159_dialog_content = "Tenanglah, kau meremehkan kami, nih... Sampai jumpa lagi.",
  ui_story_5014_50141301_160_dialog_content = "Sampai jumpa.",
  ui_story_5014_50141401_1_dialog_content = "*Suara terengah-engah*",
  ui_story_5014_50141401_2_dialog_content = "Pelan-pelan, Siobhan... Vice... Aku...",
  ui_story_5014_50141401_3_dialog_content = "Apa kau perlu kugendong, PlayerName?",
  ui_story_5014_50141401_4_dialog_content = "Tidak, kau kan masih cedera. Aku... Jangan hiraukan aku. Aku akan berusaha sebisaku untuk mengimbangi laju kalian!",
  ui_story_5014_50141401_5_dialog_content = "Sebentar lagi kita akan sampai lagi di area tempat tinggal. Bertahanlah sebentar lagi...",
  ui_story_5014_50141401_6_dialog_content = "Tunggu sebentar... Mereka menyadari keberadaan kita. Kita bisa berhenti berlari.",
  ui_story_5014_50141401_7_dialog_content = "Jumlah robot yang menemaninya banyak sekali...",
  ui_story_5014_50141401_8_dialog_content = "Sepertinya aku tak perlu repot-repot berusaha mencari kalian...",
  ui_story_5014_50141401_9_dialog_content = "Valencia, dengarkan aku...",
  ui_story_5014_50141401_10_dialog_content = "Diam!",
  ui_story_5014_50141401_11_dialog_content = "Apa kalian masih mau mencoba menyusup ke kamar ayahku untuk mencuri barang-barangnya?!",
  ui_story_5014_50141401_12_dialog_content = "Tidak, Valencia... Berkat catatan ayahmu, kami sedikit banyak tahu tentang apa yang terjadi di sini.",
  ui_story_5014_50141401_13_dialog_content = "Ayahmu selalu berharap bahwa rekan-rekannya dari Illumina akan menemukan tempat ini... Karena itu, dia menyiarkannya.",
  ui_story_5014_50141401_14_dialog_content = "Tapi, kami terlambat menerima siaran data itu. Saat kami akhirnya menerimanya, kau sudah terlanjur salah sangka tentang niat kami.",
  ui_story_5014_50141401_15_dialog_content = "Gara-gara itu, kita jadi terjebak dalam situasi seperti ini...",
  ui_story_5014_50141401_16_dialog_content = "Hentikan omong kosongmu, dan kembalikan catatan ayahku!",
  ui_story_5014_50141401_17_dialog_content = "Tenanglah. Lihat... Semua catatannya ada di sini.",
  ui_story_5014_50141401_18_dialog_content = "Ayahmu ingin kami membawamu keluar dari sini karena tempat ini mungkin saja sewaktu-waktu runtuh...",
  ui_story_5014_50141401_19_dialog_content = "Runtuh...?",
  ui_story_5014_50141401_20_dialog_content = "Ya, dia meninggalkan banyak info dengan sandi enkripsi di dalam catatannya.",
  ui_story_5014_50141401_21_dialog_content = "Dia juga menyebutkan bahwa inti energi kota ini bermasalah.",
  ui_story_5014_50141401_22_dialog_content = "Selama ini, dia berusaha memperbaiki inti itu sambil mencari jalan keluar dari sini.",
  ui_story_5014_50141401_23_dialog_content = "Sebelum dia meninggal, dia meninggalkan sebuah pesan untukmu. Aku yakin kau akan langsung memahaminya saat membaca pesan itu...",
  ui_story_5014_50141401_24_dialog_content = "...",
  ui_story_5014_50141401_25_dialog_content = "Valencia?",
  ui_story_5014_50141401_26_dialog_content = "Kau memeriksa catatan ayahku dan mengambilnya?",
  ui_story_5014_50141401_27_dialog_content = "Jangan salah sangka. Inilah yang diinginkan ayahmu.",
  ui_story_5014_50141401_28_dialog_content = "Berikan saja semua yang kalian pegang.",
  ui_story_5014_50141401_29_dialog_content = "Baiklah, ambillah.",
  ui_story_5014_50141401_30_dialog_content = "Dan jangan mendekat.",
  ui_story_5014_50141401_31_dialog_content = "Valencia, tolong baca pesan terakhir darinya dulu. Ayahmu bilang...",
  ui_story_5014_50141401_32_dialog_content = "Diam...",
  ui_story_5014_50141401_33_dialog_content = "Siobhan... Mari kita beri Valencia ruang.",
  ui_story_5014_50141401_34_dialog_content = "Raut wajah Valencia menunjukkan ada sesuatu yang tidak beres... Aku bisa merasakan bahwa dia merasa...",
  ui_story_5014_50141401_35_dialog_content = "Kalian... menerobos masuk ke rumah orang...",
  ui_story_5014_50141401_36_dialog_content = "Mengambil barang-barang ayahku tanpa izin... Terus-menerus berbohong...",
  ui_story_5014_50141401_37_dialog_content = "Bahkan membaca sesuatu yang rahasia...",
  ui_story_5014_50141401_38_dialog_content = "Valencia, tenanglah.",
  ui_story_5014_50141401_39_dialog_content = "Informasi ini bukan hal yang bisa kuutak-utik seenak hati!",
  ui_story_5014_50141401_40_dialog_content = "<size=45>Ini peninggalan ayahku!!</size>",
  ui_story_5014_50141401_41_dialog_content = "Dengarkan aku dulu...",
  ui_story_5014_50141401_42_dialog_content = "*Kriek*",
  ui_story_5014_50141402_1_dialog_content = "Pertama-tama, kita atasi dulu ancaman ini... Setelah itu, kita akan bicara dengannya.",
  ui_story_5014_50141402_2_dialog_content = "Kurasa dia baru akan bisa tenang kalau sudah kehilangan senjatanya itu.",
  ui_story_5014_50141402_3_dialog_content = "PlayerName, apa yang dirasakannya sekarang?",
  ui_story_5014_50141402_4_dialog_content = "Yah, setidaknya dia sudah berhenti menyerang.",
  ui_story_5014_50141402_5_dialog_content = "Kalian kira menghancurkan robot-robot ini saja sudah cukup untuk menghentikanku agar tidak mengejar kalian?",
  ui_story_5014_50141402_6_dialog_content = "Aku masih punya...",
  ui_story_5014_50141402_7_dialog_content = "Valencia, ayahmu sungguh-sungguh ingin membawamu keluar dari sini.",
  ui_story_5014_50141402_8_dialog_content = "Ini adalah tempat berlindung yang dibangun oleh Ancient, yang ditemukan ayahmu bertahun-tahun lalu.",
  ui_story_5014_50141402_9_dialog_content = "Walau di sini memang ada AI canggih dan fasilitas lain yang bisa membantumu bertahan hidup...",
  ui_story_5014_50141402_10_dialog_content = "Di sini juga ada banyak masalah lain...",
  ui_story_5014_50141402_11_dialog_content = "Terutama sekarang—gempa yang begitu sering terjadi ini mungkin saja akan membuat kota ini runtuh!",
  ui_story_5014_50141402_12_dialog_content = "Valencia, aku yakin ayahmu sudah mengajarimu tentang inti energi itu.",
  ui_story_5014_50141402_13_dialog_content = "Tak ada yang salah dengan inti energi itu...",
  ui_story_5014_50141402_14_dialog_content = "Dan seandainya kota ini memang runtuh, kami masih bisa membangun rumah-rumah itu lagi! Ini bukan urusan kalian!",
  ui_story_5014_50141402_15_dialog_content = "Tolong, biar kuselesaikan dulu. Lihat sendiri catatan ayahmu!",
  ui_story_5014_50141402_16_dialog_content = "Ayahmu bilang, kau pasti bisa memecahkannya dengan ilmu kriptografi yang ditinggalkannya.",
  ui_story_5014_50141402_17_dialog_content = "Kau bahkan tahu tentang kriptografi?!",
  ui_story_5014_50141402_18_dialog_content = "Situasinya buruk... Sepertinya pikirannya lagi-lagi teralih.",
  ui_story_5014_50141402_19_dialog_content = "Anak-anak yang pikirannya belum dewasa memang sering kali membayangkan hal-hal yang ekstrem.",
  ui_story_5014_50141402_20_dialog_content = "Tapi, Valencia, aku yakin ayahmu sudah mengajarimu untuk tetap tenang walau sedang menghadapi ancaman.",
  ui_story_5014_50141402_21_dialog_content = "Kumpulkan informasi sebanyak mungkin dan nilailah setiap situasi dengan objektif. Ini juga yang kami ajarkan di Illumina...",
  ui_story_5014_50141402_22_dialog_content = "Saat pertama kali bertemu denganmu, aku bisa merasakan bahwa kau sangat baik.",
  ui_story_5014_50141402_23_dialog_content = "Kau kuat, berani, baik, antusias, penuh rasa ingin tahu, dan haus akan pengetahuan.",
  ui_story_5014_50141402_24_dialog_content = "Sama seperti semua orang Illumina... Kau memang sungguh anak Illumina.",
  ui_story_5014_50141402_25_dialog_content = "...",
  ui_story_5014_50141402_26_dialog_content = "Maafkan aku, Valencia. Perbuatan kami tadi tidak sopan.",
  ui_story_5014_50141402_27_dialog_content = "Izinkan aku menjelaskan semuanya dan percayalah kepadaku sekali lagi.",
  ui_story_5014_50141402_28_dialog_content = "Kita tahu bahwa kota ini dalam bahaya besar.",
  ui_story_5014_50141402_29_dialog_content = "Tapi, aku tak bisa begitu saja pergi tanpa kalian berdua, karena kalian adalah anak-anak Seamus.",
  ui_story_5014_50141402_30_dialog_content = "Anak yang telah dipercayakan Seamus kepada Illumina.",
  ui_story_5014_50141402_31_dialog_content = "Baiklah, akan kubaca pesannya. Sekarang juga, di sini.",
  ui_story_5014_50141402_32_dialog_content = "Tapi, kalau kau sampai berani berbuat apa pun sementara aku sedang membaca pesan ini, aku pasti akan...",
  ui_story_5014_50141402_33_dialog_content = "Kami tak akan berbuat apa pun, apalagi membahayakanmu... Percayalah kepada kami.",
  ui_story_5014_50141402_34_dialog_content = "Kak, kau tak boleh percaya kepada mereka!",
  ui_story_5014_50141402_35_dialog_content = "Gretel...",
  ui_story_5014_50141402_36_dialog_content = "Wanita itu disuruh kemari untuk mengulur waktu kita!",
  ui_story_5014_50141402_37_dialog_content = "Yang lainnya sedang berusaha masuk ke dalam kota!!",
  ui_story_5014_50141402_38_dialog_content = "Ini koordinat terakhir...",
  ui_story_5014_50141402_39_dialog_content = "Ketemu, Kak Ruby, Florine—di bawah sini memang ada jalan.",
  ui_story_5014_50141402_40_dialog_content = "Aku tak mengira Rediesel Wrench ternyata sangat efisien seperti ini...",
  ui_story_5014_50141402_41_dialog_content = "Oh? Apakah akhirnya kau mengizinkan kami dalam tim petualanganmu?",
  ui_story_5014_50141402_42_dialog_content = "Yah, baguslah, kurasa.",
  ui_story_5014_50141402_43_dialog_content = "Aku ingin tahu apakah jalan ini juga buntu seperti jalan-jalan yang lainnya...",
  ui_story_5014_50141402_44_dialog_content = "Jangan khawatir. Dengan pengalamanku yang sudah banyak ini, cukup dengan mengentakkan kaki saja, aku bisa tahu kalau ada sesuatu.",
  ui_story_5014_50141402_45_dialog_content = "Dan di sini...",
  ui_story_5014_50141402_46_dialog_content = "Haha, tepat.",
  ui_story_5014_50141402_47_dialog_content = "Presiden, sepertinya ada sesuatu yang kuno dan mengerikan di bawah sana, dan dia berputar-putar tak terkendali.",
  ui_story_5014_50141402_48_dialog_content = "Keyakinanku mengatakan bahwa kita harus turun ke bawah sana. Kita harus segera menghancurkannya!",
  ui_story_5014_50141402_49_dialog_content = "Aku tahu, Erica.",
  ui_story_5014_50141402_50_dialog_content = "Inti energi kota ini dan sistem kontrol intinya ada di bawah sini.",
  ui_story_5014_50141402_51_dialog_content = "Di bawah sini, mungkin ada jalan keluar dari Undercity.",
  ui_story_5014_50141402_52_dialog_content = "Saat kau sudah sampai di bawah, ikuti petunjukku. Jangan bertindak gegabah.",
  ui_story_5014_50141402_53_dialog_content = "Baik, Presiden... Aku akan mengikuti petunjukmu.",
  ui_story_5014_50141402_54_dialog_content = "Ruby, Rouge, kalian berdua juga. Untuk sekarang, kita harus bertindak serentak.",
  ui_story_5014_50141402_55_dialog_content = "Begitu kau sudah sampai di dasarnya, dengarkan aku baik-baik.",
  ui_story_5014_50141501_1_dialog_content = "Gretel justru muncul tepat saat kita sedang berusaha meyakinkan Valencia... Lagi-lagi begini, nih.",
  ui_story_5014_50141501_2_dialog_content = "Sudah jelas bahwa mereka berpencar agar bisa lebih cepat memecahkan masalah...",
  ui_story_5014_50141501_3_dialog_content = "Kenapa malah jadi salah paham lagi?",
  ui_story_5014_50141501_4_dialog_content = "Dan bagaimana bisa Gretel tahu...",
  ui_story_5014_50141501_5_dialog_content = "Vice, kau tak boleh bertanya seperti itu. Bisa-bisa nanti Gretel salah sangka lagi tentang kita.",
  ui_story_5014_50141501_6_dialog_content = "Segala yang kita lakukan di sini diamati... Yah, bisa kupahami.",
  ui_story_5014_50141501_7_dialog_content = "Menurutku, sejak awal Gretel memang sudah sengaja menunjukkan sikap bermusuhan kepada kita... Ini bukan kesalahpahaman.",
  ui_story_5014_50141501_8_dialog_content = "Mungkin... baginya \"dunia luar\" adalah tempat yang dipenuhi ketidakpastian dan ketakutan.",
  ui_story_5014_50141501_9_dialog_content = "Jangan menjelek-jelekkanku lagi! Kaukira aku tak bisa mendengarmu?!",
  ui_story_5014_50141501_10_dialog_content = "Pendengaranku sangat tajam, tahu!",
  ui_story_5014_50141501_11_dialog_content = "Dengar, dengarkan aku...",
  ui_story_5014_50141501_12_dialog_content = "Ayahmu berasal dari Illumina Federation, dan kami adalah rekan sebangsanya.",
  ui_story_5014_50141501_13_dialog_content = "Dia dan ibumu tak sengaja terperangkap di sini dan tak punya pilihan lain selain tinggal di sini.",
  ui_story_5014_50141501_14_dialog_content = "Aku yakin dia menahan diri untuk tidak memberitahukan beberapa hal tertentu kepadamu agar masa kecilmu tak terganggu.",
  ui_story_5014_50141501_15_dialog_content = "Tapi, dia meninggalkan pesan bagi rekan-rekan sebangsanya di Illumina Federation, dan berharap kami bisa menemukan tempat ini dan membawa kalian pulang...",
  ui_story_5014_50141501_16_dialog_content = "Kau bisa membaca catatan ayahmu atau menanyakannya kepada kakakmu. Dia tahu...",
  ui_story_5014_50141501_17_dialog_content = "Kalian memperdaya kakakku! Aku tahu semua tentang itu!",
  ui_story_5014_50141501_18_dialog_content = "Kau... Kenapa kau terus bersikeras tentang itu?!",
  ui_story_5014_50141501_19_dialog_content = "Memangnya kaukira kau ini siapa, berani-beraninya menyanggahku?!",
  ui_story_5014_50141501_20_dialog_content = "Aku bukannya menyanggahmu. Kenapa kau menganggapku menyanggahmu...",
  ui_story_5014_50141501_21_dialog_content = "Kota ini perlahan runtuh, inti energinya bermasalah, dan semua orang di sini berada dalam bahaya!",
  ui_story_5014_50141501_22_dialog_content = "Kami hanya menginginkan yang terbaik untuk kalian berdua...",
  ui_story_5014_50141501_23_dialog_content = "Kau sudah selesai bicara?",
  ui_story_5014_50141501_24_dialog_content = "Kau, apa-apaan... Rupanya dari tadi kau tak menyimak kata-kataku sedikit pun, ya?",
  ui_story_5014_50141501_25_dialog_content = "Kaukira aku mudah tertipu seperti kakakku, ya?",
  ui_story_5014_50141501_26_dialog_content = "Gretel, aku hanya mengatakan yang sebenarnya!",
  ui_story_5014_50141501_27_dialog_content = "Butler, bagaimana keadaan kakakku?",
  ui_story_5014_50141501_28_dialog_content = "Gretel, aku baik-baik saja... Tak usah mengkhawatirkanku.",
  ui_story_5014_50141501_29_dialog_content = "<color=#e8d9bb>Memulai pemeriksaan... Fisik... Kelelahan... Curiga... Ada rangsangan mental.</color>",
  ui_story_5014_50141501_30_dialog_content = "<color=#e8d9bb>Pertarungan barusan... Sengit sekali.</color>",
  ui_story_5014_50141501_31_dialog_content = "Kau memukul kakakku!",
  ui_story_5014_50141501_32_dialog_content = "Kami tak punya pilihan...",
  ui_story_5014_50141501_33_dialog_content = "Valencia menyerang kami duluan.",
  ui_story_5014_50141501_34_dialog_content = "Sebenarnya dia hanya kelelahan akibat berusaha mengendalikan robot-robot itu.",
  ui_story_5014_50141501_35_dialog_content = "Kalau tak percaya, tanyakan saja sendiri kepada Butler.",
  ui_story_5014_50141501_36_dialog_content = "Butler, mereka menggunakanmu untuk memerintah para robot itu, 'kan?",
  ui_story_5014_50141501_37_dialog_content = "Kenapa tiba-tiba kau memberikan perintah secara langsung?",
  ui_story_5014_50141501_38_dialog_content = "<color=#e8d9bb>Aurorian... Tidak berwenang...</color>",
  ui_story_5014_50141501_39_dialog_content = "Aku tak perlu bertanya kepadanya. Butler bukan pembohong seperti kalian.",
  ui_story_5014_50141501_40_dialog_content = "<color=#e8d9bb>Informasiku... Adalah fakta.</color>",
  ui_story_5014_50141501_41_dialog_content = "Gretel, apa kau mengendalikan sistem kota ini melalui Butler?",
  ui_story_5014_50141501_42_dialog_content = "Kalau kau bisa memeriksa statusnya lagi, kau akan tahu bahwa tempat ini sungguh tak aman.",
  ui_story_5014_50141501_43_dialog_content = "Aku bukan sebatas mengendalikan sistem itu. Aku bisa mengendalikan semua yang ada di dalamnya...",
  ui_story_5014_50141501_44_dialog_content = "Terima kasih sudah mengingatkanku, dasar penyusup, pembohong, maling!",
  ui_story_5014_50141501_45_dialog_content = "Butler, seperti kataku, aktifkan programnya dan naikkan peringatannya lagi.",
  ui_story_5014_50141501_46_dialog_content = "Gretel, jangan...",
  ui_story_5014_50141501_47_dialog_content = "<color=#e8d9bb>Diterima. Mereset... Menjalankan... Meningkatkan kewaspadaan...</color>",
  ui_story_5014_50141501_48_dialog_content = "Apa kita akan bertarung lagi?",
  ui_story_5014_50141501_49_dialog_content = "Gerombolan Eclipsite itu mendekat lagi seperti tadi... Sepertinya mereka hanya mengincar kita.",
  ui_story_5014_50141501_50_dialog_content = "Bagaimana mungkin Gretel bisa mengendalikan mereka...",
  ui_story_5014_50141501_51_dialog_content = "Tapi, daripada itu, aku ingin tahu bagaimana kita bisa melepaskan diri dari makhluk-makhluk menyebalkan itu.",
  ui_story_5014_50141502_1_dialog_content = "Di belakangmu... Yang terakhir!",
  ui_story_5014_50141502_2_dialog_content = "Masih ada lagi di sini! Ice Blossom!!",
  ui_story_5014_50141502_3_dialog_content = "Mana mungkin aku kalah...? Kalian hanya bertiga! Bagaimana mungkin kalian masih bisa bertahan?!",
  ui_story_5014_50141502_4_dialog_content = "Tiga? Memangnya aku tidak dihitung, ya?",
  ui_story_5014_50141502_5_dialog_content = "Pasti aku sangat lemah...",
  ui_story_5014_50141502_6_dialog_content = "Karena aku lemah, ayah dan ibu meninggal...",
  ui_story_5014_50141502_7_dialog_content = "Karena aku lemah, kalian berhasil menyusup ke rumah kami dan mengancam kakakku!",
  ui_story_5014_50141502_8_dialog_content = "Gretel, pikirkan orang tuamu. Mereka pasti tak ingin melihatmu seperti ini...",
  ui_story_5014_50141502_9_dialog_content = "Kau ingin aku memikirkan ayah ibuku...?",
  ui_story_5014_50141502_10_dialog_content = "Aku sangat merindukan mereka... Selalu...",
  ui_story_5014_50141502_11_dialog_content = "Kurasa, seandainya saja mereka masih ada di sini, mereka pasti tak akan membiarkan kalian...",
  ui_story_5014_50141502_12_dialog_content = "Menggangguku dan kakakku...",
  ui_story_5014_50141502_13_dialog_content = "Gretel, tenangkan dirimu. Biar kubacakan pesan dari ayah dulu, ya?",
  ui_story_5014_50141502_14_dialog_content = "*Hiks*",
  ui_story_5014_50141502_15_dialog_content = "Valencia, apa orang tuamu diserang oleh Eclipsite saat mereka mencari jalan keluar?",
  ui_story_5014_50141502_16_dialog_content = "Ya, tapi Gretel... Dia tak ingat tentang hal itu... Aku tak bisa mengatakannya di depannya.",
  ui_story_5014_50141502_17_dialog_content = "Sayang, gempanya muncul lagi.",
  ui_story_5014_50141502_18_dialog_content = "Aku tahu... Ini bukan pertanda baik.",
  ui_story_5014_50141502_19_dialog_content = "Bagaimana kalau kita berhenti mencari jalan keluar sampai gempanya berhenti?",
  ui_story_5014_50141502_20_dialog_content = "Aku juga berpikir begitu. Setidaknya kita akan aman di kota.",
  ui_story_5014_50141502_21_dialog_content = "Ayo segera kembali...",
  ui_story_5014_50141502_22_dialog_content = "Graagh!",
  ui_story_5014_50141502_23_dialog_content = "Eclipsite?! Di sini?!",
  ui_story_5014_50141502_24_dialog_content = "Sialan! Robot-robot penjaga ini terpengaruh gempa..",
  ui_story_5014_50141502_25_dialog_content = "Ayo! Lewat sini!",
  ui_story_5014_50141502_26_dialog_content = "Kepalaku sakit... Aku tidak mau memikirkannya... Tidak mau... *Hiks*",
  ui_story_5014_50141502_27_dialog_content = "Gretel, ada apa?! Aku di sini. Jangan takut. Aku di sini...",
  ui_story_5014_50141502_28_dialog_content = "<color=#e8d9bb>Brak!</color>",
  ui_story_5014_50141502_29_dialog_content = "Ibu, masuklah ke sini!",
  ui_story_5014_50141502_30_dialog_content = "<color=#e8d9bb>Klik, klik, klik...</color>",
  ui_story_5014_50141502_31_dialog_content = "K-kenapa tidak mau terbuka? Ibu, aku tak bisa membuka pintunya!",
  ui_story_5014_50141502_32_dialog_content = "Pintunya tidak bisa dibuka!!",
  ui_story_5014_50141502_33_dialog_content = "Aku mengunci pintunya... Kau tetap di sana saja.",
  ui_story_5014_50141502_34_dialog_content = "Cepat, sembunyilah... Semua akan baik-baik saja.",
  ui_story_5014_50141502_35_dialog_content = "Valencia, Gretel... Kalian berdua, jangan keluar... *batuk-batuk*",
  ui_story_5014_50141502_36_dialog_content = "Ibu?",
  ui_story_5014_50141502_37_dialog_content = "Apa yang terjadi, Ibu?!",
  ui_story_5014_50141502_38_dialog_content = "*Hiks* Tolong, buka pintunya...",
  ui_story_5014_50141502_39_dialog_content = "Ingat... Lindungi... adikmu...",
  ui_story_5014_50141502_40_dialog_content = "...",
  ui_story_5014_50141502_41_dialog_content = "Aaaaaaaargh!!",
  ui_story_5014_50141502_42_dialog_content = "<color=#e8d9bb>*Gruk*</color>",
  ui_story_5014_50141502_43_dialog_content = "Barusan dia melepaskan energi yang luar biasa kuat, ya?!",
  ui_story_5014_50141502_44_dialog_content = "<color=#e8d9bb>Peringatan! Peringatan!</color>",
  ui_story_5014_50141502_45_dialog_content = "<color=#e8d9bb>Akses tanpa izin... Penyusup! Memasuki... Area inti!</color>",
  ui_story_5014_50141502_46_dialog_content = "Mungkinkah itu Florine dan yang lainnya?",
  ui_story_5014_50141502_47_dialog_content = "Butler bilang... Inti harus dilindungi...",
  ui_story_5014_50141502_48_dialog_content = "<color=#e8d9bb>Penyusup... Akan... Menghancurkan... Segalanya...</color>",
  ui_story_5014_50141502_49_dialog_content = "<color=#e8d9bb>Menghancurkan... Segalanya...!</color>",
  ui_story_5014_50141502_50_dialog_content = "Jangan dengarkan dia!",
  ui_story_5014_50141502_51_dialog_content = "Tempat ini sudah hampir runtuh, dan teman-teman kami sedang mencari jalan keluar!",
  ui_story_5014_50141502_52_dialog_content = "Harus bantu Butler... Menanganimu!",
  ui_story_5014_50141502_53_dialog_content = "*Kriek*",
  ui_story_5014_50141601_1_dialog_content = "Serang!",
  ui_story_5014_50141601_2_dialog_content = "*Kriek*",
  ui_story_5014_50141601_3_dialog_content = "Aku bilang serang!!",
  ui_story_5014_50141601_4_dialog_content = "*Kriek*",
  ui_story_5014_50141601_5_dialog_content = "Butler, teruskan! Sedang apa kau?!",
  ui_story_5014_50141601_6_dialog_content = "<color=#e8d9bb>Bersihkan... Bersihkan... Bersihkan...</color>",
  ui_story_5014_50141601_7_dialog_content = "Kau tidak lihat Eclipsite di sana, ya?! Perintahkan mereka!",
  ui_story_5014_50141601_8_dialog_content = "<color=#e8d9bb>Perintahkan... Tanpa terkecuali... Habisi semua!</color>",
  ui_story_5014_50141601_9_dialog_content = "Argh...",
  ui_story_5014_50141601_10_dialog_content = "Graagh!",
  ui_story_5014_50141601_11_dialog_content = "Apa Butler memberikan perintah kepada para Eclipsite itu?",
  ui_story_5014_50141601_12_dialog_content = "Gretel bisa mengendalikan robot-robot itu karena Butler, yang membuat robot-robot itu, ada di bawah perintahnya.",
  ui_story_5014_50141601_13_dialog_content = "Jadi, kalau kau bisa memerintah Eclipsite, bukankah itu berarti...",
  ui_story_5014_50141601_14_dialog_content = "Para Eclipsite itu dibuat oleh Butler?",
  ui_story_5014_50141601_15_dialog_content = "Butler menyangkalnya.",
  ui_story_5014_50141601_16_dialog_content = "Berarti dia bohong... \"Butler hanya mengatakan fakta\" juga adalah kebohongan yang dikatakannya kepada kakak beradik itu.",
  ui_story_5014_50141601_17_dialog_content = "Untuk sekarang, kita harus terlebih dulu mengatasi musuh-musuh ini.",
  ui_story_5014_50141601_18_dialog_content = "Tapi, jumlah mereka tak ada habisnya...",
  ui_story_5014_50141601_19_dialog_content = "Sepertinya kita harus menundukkan orang yang memberikan perintah kepada mereka...",
  ui_story_5014_50141601_X19_dialog_content = "Gretel.",
  ui_story_5014_50141601_20_dialog_content = "<color=#e8d9bb>Peringatan... Bahaya besar... terdeteksi... Lari... Gretel...</color>",
  ui_story_5014_50141601_21_dialog_content = "Tunggu, tunggu! Jangan sakiti Gretel!",
  ui_story_5014_50141601_22_dialog_content = "Dia tak tahu apa yang dilakukannya!",
  ui_story_5014_50141601_23_dialog_content = "Serang... Serang... Semua, semua orang...",
  ui_story_5014_50141601_24_dialog_content = "Habisi mereka...!",
  ui_story_5014_50141601_25_dialog_content = "<color=#e8d9bb>Peringatan... Prioritas... Dalam ancaman!</color>",
  ui_story_5014_50141601_26_dialog_content = "Kita dalam masalah. Butler mengira kita berusaha menyakiti Gretel.",
  ui_story_5014_50141601_27_dialog_content = "<color=#e8d9bb>Brak! Brak!</color>",
  ui_story_5014_50141601_28_dialog_content = "Menjauhlah! Tak akan kubiarkan kau menyakiti Gretel!",
  ui_story_5014_50141601_29_dialog_content = "Kalian semua! Menjauhlah!",
  ui_story_5014_50141601_30_dialog_content = "Aku... Lagi, lagi... Lindungi... Rumah...",
  ui_story_5014_50141601_31_dialog_content = "Kakak...",
  ui_story_5014_50141601_32_dialog_content = "Gretel, tenanglah. Dengarkan aku... Kendalikan emosimu!",
  ui_story_5014_50141601_33_dialog_content = "Valencia, biarkan kami membantu! Aku mungkin bisa membantunya!",
  ui_story_5014_50141601_34_dialog_content = "Jangan mendekat!",
  ui_story_5014_50141601_35_dialog_content = "Jangan dekat-dekat dengan adikku!",
  ui_story_5014_50141602_1_dialog_content = "Kak... Kakak...",
  ui_story_5014_50141602_2_dialog_content = "Gretel... Bagus sekali... Akhirnya kau bisa tenang!",
  ui_story_5014_50141602_3_dialog_content = "Jangan bergerak. Istirahatlah...",
  ui_story_5014_50141602_4_dialog_content = "Butler, tolong periksa adikku!",
  ui_story_5014_50141602_5_dialog_content = "<color=#e8d9bb>Diterima... Memulai... Pemeriksaan...</color>",
  ui_story_5014_50141602_6_dialog_content = "Maaf, kami terpaksa bertindak...",
  ui_story_5014_50141602_7_dialog_content = "Apa kami melukai kalian?",
  ui_story_5014_50141602_8_dialog_content = "Aku baik-baik saja... Tapi, adikku membenci kalian, jadi tolong jangan dekat-dekat dengannya...",
  ui_story_5014_50141602_9_dialog_content = "Dia mudah tersinggung... Tersulut.",
  ui_story_5014_50141602_10_dialog_content = "Baiklah. Sekarang dia sudah tenang, dan kami tak akan dekat-dekat dengannya.",
  ui_story_5014_50141602_11_dialog_content = "<color=#e8d9bb>*Gruk*</color>",
  ui_story_5014_50141602_12_dialog_content = "Valencia, gempanya muncul lagi. Ini gawat...",
  ui_story_5014_50141602_13_dialog_content = "Aku ingin membaca catatan ayah... Beri aku waktu sebentar saja.",
  ui_story_5014_50141602_14_dialog_content = "Baiklah... Jangan khawatir. Tak perlu terburu-buru...",
  ui_story_5014_50141602_15_dialog_content = "Kalian tunggu saja di sana. Jangan mendekat ke arah kami, dan jangan pergi...",
  ui_story_5014_50141602_16_dialog_content = "Butler, suruh beberapa robot untuk mengawasi mereka... Ayo kita cari tempat yang aman.",
  ui_story_5014_50141602_17_dialog_content = "<color=#e8d9bb>Siap, laksanakan.</color>",
  ui_story_5014_50141602_18_dialog_content = "Valencia.",
  ui_story_5014_50141602_19_dialog_content = "Saat kau membaca pesan ini, Ayah takut Ayah sudah tak lagi berada di dekatmu.",
  ui_story_5014_50141602_20_dialog_content = "Ayah tak tahu bagaimana Ayah akan pergi. Apa pun itu, pastinya bukan karena keinginan Ayah sendiri.",
  ui_story_5014_50141602_21_dialog_content = "Karena Ayah tak pernah ingin meninggalkanmu.",
  ui_story_5014_50141602_22_dialog_content = "Tapi, dunia maupun takdir tak berpihak kepada kita.",
  ui_story_5014_50141602_23_dialog_content = "Ayah dan ibumu... Kami sudah menghadapi banyak rintangan, dan suatu kali kami bahkan nyaris menyerah.",
  ui_story_5014_50141602_24_dialog_content = "Tapi, semua berubah saat kau hadir dalam hidup kami.",
  ui_story_5014_50141602_25_dialog_content = "Setiap kali Ayah melihat senyummu, keyakinan Ayah pun tumbuh lagi—",
  ui_story_5014_50141602_26_dialog_content = "Ayah harus membuat hidupmu lebih baik.",
  ui_story_5014_50141602_27_dialog_content = "Sekarang, mungkin kau sudah meninggalkan \"rumah\" dan menginjakkan kaki di tanah yang luas dan nyata.",
  ui_story_5014_50141602_28_dialog_content = "Atau, mungkin kau masih terus bertahan... Melindungi adik dan ibumu.",
  ui_story_5014_50141602_29_dialog_content = "Apa pun itu, kau sudah berusaha dengan baik, Valencia. Ayah akan selalu bangga padamu.",
  ui_story_5014_50141602_30_dialog_content = "Kalau kau berhasil keluar dari sana, Ayah akan merasa sangat lega sekaligus khawatir.",
  ui_story_5014_50141602_31_dialog_content = "Kau akan bisa melihat gunung dan sungai, danau dan laut... berjalan di padang rumput yang berubah seiring pergantian musim, dan melihat matahari terbit dan terbenam di cakrawala.",
  ui_story_5014_50141602_32_dialog_content = "Kau akan bisa bergandengan tangan dengan adik dan ibumu, membangun rumah baru, membuat pakaian baru, dan Ayah bahkan akan bisa mencium aroma masakan kalian.",
  ui_story_5014_50141602_33_dialog_content = "Kau pasti akan ingin memandangi langit yang nyata, siang maupun malam.",
  ui_story_5014_50141602_34_dialog_content = "Tapi, kau juga akan menyaksikan kegelapan.",
  ui_story_5014_50141602_35_dialog_content = "Dingin yang menggigit, deru angin, dan musuh yang lebih mengerikan daripada yang kaubayangkan.",
  ui_story_5014_50141602_36_dialog_content = "Tapi, mereka tak akan bisa mengalahkanmu, Valencia.",
  ui_story_5014_50141602_37_dialog_content = "Karena saat kau membaca surat ini, kau pasti sudah dewasa.",
  ui_story_5014_50141602_38_dialog_content = "Rekan-rekan Ayah sesama warga Illumina pasti akan menemukanmu dan menerimamu.",
  ui_story_5014_50141602_39_dialog_content = "Kau akan lihat bahwa kita adalah satu keluarga besar.",
  ui_story_5014_50141602_40_dialog_content = "Mungkin saja kau, seperti halnya Ayah dan ibumu, setelah melewati kesulitan yang tak terhitung banyaknya...",
  ui_story_5014_50141602_41_dialog_content = "Akhirnya bisa menemukan orang-orang yang selalu ada untukmu, dan menemukan rumah baru.",
  ui_story_5014_50141602_42_dialog_content = "Ah, omong-omong tentang itu, Ayah jadi agak gugup...",
  ui_story_5014_50141602_43_dialog_content = "Orang yang akan menjagamu pada saat itu? Ayah juga ingin melihatnya.",
  ui_story_5014_50141602_44_dialog_content = "Ayah bersedia memberikan apa pun asalkan masa depan itu bisa terwujud.",
  ui_story_5014_50141602_45_dialog_content = "Sayangnya, hidup kita masih ditentukan oleh orang lain...",
  ui_story_5014_50141602_46_dialog_content = "Tidak, dia lebih rumit daripada manusia... dia adalah AI kuno.",
  ui_story_5014_50141602_47_dialog_content = "Jika, sayangnya... Masa depan itu belum terwujud, kau harus ingat perkataan Ayah.",
  ui_story_5014_50141602_48_dialog_content = "Tempat ini hancur. Butler tak akan bisa menghentikannya.",
  ui_story_5014_50141602_49_dialog_content = "Jika keadaan mulai memburuk, pegang tangan orang-orang di sekitarmu dan hadapilah bersama-sama.",
  ui_story_5014_50141602_50_dialog_content = "Karena dengan begitu, kota ini tidak akan lagi menjadi rumahmu. Rumah adalah tempat dirimu dan orang-orang di sekitarmu berada...",
  ui_story_5014_50141602_51_dialog_content = "\"... Itulah yang disebut rumah.\"",
  ui_story_5014_50141602_52_dialog_content = "Ayah...",
  ui_story_5014_50141602_53_dialog_content = "Gretel, aku akan memercayai mereka sekali lagi...",
  ui_story_5014_50141602_54_dialog_content = "Gretel? Butler? Di mana kalian?",
  ui_story_5014_50141602_55_dialog_content = "Siobhan...",
  ui_story_5014_50141602_56_dialog_content = "Bagus, kau sudah keluar.",
  ui_story_5014_50141602_57_dialog_content = "Aku merasakan Gretel pergi. Tadinya kukira kalian...",
  ui_story_5014_50141602_58_dialog_content = "Gretel pergi dengan Butler... Dia tidak memberitahuku.",
  ui_story_5014_50141602_59_dialog_content = "<color=#e8d9bb>*Gruk*</color>",
  ui_story_5014_50141602_60_dialog_content = "<color=#e8d9bb>*Bum—bum*</color>",
  ui_story_5014_50141602_61_dialog_content = "Lihat, langitnya...",
  ui_story_5014_50141602_62_dialog_content = "Sudah dimulai... Undercity mulai hancur.",
  ui_story_5014_50141602_63_dialog_content = "Ayah bilang \"tempat ini hancur\"... Langitnya...",
  ui_story_5014_50141602_64_dialog_content = "Langitnya terlihat seperti layar yang dibuat oleh Ancient, dan itu menjadi kubah Undercity.",
  ui_story_5014_50141602_65_dialog_content = "Tak lama lagi kubah itu pasti roboh, seperti bangunan-bangunan di sini...",
  ui_story_5014_50141602_66_dialog_content = "Roboh dalam reruntuhan... lalu terkubur selamanya.",
  ui_story_5014_50141602_67_dialog_content = "Tapi, ayahmu tidak ingin kau dan Gretel ikut terkubur di sini...",
  ui_story_5014_50141602_68_dialog_content = "Jadi, dia terus mencari jalan keluar, berusaha memperbaiki inti itu, dan terus-terusan mengirim pesan ke dunia luar...",
  ui_story_5014_50141602_69_dialog_content = "Tapi, Butler selalu berusaha menghentikannya.",
  ui_story_5014_50141602_70_dialog_content = "Agar tidak ketahuan Butler, dia tidak bisa mencoba semua ini secara terang-terangan.",
  ui_story_5014_50141602_71_dialog_content = "Bahkan hal ini pun tak bisa dia beri tahukan kepadamu secara langsung.",
  ui_story_5014_50141602_72_dialog_content = "Valencia, ajak Gretel dan ikutlah dengan kami.",
  ui_story_5014_50141602_73_dialog_content = "Tapi, Gretel... Dia memilih untuk pergi dengan Butler.",
  ui_story_5014_50141602_74_dialog_content = "Dia pergi begitu saja...",
  ui_story_5014_50141602_75_dialog_content = "Mungkin Butler berbohong padanya, tapi dia membutuhkanmu sekarang... Valencia.",
  ui_story_5014_50141602_76_dialog_content = "Valencia, kau adalah kakaknya. Aku tahu kau pasti kesulitan menjaganya sendirian selama ini.",
  ui_story_5014_50141602_77_dialog_content = "Tapi, kau harus bertanggung jawab... Jelaskan padanya mana yang benar dan salah.",
  ui_story_5014_50141602_78_dialog_content = "Benar, kau harus bertanggung jawab atas adikmu. Jangan serahkan dia pada Butler.",
  ui_story_5014_50141602_79_dialog_content = "Aku...",
  ui_story_5014_50141602_80_dialog_content = "Aku tahu kau sudah berusaha semampumu...",
  ui_story_5014_50141602_81_dialog_content = "Merawat seseorang bukan hal yang mudah, apalagi jika tidak punya pengalaman.",
  ui_story_5014_50141602_82_dialog_content = "Tapi, sekarang kau harus mencoba membujuknya.",
  ui_story_5014_50141602_83_dialog_content = "Jangan biarkan dia mengabaikan apa yang terjadi dan mengasingkan diri dari orang lain.",
  ui_story_5014_50141602_84_dialog_content = "Kau setuju dengan perkataanku?",
  ui_story_5014_50141602_85_dialog_content = "I-iya... Kurasa begitu.",
  ui_story_5014_50141602_86_dialog_content = "Sekarang kita harus menemukannya. Aku khawatir terjadi sesuatu padanya.",
  ui_story_5014_50141602_87_dialog_content = "Hmm... Aku punya ide...",
  ui_story_5014_50141602_88_dialog_content = "Ayah memberiku sensor... Aku bisa menggunakannya untuk mendeteksi keberadaannya.",
  ui_story_5014_50141701_1_dialog_content = "Sial. Gempa lagi. Ada yang salah dengan sensor sinyalnya.",
  ui_story_5014_50141701_2_dialog_content = "Akan kucoba menyesuaikannya. Sebentar.",
  ui_story_5014_50141701_3_dialog_content = "Bagaimana? Butuh bantuan?",
  ui_story_5014_50141701_4_dialog_content = "Tidak... Aku bisa memperbaikinya. Tunggu sebentar.",
  ui_story_5014_50141701_5_dialog_content = "Akan kucoba mencari sinyal di sana. Tunggu aku.",
  ui_story_5014_50141701_6_dialog_content = "Kalau begitu, kami ikut...",
  ui_story_5014_50141701_7_dialog_content = "Kau takut aku bakal kabur? Tenang saja, aku tak akan pergi.",
  ui_story_5014_50141701_8_dialog_content = "Tapi...",
  ui_story_5014_50141701_9_dialog_content = "Carleen, biarkan saja.",
  ui_story_5014_50141701_10_dialog_content = "Pergilah, Valencia. Kami akan menunggumu di sini.",
  ui_story_5014_50141701_11_dialog_content = "Baiklah.",
  ui_story_5014_50141701_12_dialog_content = "Siobhan, apa benar tidak apa-apa dia pergi sendirian?",
  ui_story_5014_50141701_13_dialog_content = "Memangnya mencari sinyal sendirian itu perlu?",
  ui_story_5014_50141701_14_dialog_content = "Kepercayaan menghasilkan kepercayaan... Mungkin dia hanya ingin menyendiri sebentar.",
  ui_story_5014_50141701_15_dialog_content = "Atau mungkin dia hanya menguji kita.",
  ui_story_5014_50141701_16_dialog_content = "Cara berpikir anak-anak sangat sederhana. Aku tak mau meragukannya.",
  ui_story_5014_50141701_17_dialog_content = "Selain itu... Caelestite kita ini juga punya kemampuan mendeteksi.",
  ui_story_5014_50141701_18_dialog_content = "Yah, asalkan dia tidak pergi terlalu jauh, aku bisa merasakannya.",
  ui_story_5014_50141701_19_dialog_content = "Dia tidak jauh...",
  ui_story_5014_50141701_20_dialog_content = "Hmm... Bagaimana kalau Valencia tahu? Apa dia tidak akan mengira sudah ditipu lagi?",
  ui_story_5014_50141701_21_dialog_content = "Mendapatkan kepercayaannya tidaklah mudah, dan aku tak ingin...",
  ui_story_5014_50141701_22_dialog_content = "*Batuk-batuk* Jangan dibahas lagi...",
  ui_story_5014_50141701_23_dialog_content = "*Menghela napas* Meyakinkan mereka memang sulit, terutama mengingat cara Seamus menyampaikan pesannya.",
  ui_story_5014_50141701_24_dialog_content = "Siobhan, tadi katamu Seamus berusaha agar \"tidak ketahuan Butler\", 'kan?",
  ui_story_5014_50141701_25_dialog_content = "Benar, itu sebabnya dia membagi pesannya dalam beberapa bagian dan mengenkripsinya demi keamanan informasi itu.",
  ui_story_5014_50141701_26_dialog_content = "Bahkan kalau Butler mendapatkannya atau menghancurkan sebagian informasi itu, sisanya pun cukup.",
  ui_story_5014_50141701_27_dialog_content = "Seamus menggunakan banyak metode enkripsi dan kode rahasia.",
  ui_story_5014_50141701_28_dialog_content = "Nimbus bahkan menulis pesannya menggunakan steganografi.",
  ui_story_5014_50141701_29_dialog_content = "Semua itu agar Butler tidak bisa membacanya.",
  ui_story_5014_50141701_30_dialog_content = "Benar sekali.",
  ui_story_5014_50141701_31_dialog_content = "Sebenarnya, ada cara lain untuk menyikapinya.",
  ui_story_5014_50141701_32_dialog_content = "Dari sudut pandang orang tua... Mereka tidak tahu apakah anak-anak itu siap menghadapi semua ini.",
  ui_story_5014_50141701_33_dialog_content = "Mereka juga tidak tahu orang macam apa yang akan anak-anak itu temui.",
  ui_story_5014_50141701_34_dialog_content = "Bahkan jika mereka sudah berusaha semampunya untuk mengajari kakak beradik itu cara membedakan baik dan buruk...",
  ui_story_5014_50141701_35_dialog_content = "Masih ada kemungkinan mereka tidak akan bisa membedakan siapa yang baik dan jahat.",
  ui_story_5014_50141701_36_dialog_content = "Lagi pula, semua orang bisa berbohong.",
  ui_story_5014_50141701_37_dialog_content = "Selalu bersikap skeptis dan mengumpulkan informasi dari berbagai sudut pandang akan membuat seseorang tetap waspada dan siap.",
  ui_story_5014_50141701_38_dialog_content = "Aku yakin begitulah yang Seamus ajarkan kepada kakak beradik itu.",
  ui_story_5014_50141701_39_dialog_content = "Mesin juga bisa berbohong, tapi Gretel tak pernah meragukannya.",
  ui_story_5014_50141701_40_dialog_content = "Gretel masih terlalu kecil saat ayah dan ibunya tewas...",
  ui_story_5014_50141701_41_dialog_content = "Profesor Siobhan, apa kau punya anak?",
  ui_story_5014_50141701_42_dialog_content = "*Batuk-batuk hebat*",
  ui_story_5014_50141701_43_dialog_content = "Maaf, entah kenapa aku tersedak... Kenapa tiba-tiba kamu tanya begitu?",
  ui_story_5014_50141701_44_dialog_content = "Maaf... Aku hanya berpikir perkataan Profesor Siobhan sangat masuk akal.",
  ui_story_5014_50141701_45_dialog_content = "Tampaknya dia paham seperti apa rasanya menjadi orang tua...",
  ui_story_5014_50141701_46_dialog_content = "Tentu saja tidak, tapi aku pernah mengalami hal yang sama... mendengarkan pesan terakhir kelima rekan timku.",
  ui_story_5014_50141701_47_dialog_content = "Intinya, mereka berpesan agar kami memanfaatkan penelitian dengan baik atau melindungi keluarga mereka.",
  ui_story_5014_50141701_48_dialog_content = "Beberapa tidak ingin kami mengabarkan kematian mereka kepada keluarga mereka...",
  ui_story_5014_50141701_49_dialog_content = "Beberapa bahkan ingin keluarga mereka melupakan mereka...",
  ui_story_5014_50141701_50_dialog_content = "Profesor Siobhan...",
  ui_story_5014_50141701_51_dialog_content = "Inilah masalah yang sebenarnya. Mungkin suatu hari nanti kau akan mengerti...",
  ui_story_5014_50141701_52_dialog_content = "Aku hanya berharap kau tak pernah terpaksa menghadapi situasi ini, tapi ekspedisi selalu penuh dengan bahaya.",
  ui_story_5014_50141701_53_dialog_content = "Jadi, kau harus selalu tetap waspada.",
  ui_story_5014_50141701_54_dialog_content = "Benar, kami akan selalu mengingatnya.",
  ui_story_5014_50141701_55_dialog_content = "<size=33>Keluarga...</size>",
  ui_story_5014_50141701_56_dialog_content = "Kau baik-baik saja, PlayerName?",
  ui_story_5014_50141701_57_dialog_content = "Aku baru saja... teringat sesuatu.",
  ui_story_5014_50141701_58_dialog_content = "Kita harus membawa Valencia dan Gretel keluar dari sini—keluar dari bawah tanah.",
  ui_story_5014_50141701_59_dialog_content = "Dan melihat dunia luar...",
  ui_story_5014_50141701_60_dialog_content = "Ya, kamu benar...",
  ui_story_5014_50141701_61_dialog_content = "Yah, kurasa kita sudah cukup mengobrol. Vice, hubungi Florine dan yang lain.",
  ui_story_5014_50141701_62_dialog_content = "Ayo kita dengar laporan mereka.",
  ui_story_5014_50141701_63_dialog_content = "Baiklah.",
  ui_story_5014_50141701_64_dialog_content = "Siobhan, aku menemukan adikku.",
  ui_story_5014_50141701_65_dialog_content = "Dia menuju ke dalam kota... Butler pasti telah membawanya ke sana.",
  ui_story_5014_50141701_66_dialog_content = "Dalam kota... Florine dan yang lain pasti juga mencari pintu masuk ke tempat itu.",
  ui_story_5014_50141701_67_dialog_content = "Kita mendapat kabar terbaru!",
  ui_story_5014_50141701_68_dialog_content = "Florine bilang mereka menemukan pintu masuk dan jalan yang tepat.",
  ui_story_5014_50141701_69_dialog_content = "Mereka baru saja lolos dari kejaran pasukan robot dan Eclipsite, dan mengirim koordinatnya.",
  ui_story_5014_50141701_70_dialog_content = "Valencia, ayo kita gunakan jalan yang tadi dilalui Florine dan yang lain. Kita harus menemui mereka dulu.",
  ui_story_5014_50141701_71_dialog_content = "Tentu saja... tapi aku khawatir Butler akan mengirim lebih banyak robot untuk menghentikan mereka.",
  ui_story_5014_50141701_72_dialog_content = "Kalau aku bersama mereka, para robot itu tak akan menyerang... Semua orang akan lebih aman.",
  ui_story_5014_50141701_73_dialog_content = "Terima kasih, Valencia.",
  ui_story_5014_50141701_74_dialog_content = "Tidak perlu berterima kasih. Lagi pula, ini tanggung jawabku... Ayo kita pergi.",
  ui_story_5014_50141701_75_dialog_content = "Baiklah, tunjukkan jalannya!",
  ui_story_5014_50141701_76_dialog_content = "Teman-teman, lokasinya ada di depan sana. Kita hampir sampai.",
  ui_story_5014_50141701_77_dialog_content = "Ini adalah lokasi terakhir Florine yang diketahui.",
  ui_story_5014_50141701_78_dialog_content = "Ini jalan menuju sistem kendali dan inti energi, 'kan?",
  ui_story_5014_50141701_79_dialog_content = "Benar. Pasti ada jalan keluar dari Undercity ini, dan...",
  ui_story_5014_50141701_80_dialog_content = "Dan sains serta teknologi yang selalu kamu impikan?",
  ui_story_5014_50141701_81_dialog_content = "Iya.",
  ui_story_5014_50141701_82_dialog_content = "Siobhan.",
  ui_story_5014_50141701_83_dialog_content = "Ada apa, Valencia?",
  ui_story_5014_50141701_84_dialog_content = "Sejujurnya, aku bukan... murid terbaik ayahku.",
  ui_story_5014_50141701_85_dialog_content = "Kenapa kamu bilang begitu...?",
  ui_story_5014_50141701_86_dialog_content = "Karena aku belum benar-benar menguasai... teknik yang ayahku ajarkan.",
  ui_story_5014_50141701_87_dialog_content = "Material-material itu... Kau boleh mengambilnya.",
  ui_story_5014_50141701_88_dialog_content = "Kau boleh membawanya kembali ke Illumina untuk diteliti.",
  ui_story_5014_50141701_89_dialog_content = "Baiklah, aku mengerti.",
  ui_story_5014_50141701_90_dialog_content = "Tapi, Gretel... Perkataan atau perbuatannya...",
  ui_story_5014_50141701_91_dialog_content = "Tolong jangan diambil hati.",
  ui_story_5014_50141701_92_dialog_content = "Aku ingin meminta maaf atas nama Gretel... Untuk segala perbuatan dan perkataannya.",
  ui_story_5014_50141701_93_dialog_content = "Aku akan berusaha semampuku untuk membujuknya.",
  ui_story_5014_50141701_94_dialog_content = "Aku berjanji sebagai warga Illumina—",
  ui_story_5014_50141701_95_dialog_content = "Kita akan bergandengan tangan... Kita semua... Seperti yang ayahmu harapkan.",
  ui_story_5014_50141701_96_dialog_content = "Mari kita selesaikan masalah ini dan pergi dari Undercity bersama-sama.",
  ui_story_5014_50141701_97_dialog_content = "<color=#e8d9bb>*Gruk*</color>",
  ui_story_5014_50141701_98_dialog_content = "Lagi-lagi gempa...",
  ui_story_5014_50141701_99_dialog_content = "Tidak, yang ini berbeda!",
  ui_story_5014_50141701_100_dialog_content = "Perhatikan pijakan kakimu!",
  ui_story_5014_50141701_101_dialog_content = "<color=#e8d9bb>*Gruk*</color>",
  ui_story_5014_50141701_102_dialog_content = "K-kamu...?",
  ui_story_5014_50141701_103_dialog_content = "<color=#e8d9bb>Salam... Aku pengelola tempat perlindungan bawah tanah ini.</color>",
  ui_story_5014_50141701_104_dialog_content = "<color=#e8d9bb>Panggil aku Butler.</color>"
}
return config
